INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(1, 'abandon', 2, '/əˈbæn.dən/', 'To give up or relinquish control of, to surrender or to give oneself over, or to yield to one\'s emotions.', '拋棄、放棄', 'https://api.dictionaryapi.dev/media/pronunciations/en/abandon-us.mp3', 1, '2026-06-01 14:48:14'),
(2, 'abbreviation', 1, '/əˌbɹiː.viˈeɪ.ʃən/', 'The result of shortening or reducing; abridgment.', '縮寫、節略、縮短', 'https://api.dictionaryapi.dev/media/pronunciations/en/abbreviation-uk.mp3', 1, '2026-06-01 14:48:14'),
(3, 'abide', 2, '/əˈbaɪd/', 'To endure without yielding; to withstand; await defiantly; to encounter; to persevere.', '忍受、遵守、堅持', 'https://api.dictionaryapi.dev/media/pronunciations/en/abide-us.mp3', 1, '2026-06-01 14:48:14'),
(4, 'ability', 1, '/əˈ.bɪl.ɪ.ti/', 'Suitableness.', '能力、才能', 'https://api.dictionaryapi.dev/media/pronunciations/en/ability-us.mp3', 1, '2026-06-01 14:48:14'),
(5, 'able', 3, '/ˈeɪ.bl̩/', 'Easy to use.', '有能力的、能幹的、易用的', 'https://api.dictionaryapi.dev/media/pronunciations/en/able-us.mp3', 1, '2026-06-01 14:48:14'),
(6, 'abnormal', 3, '/əbˈnɔɹ.ml̩/', 'Not conforming to rule or system; deviating from the usual or normal type.', '異常的、不正常的', 'https://api.dictionaryapi.dev/media/pronunciations/en/abnormal-us.mp3', 1, '2026-06-01 14:48:14'),
(7, 'aboard', 4, '/əˈbɔːd/', 'On board; into or within a ship or boat; hence, into or within a railway car.', '在船上、在火車上、在飛機上', 'https://api.dictionaryapi.dev/media/pronunciations/en/aboard-us.mp3', 1, '2026-06-01 14:48:14'),
(8, 'aboard', 5, '/əˈbɔːd/', 'On board of; onto or into a ship, boat, train, plane.', '在...之上、搭乘（船、機、車）', 'https://api.dictionaryapi.dev/media/pronunciations/en/aboard-us.mp3', 1, '2026-06-01 14:48:14'),
(9, 'abolish', 2, '/əˈbɒlɪʃ/', 'To end a law, system, institution, custom or practice.', '廢除、革除、消滅', 'https://api.dictionaryapi.dev/media/pronunciations/en/abolish-us.mp3', 1, '2026-06-01 14:48:14'),
(10, 'abolition', 1, '/ˌæb.əˈlɪʃ.n̩/', 'The act of abolishing; an annulling; abrogation', '廢除、革除', 'https://api.dictionaryapi.dev/media/pronunciations/en/abolition-au.mp3', 1, '2026-06-01 14:48:14'),
(11, 'aboriginal', 3, '/ˌæb.əˈɹɪd͡ʒ.n̩.l̩/', 'Of or pertaining to Australian Aboriginal peoples, Aborigines, or their language.', '土著的、原本的、原住民的', 'https://api.dictionaryapi.dev/media/pronunciations/en/aboriginal-uk.mp3', 1, '2026-06-01 14:48:14'),
(12, 'aborigine', 1, '/ˌæb.əˈɹɪdʒ.ɪ.ni/', 'A native inhabitant of a country; a member of the original people.', '土著、原住民', 'https://api.dictionaryapi.dev/media/pronunciations/en/aborigine-us.mp3', 1, '2026-06-01 14:48:14'),
(13, 'abortion', 1, '/əˈbɔɹ.ʃn̩/', 'The expulsion from the womb of a foetus or embryo before it is fully developed, with loss of the foetus; either naturally as a spontaneous abortion (now usually called a miscarriage), or deliberately as an induced abortion.', '墮胎、流產、失敗', 'https://api.dictionaryapi.dev/media/pronunciations/en/abortion-us.mp3', 1, '2026-06-01 14:48:14'),
(14, 'about', 4, '/əˈbɛʊt/', 'On all sides; around.', '大約、周圍、到處', 'https://api.dictionaryapi.dev/media/pronunciations/en/about-us.mp3', 1, '2026-06-01 14:48:14'),
(15, 'about', 5, '/əˈbɛʊt/', 'In a circle around; all round; on every side of; on the outside of.', '關於、在...周圍', 'https://api.dictionaryapi.dev/media/pronunciations/en/about-us.mp3', 1, '2026-06-01 14:48:14'),
(16, 'above', 3, '/əˈbʌv/', 'Of heaven; heavenly.', '上述的、上面的', 'https://api.dictionaryapi.dev/media/pronunciations/en/above-us.mp3', 1, '2026-06-01 14:48:14'),
(17, 'above', 4, '/əˈbʌv/', 'Directly overhead; vertically on top of.', '在上方、在上文', 'https://api.dictionaryapi.dev/media/pronunciations/en/above-us.mp3', 1, '2026-06-01 14:48:14'),
(18, 'above', 5, '/əˈbʌv/', 'Physically over; on top of; worn on top of, said of clothing.', '在...之上、高於', 'https://api.dictionaryapi.dev/media/pronunciations/en/above-us.mp3', 1, '2026-06-01 14:48:14'),
(19, 'abroad', 4, '/əˈbɹɔːd/', 'Beyond the bounds of a country; in foreign countries.', '在國外、到國外、廣為流傳', 'https://api.dictionaryapi.dev/media/pronunciations/en/abroad-us.mp3', 1, '2026-06-01 14:48:14'),
(20, 'abrupt', 3, '/aˈbɹʌpt/', 'Broken away (from restraint).', '突然的、唐突的、陡峭的', 'https://api.dictionaryapi.dev/media/pronunciations/en/abrupt-us.mp3', 1, '2026-06-01 14:48:14'),
(21, 'absence', 1, '/ˈæb.s(ə)n̩s/', 'A state of being away or withdrawn from a place or from companionship; the period of being away.', '缺席、缺乏、不在場', 'https://api.dictionaryapi.dev/media/pronunciations/en/absence-us.mp3', 1, '2026-06-01 14:48:14'),
(22, 'absent', 3, '/ˈæb.sn̩t/', 'Being away from a place; withdrawn from a place; not present; missing.', '缺席的、缺乏的、心不在焉的', 'https://api.dictionaryapi.dev/media/pronunciations/en/absent-1-us.mp3', 1, '2026-06-01 14:48:14'),
(23, 'absolute', 3, '/ˈæb.səˌljuːt/', 'Free of restrictions, limitations, qualifications or conditions; unconditional.', '絕對的、完全的', 'https://api.dictionaryapi.dev/media/pronunciations/en/absolute-uk.mp3', 1, '2026-06-01 14:48:14'),
(24, 'absorb', 2, '/əbˈsɔːb/', 'To include so that it no longer has separate existence; to overwhelm; to cause to disappear as if by swallowing up; to incorporate; to assimilate; to take in and use up.', '吸收、吸引、承受', 'https://api.dictionaryapi.dev/media/pronunciations/en/absorb-us.mp3', 1, '2026-06-01 14:48:14'),
(25, 'absorbing', 3, '/əbˈsɔː.bɪŋ/', 'Engrossing, that sustains someone\'s interest.', '引人入勝的、迷人的', 'https://api.dictionaryapi.dev/media/pronunciations/en/absorbing-us.mp3', 1, '2026-06-01 14:48:14'),
(26, 'abstract', 3, '/ˈæbˌstɹækt/', 'Derived; extracted.', '抽象的、深奧的', 'https://api.dictionaryapi.dev/media/pronunciations/en/abstract-uk.mp3', 1, '2026-06-01 14:48:14'),
(27, 'abstraction', 1, '/əbˈstɹæk.ʃn̩/', 'The act of abstracting, separating, withdrawing, or taking away; withdrawal; the state of being taken away.', '抽象概念、分心、提取', 'https://api.dictionaryapi.dev/media/pronunciations/en/abstraction-us.mp3', 1, '2026-06-01 14:48:14'),
(28, 'absurd', 3, '/æbˈzɝd/', 'Contrary to reason or propriety; obviously and flatly opposed to manifest truth; inconsistent with the plain dictates of common sense; logically contradictory; nonsensical; ridiculous; silly.', '荒謬的、不合理的、可笑的', 'https://api.dictionaryapi.dev/media/pronunciations/en/absurd-us.mp3', 1, '2026-06-01 14:48:14'),
(29, 'abundance', 1, '/əˈbʌn.dn̩s/', 'A large quantity; many.', '豐富、充裕、大量', 'https://api.dictionaryapi.dev/media/pronunciations/en/abundance-us.mp3', 1, '2026-06-01 14:48:14'),
(30, 'academic', 3, '/ˌækəˈdɛmɪk/', 'Belonging to the school or philosophy of Plato', '學術的、學院的', 'https://api.dictionaryapi.dev/media/pronunciations/en/academic-us.mp3', 1, '2026-06-01 14:48:14'),
(31, 'acceleration', 1, '/æk.ˌsɛl.ə.ˈɹeɪ.ʃən/', 'The act of accelerating, or the state of being accelerated; increase of motion or action; as opposed to retardation or deceleration.', '加速度、促進', 'https://api.dictionaryapi.dev/media/pronunciations/en/acceleration-us.mp3', 1, '2026-06-01 14:48:14'),
(32, 'accept', 1, '/ækˈsɛpt/', 'To receive, especially with a consent, with favour, or with approval.', '接受、贊同（名詞型態之語意）', 'https://api.dictionaryapi.dev/media/pronunciations/en/accept-uk.mp3', 1, '2026-06-01 14:48:14'),
(33, 'accept', 2, '/ækˈsɛpt/', 'To receive, especially with a consent, with favour, or with approval.', '接受、認可、承擔', 'https://api.dictionaryapi.dev/media/pronunciations/en/accept-uk.mp3', 1, '2026-06-01 14:48:14'),
(34, 'acceptable', 3, '/æk.ˈsɛp.tə.bəl/', 'Worthy, decent, sure of being accepted or received with at least moderate pleasure', '可接受的、令人滿意的', 'https://api.dictionaryapi.dev/media/pronunciations/en/acceptable-us.mp3', 1, '2026-06-01 14:48:14'),
(35, 'acceptance', 1, '/ək.ˈsɛp.təns/', 'The act of accepting; a receiving of something offered, with acquiescence, approbation, or satisfaction; especially, favourable reception; approval.', '接受、贊同、容忍', 'https://api.dictionaryapi.dev/media/pronunciations/en/acceptance-au.mp3', 1, '2026-06-01 14:48:14'),
(36, 'accessible', 3, '/əkˈsɛs.ə.bəl/', 'Easy of access or approach.', '可接近的、可進入的、易上手的', 'https://api.dictionaryapi.dev/media/pronunciations/en/accessible-uk.mp3', 1, '2026-06-01 14:48:14'),
(37, 'accessory', 1, '/ækˈsɛs(ə)ɹi/', 'Having a secondary, supplementary or subordinate function by accompanying as a subordinate; aiding in a secondary way; being additional; being connected as an incident or subordinate to a principal; contributing or being contributory. Said of people and things, and, when of people, usually in a bad sense', '配件、飾品、從犯', 'https://api.dictionaryapi.dev/media/pronunciations/en/accessory-us.mp3', 1, '2026-06-01 14:48:14'),
(38, 'accident', 1, '/ˈæk.sə.dənt/', 'An unexpected event with negative consequences occurring without the intention of the one suffering the consequences.', '意外、事故、偶然的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/accident-us.mp3', 1, '2026-06-01 14:48:14'),
(39, 'accidental', 3, '/ˌæk.sɪ.ˈdɛn.tl̩/', 'Not essential; incidental, secondary.', '偶然的、意外的', 'https://api.dictionaryapi.dev/media/pronunciations/en/accidental-us.mp3', 1, '2026-06-01 14:48:14'),
