(219, 'alternatively', 4, '', 'In an alternative way', '或者、另類地', 'https://dictionaryapi.dev/alternatively', 1, '2026-06-01 14:48:14'),
(220, 'although', 6, '/ɔːlˈðəʊ/', 'Though, even though, in spite of or despite the fact that: introducing a clause that expresses a concession.', '雖然、儘管', 'https://api.dictionaryapi.dev/media/pronunciations/en/although-us.mp3', 1, '2026-06-01 14:48:14'),
(221, 'altitude', 1, '/ˈælt.ɪˌtjuːd/', 'The absolute height of a location, usually measured from sea level.', '高度、海拔', 'https://api.dictionaryapi.dev/media/pronunciations/en/altitude-uk.mp3', 1, '2026-06-01 14:48:14'),
(222, 'altogether', 4, '/ɔː.tuːˈɡɛð.ə(ɹ)/', 'Without exception; wholly; completely.', '完全、總共', 'https://api.dictionaryapi.dev/media/pronunciations/en/altogether-us.mp3', 1, '2026-06-01 14:48:14'),
(223, 'aluminum', 1, '/ə.ˈluː.mɨ.nəm/', 'A metallic chemical element (symbol Al) with an atomic number of 13.', '鋁', 'https://api.dictionaryapi.dev/media/pronunciations/en/aluminum-uk.mp3', 1, '2026-06-01 14:48:14'),
(224, 'always', 4, '/ˈɔː(l).weɪz/', 'At all times; throughout all time; since the beginning.', '總是、永遠', 'https://api.dictionaryapi.dev/media/pronunciations/en/always-uk.mp3', 1, '2026-06-01 14:48:14'),
(225, 'amateur', 1, '/ˈæ.mə.tə/', 'A lover of something.', '業餘愛好者', 'https://api.dictionaryapi.dev/media/pronunciations/en/amateur-us.mp3', 1, '2026-06-01 14:48:14'),
(226, 'amateur', 3, '/ˈæ.mə.tə/', 'Non-professional.', '業餘的、外行的', 'https://api.dictionaryapi.dev/media/pronunciations/en/amateur-us.mp3', 1, '2026-06-01 14:48:14'),
(227, 'amaze', 1, '/əˈmeɪz/', 'Amazement, astonishment.', '吃驚、驚奇（此處依名詞語意翻譯）', 'https://api.dictionaryapi.dev/media/pronunciations/en/amaze-us.mp3', 1, '2026-06-01 14:48:14'),
(228, 'amaze', 2, '/əˈmeɪz/', 'To fill with wonder and surprise; to astonish, astound, surprise or perplex.', '使大吃驚、使驚奇', 'https://api.dictionaryapi.dev/media/pronunciations/en/amaze-us.mp3', 1, '2026-06-01 14:48:14'),
(229, 'amazing', 3, '/əˈmeɪzɪŋ/', 'Causing wonder and amazement; very surprising.', '令人驚奇的、極妙的', 'https://api.dictionaryapi.dev/media/pronunciations/en/amazing-us.mp3', 1, '2026-06-01 14:48:14'),
(230, 'ambassador', 1, '/æmˈbæs.ə.də(ɹ)/', 'A minister of the highest rank sent to a foreign court to represent there his sovereign or country. (Sometimes called ambassador-in-residence)', '大使、特使', NULL, 1, '2026-06-01 14:48:14'),
(231, 'ambiguity', 1, '/æmbɪˈɡjuːɪti/', 'Something, particularly words and sentences, that is open to more than one interpretation, explanation or meaning, if that meaning etc cannot be determined from its context.', '含糊、模稜兩可', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambiguity-us.mp3', 1, '2026-06-01 14:48:14'),
(232, 'ambiguous', 3, '/æmˈbɪɡjuəs/', 'Open to multiple interpretations.', '模稜兩可的、含糊的', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambiguous-us.mp3', 1, '2026-06-01 14:48:14'),
(233, 'ambition', 1, '/æmˈbɪ.ʃən/', 'Eager or inordinate desire for some object that confers distinction, as preferment, honor, superiority, political power, or literary fame; desire to distinguish one\'s self from other people.', '抱負、野心', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambition-us.mp3', 1, '2026-06-01 14:48:14'),
(234, 'ambitious', 3, '/æmˈbɪʃ.əs/', '(of a person or their character) Having or showing ambition; wanting a lot of power, honor, respect, superiority, or other distinction.', '有野心的、雄心勃勃的', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambitious-us.mp3', 1, '2026-06-01 14:48:14'),
(235, 'ambulance', 1, '/ˈæm.bjə.ləns/', 'An emergency vehicle designed for transporting seriously ill or injured people to a hospital.', '救護車', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambulance-us.mp3', 1, '2026-06-01 14:48:14'),
(236, 'ambush', 2, '/ˈæm.bʊʃ/', 'To station in ambush with a view to surprise an enemy.', '埋伏、伏擊', 'https://api.dictionaryapi.dev/media/pronunciations/en/ambush-uk.mp3', 1, '2026-06-01 14:48:14'),
(237, 'amend', 2, '/əˈmɛnd/', 'To make better; improve.', '修改、修訂、改善', '', 1, '2026-06-01 14:48:14'),
(238, 'amenna', 1, '', 'N/A', '阿門（宗教用語，原字通常為 amen，此處依名詞型態保留）', NULL, 1, '2026-06-01 14:48:14'),
(239, 'amid', 5, '/əˈmɪd/', 'In the middle of; in the center of; surrounded by.', '在...之中、在...深處', 'https://api.dictionaryapi.dev/media/pronunciations/en/amid-us.mp3', 1, '2026-06-01 14:48:14'),
(240, 'ammunition', 1, '/ˌæmjuˈnɪʃən/', 'Articles used in charging firearms and ordnance of all kinds; as powder, balls, shot, shells, percussion caps, rockets, etc.', '彈藥、軍火', 'https://api.dictionaryapi.dev/media/pronunciations/en/ammunition-us.mp3', 1, '2026-06-01 14:48:14'),
(241, 'amnesty', 1, '/ˈæm.nɪ.sti/', 'Forgetfulness; cessation of remembrance of wrong; oblivion.', '大赦、特赦', NULL, 1, '2026-06-01 14:48:14'),
(242, 'among', 5, '/əˈmɒŋ/', 'Denotes a mingling or intermixing with distinct or separable objects. (See Usage Note at amidst.)', '在...之中、在...之間', 'https://api.dictionaryapi.dev/media/pronunciations/en/among-us.mp3', 1, '2026-06-01 14:48:14'),
(243, 'amount', 1, '/əˈmaʊnt/', 'The total, aggregate or sum of material (not applicable to discrete numbers or units or items in standard English).', '數量、總額', 'https://api.dictionaryapi.dev/media/pronunciations/en/amount-us.mp3', 1, '2026-06-01 14:48:14'),
(244, 'amount', 2, '/əˈmaʊnt/', '(followed by to) To total or evaluate.', '總計、共達', 'https://api.dictionaryapi.dev/media/pronunciations/en/amount-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(245, 'amuse', 1, '/əˈmjuːz/', 'To entertain or occupy in a pleasant manner; to stir with pleasing emotions.', '娛樂、消遣（此處依名詞語意翻譯）', 'https://api.dictionaryapi.dev/media/pronunciations/en/amuse-uk.mp3', 1, '2026-06-01 14:48:14'),
(246, 'amuse', 2, '/əˈmjuːz/', 'To entertain or occupy in a pleasant manner; to stir with pleasing emotions.', '使快樂、逗...笑', 'https://api.dictionaryapi.dev/media/pronunciations/en/amuse-uk.mp3', 1, '2026-06-01 14:48:14'),
(247, 'analects', 1, '[ˈæ.nəˌlɛk(t)s]', 'A collection of excerpts or quotes.', '文選、語錄（常指《論語》）', NULL, 1, '2026-06-01 14:48:14'),
(248, 'analogy', 1, '/əˈnæləd͡ʒi/', 'A relationship of resemblance or equivalence between two situations, people, or objects, especially when used as a basis for explanation or extrapolation.', '類比、類推', 'https://api.dictionaryapi.dev/media/pronunciations/en/analogy-us.mp3', 1, '2026-06-01 14:48:14'),
(249, 'analysis', 1, '/əˈnælɪsɪs/', 'Decomposition into components in order to study (a complex thing, concept, theory etc.).', '分析', 'https://api.dictionaryapi.dev/media/pronunciations/en/analysis-us.mp3', 1, '2026-06-01 14:48:14'),
(250, 'analyst', 1, '/ˈænəlɪst/', 'Someone who analyzes.', '分析師', 'https://api.dictionaryapi.dev/media/pronunciations/en/analyst-us.mp3', 1, '2026-06-01 14:48:14'),
(251, 'ancestor', 1, '/ˈæn.sɛs.tə/', 'One from whom a person is descended, whether on the father\'s or mother\'s side, at any distance of time; a progenitor; a forefather.', '祖先、祖宗', 'https://api.dictionaryapi.dev/media/pronunciations/en/ancestor-us.mp3', 1, '2026-06-01 14:48:14'),
(252, 'ancestral', 3, '/ænˈsɛs.təɹ.əl/', 'Of, pertaining to, derived from, or possessed by, an ancestor or ancestors', '祖先的、祖傳的', NULL, 1, '2026-06-01 14:48:14'),
(253, 'anchor', 1, '/ˈæŋ.kə/', 'A tool used to moor a vessel to the bottom of a sea or river to resist movement.', '錨、主播、靠山', 'https://api.dictionaryapi.dev/media/pronunciations/en/anchor-us.mp3', 1, '2026-06-01 14:48:14'),
(254, 'ancient', 3, '/ˈeɪn.ʃənt/', 'Having lasted from a remote period; having been of long duration; of great age, very old.', '古代的、古老的', 'https://api.dictionaryapi.dev/media/pronunciations/en/ancient-us.mp3', 1, '2026-06-01 14:48:14'),
(255, 'anecdote', 1, '/ˈæ.nɪk.doʊt/', 'A short account of a real incident or person, often humorous or interesting.', '軼事、趣聞', 'https://api.dictionaryapi.dev/media/pronunciations/en/anecdote-us.mp3', 1, '2026-06-01 14:48:14'),
(256, 'angel', 1, '/ˈeɪn.dʒəl/', 'An incorporeal and sometimes divine messenger from a deity, or other divine entity, often depicted in art as a youthful winged figure in flowing robes.', '天使', 'https://api.dictionaryapi.dev/media/pronunciations/en/angel-uk.mp3', 1, '2026-06-01 14:48:14'),
(257, 'anger', 1, '/ˈæŋɡə(ɹ)/', 'A strong feeling of displeasure, hostility or antagonism towards someone or something, usually combined with an urge to harm.', '憤怒、生氣', 'https://api.dictionaryapi.dev/media/pronunciations/en/anger-us.mp3', 1, '2026-06-01 14:48:14'),
(258, 'angler', 1, '/ˈæŋ.ɡlə(ɹ)/', 'A person who fishes with a hook and line.', '釣魚者', NULL, 1, '2026-06-01 14:48:14'),
(259, 'angry', 3, '/ˈæŋ.ɡɹi/', 'Displaying or feeling anger.', '生氣的、憤怒的', 'https://api.dictionaryapi.dev/media/pronunciations/en/angry-us.mp3', 1, '2026-06-01 14:48:14'),
(260, 'angular', 3, '/-lɑɹ/', 'Relating or pertaining to an angle or angles.', '有角的、瘦骨嶙峋的、生硬的', 'https://api.dictionaryapi.dev/media/pronunciations/en/angular-us.mp3', 1, '2026-06-01 14:48:14'),
(261, 'animal', 1, '/ˈænɪməl/', 'In scientific usage, a multicellular organism that is usually mobile, whose cells are not encased in a rigid cell wall (distinguishing it from plants and fungi) and which derives energy solely from the consumption of other organisms (distinguishing it from plants).', '動物', 'https://api.dictionaryapi.dev/media/pronunciations/en/animal-us.mp3', 1, '2026-06-01 14:48:14'),
(262, 'ankle', 1, '/ˈæŋ.kəl/', 'The skeletal joint which connects the foot with the leg; the uppermost portion of the foot and lowermost portion of the leg, which contain this skeletal joint.', '腳踝', 'https://api.dictionaryapi.dev/media/pronunciations/en/ankle-us.mp3', 1, '2026-06-01 14:48:14'),
(263, 'anniversary', 1, '/ˌænɪˈvɜːs(ə)ɹi/', 'A day that is an exact number of years (to the day) since a given significant event occurred. Often preceded by an ordinal number indicating the number of years.', '週年紀念日', 'https://api.dictionaryapi.dev/media/pronunciations/en/anniversary-uk.mp3', 1, '2026-06-01 14:48:14'),
(264, 'announce', 1, '/əˈnaʊns/', 'To give public notice, especially for the first time; to make known', '通告、宣告（此處依名詞語意翻譯）', NULL, 1, '2026-06-01 14:48:14'),
(265, 'announce', 2, '/əˈnaʊns/', 'To give public notice, especially for the first time; to make known', '宣布、宣告、發表', NULL, 1, '2026-06-01 14:48:14'),
(266, 'annual', 3, '/ˈæn.ju.əl/', 'Happening once every year.', '每年的、年度的', 'https://api.dictionaryapi.dev/media/pronunciations/en/annual-us.mp3', 1, '2026-06-01 14:48:14'),
(267, 'anonymous', 3, '/əˈnɒnəməs/', 'Lacking a name; not named, for example an animal not assigned to any species.', '匿名的、無名氏的', 'https://api.dictionaryapi.dev/media/pronunciations/en/anonymous-us.mp3', 1, '2026-06-01 14:48:14'),
(268, 'another', 3, '/æˈnʌð.ə(ɹ)/', 'An additional one of the same kind.', '另一個的、再一個的', 'https://api.dictionaryapi.dev/media/pronunciations/en/another-uk.mp3', 1, '2026-06-01 14:48:14'),
(269, 'answer', 1, '/ˈan.sə/', 'A response or reply; something said or done in reaction to a statement or question.', '答案、回答', 'https://api.dictionaryapi.dev/media/pronunciations/en/answer-uk.mp3', 1, '2026-06-01 14:48:14'),
(270, 'answer', 2, '/ˈan.sə/', 'A response or reply; something said or done in reaction to a statement or question.', '回答、答覆', 'https://api.dictionaryapi.dev/media/pronunciations/en/answer-uk.mp3', 1, '2026-06-01 14:48:14'),
(271, 'ant', 1, '/ɛnt/', 'Any of various insects in the family Formicidae in the order Hymenoptera, typically living in large colonies composed almost entirely of flightless females.', '螞蟻', 'https://api.dictionaryapi.dev/media/pronunciations/en/ant-us.mp3', 1, '2026-06-01 14:48:14'),
(272, 'anthem', 1, '/ˈæn.θəm/', 'Antiphon.', '頌歌、國歌、校歌', NULL, 1, '2026-06-01 14:48:14'),
(273, 'antibiotic', 1, '/ˌæn.taɪ.baɪˈɒt.ɪk/', 'Any substance that can destroy or inhibit the growth of bacteria and similar microorganisms, generally transported by the lymphatic system.', '抗生素', NULL, 1, '2026-06-01 14:48:14'),
(274, 'antibody', 1, '', 'A protein produced by B-lymphocytes that binds to a specific antigen.', '抗體', 'https://api.dictionaryapi.dev/media/pronunciations/en/antibody-us.mp3', 1, '2026-06-01 14:48:14'),
(275, 'anticipation', 1, '/æn.tɪs.əˈpe.ʃən/', 'The act of anticipating, taking up, placing, or considering something beforehand, or before the proper time in natural order.', '期待、預期', NULL, 1, '2026-06-01 14:48:14'),
(276, 'antique', 3, '/ænˈtiːk/', 'Playful, funny, absurd', '古董的、古風的', 'https://api.dictionaryapi.dev/media/pronunciations/en/antique-us.mp3', 1, '2026-06-01 14:48:14'),
(277, 'anxiety', 1, '/ˌæŋ(ɡ)ˈzaɪ.ə.ti/', 'An unpleasant state of mental uneasiness, nervousness, apprehension and obsession or concern about some uncertain event.', '焦慮、憂慮', 'https://api.dictionaryapi.dev/media/pronunciations/en/anxiety-us.mp3', 1, '2026-06-01 14:48:14'),
(278, 'anxious', 3, '/ˈaŋ(k)ʃəs/', 'Nervous and worried.', '焦慮的、渴望的', 'https://api.dictionaryapi.dev/media/pronunciations/en/anxious-us.mp3', 1, '2026-06-01 14:48:14'),
(279, 'any', 3, '/ˈæni/', 'To even the slightest extent, at all.', '任何的、任一的', 'https://api.dictionaryapi.dev/media/pronunciations/en/any-us.mp3', 1, '2026-06-01 14:48:14'),
(280, 'any', 4, '/ˈæni/', 'To even the slightest extent, at all.', '稍微、根本（用於否定/疑問）', 'https://api.dictionaryapi.dev/media/pronunciations/en/any-us.mp3', 1, '2026-06-01 14:48:14'),
(281, 'anyhow', 4, '/ˈæn.i.haʊ/', '(manner) In any way or manner whatever.', '無論如何、不管怎樣', 'https://api.dictionaryapi.dev/media/pronunciations/en/anyhow-us.mp3', 1, '2026-06-01 14:48:14'),
(282, 'anymore', 4, '/ˌæ.niˈmoːɹ/', '(in negative or interrogative constructions) From a given time onwards; longer, again.', '再也不、現在（不）', 'https://api.dictionaryapi.dev/media/pronunciations/en/anymore-us.mp3', 1, '2026-06-01 14:48:14'),
(283, 'anyway', 4, '/ˈɛniweɪ/', 'Regardless; anyhow.', '無論如何、反正', 'https://api.dictionaryapi.dev/media/pronunciations/en/anyway-us.mp3', 1, '2026-06-01 14:48:14'),
(284, 'apart', 3, '/əˈpɑː(ɹ)t/', '(Used after a noun or in the predicate) Exceptional, distinct.', '分離的、分開的', 'https://api.dictionaryapi.dev/media/pronunciations/en/apart-us.mp3', 1, '2026-06-01 14:48:14'),
(285, 'apart', 4, '/əˈpɑː(ɹ)t/', 'Placed separately (in regard to space or time).', '相距地、分開地', 'https://api.dictionaryapi.dev/media/pronunciations/en/apart-us.mp3', 1, '2026-06-01 14:48:14'),
(286, 'apartment', 1, '/əˈpɑːt.mənt/', 'A complete domicile occupying only part of a building, especially one for rent; a flat.', '公寓、套房', 'https://api.dictionaryapi.dev/media/pronunciations/en/apartment-uk.mp3', 1, '2026-06-01 14:48:14'),
(287, 'ape', 1, '/eɪp/', 'A primate of the clade Hominoidea, generally larger than monkeys and distinguished from them by having no tail.', '猿、大猩猩', 'https://api.dictionaryapi.dev/media/pronunciations/en/ape-us.mp3', 1, '2026-06-01 14:48:14'),
(288, 'apologize', 2, '/əˈpɒləd͡ʒaɪz/', '(often followed by “for”) To make an apology or excuse; to acknowledge some fault or offense, with expression of regret for it, by way of amends', '道歉、認錯', 'https://api.dictionaryapi.dev/media/pronunciations/en/apologize-us.mp3', 1, '2026-06-01 14:48:14'),
(289, 'apology', 1, '/əˈpɒl.ə.dʒi/', 'An expression of remorse or regret for having said or done something that harmed another: an instance of apologizing (saying that one is sorry).', '道歉、謝罪', 'https://api.dictionaryapi.dev/media/pronunciations/en/apology-us.mp3', 1, '2026-06-01 14:48:14'),
(290, 'appal', 2, '', 'To fill with horror; to dismay.', '使驚駭、使膽寒', 'https://dictionaryapi.dev/appal', 1, '2026-06-01 14:48:14'),
(291, 'appalling', 3, '/əˈpɔːlɪŋ/', 'Horrifying and astonishing.', '令人驚駭的、糟糕透頂的', NULL, 1, '2026-06-01 14:48:14'),
(292, 'apparent', 3, '/əˈpæ.ɹənt/', 'Capable of being seen, or easily seen; open to view; visible to the eye, eyely; within sight or view.', '明顯的、顯而易見的', 'https://api.dictionaryapi.dev/media/pronunciations/en/apparent-us.mp3', 1, '2026-06-01 14:48:14'),
(293, 'appeal', 1, '/əˈpiːl/', 'An application for the removal of a cause or suit from an inferior to a superior judge or court for re-examination or review.', '呼籲、上訴、吸引力', 'https://api.dictionaryapi.dev/media/pronunciations/en/appeal-au.mp3', 1, '2026-06-01 14:48:14'),
(294, 'appeal', 2, '/əˈpiːl/', 'To call upon another to decide a question controverted, to corroborate a statement, to vindicate one\'s rights, etc.', '呼籲、要求、有吸引力', 'https://api.dictionaryapi.dev/media/pronunciations/en/appeal-au.mp3', 1, '2026-06-01 14:48:14'),
(295, 'appealing', 3, '/əˈpiː.lɪŋ/', 'Having appeal; attractive.', '有吸引力的、迷人的', NULL, 1, '2026-06-01 14:48:14'),
(296, 'appear', 2, '/əˈpiːɹ/', 'To come or be in sight; to be in view; to become visible.', '出現、顯露、似乎', 'https://api.dictionaryapi.dev/media/pronunciations/en/appear-us.mp3', 1, '2026-06-01 14:48:14'),
(297, 'appearance', 1, '/əˈpɪəɹəns/', 'The act of appearing or coming into sight; the act of becoming visible to the eye.', '外表、出現、露面', 'https://api.dictionaryapi.dev/media/pronunciations/en/appearance-us.mp3', 1, '2026-06-01 14:48:14'),
(298, 'appetite', 1, '/ˈæp.ə.taɪt/', 'Desire to eat food or consume drink.', '食慾、胃口、慾望', 'https://api.dictionaryapi.dev/media/pronunciations/en/appetite-us.mp3', 1, '2026-06-01 14:48:14'),
(299, 'appetizer', 1, '', 'A small, light, and usually savory first course in a meal', '開胃菜、前菜', 'https://api.dictionaryapi.dev/media/pronunciations/en/appetizer-us.mp3', 1, '2026-06-01 14:48:14'),
(300, 'applaud', 2, '/əˈplɔːd/', 'To express approval (of something) by clapping the hands.', '向...鼓掌、稱讚', 'https://api.dictionaryapi.dev/media/pronunciations/en/applaud-us.mp3', 1, '2026-06-01 14:48:14'),
(301, 'applause', 1, '/əˈplɔːz/', 'The act of applauding; approbation and praise publicly expressed by the clapping of hands, stamping or tapping of the feet, acclamation, huzzas, or other means; marked commendation.', '掌聲、喝采', 'https://api.dictionaryapi.dev/media/pronunciations/en/applause-us.mp3', 1, '2026-06-01 14:48:14'),
(302, 'appliance', 1, '/əˈplaɪəns/', 'An implement, an instrument or apparatus designed (or at least used) as a means to a specific end (often specified), especially:', '器具、家用電器', 'https://api.dictionaryapi.dev/media/pronunciations/en/appliance-us.mp3', 1, '2026-06-01 14:48:14'),
(303, 'applicable', 3, '/əˈplɪkəbəl/', 'Suitable for application, relevant', '可應用的、適用的', 'https://api.dictionaryapi.dev/media/pronunciations/en/applicable-us.mp3', 1, '2026-06-01 14:48:14'),
(304, 'applicant', 1, '/ˈæp.lə.kɪnt/', 'One who applies for something; one who makes a request; a petitioner.', '申請人、應徵者', NULL, 1, '2026-06-01 14:48:14'),
