(953, 'census', 1, '/ˈsɛnsəs/', 'An official count or enumeration of members of a population (not necessarily human), usually residents or citizens in a particular region, often done at regular intervals.', '人口普查', 'https://api.dictionaryapi.dev/media/pronunciations/en/census-us.mp3', 1, '2026-06-01 14:48:14'),
(954, 'cent', 1, '/sɛnt/', '(money) A subunit of currency equal to one-hundredth of the main unit of currency in many countries. Symbol: ¢.', '分（貨幣單位）', 'https://api.dictionaryapi.dev/media/pronunciations/en/cent-us.mp3', 1, '2026-06-01 14:48:14'),
(955, 'center', 1, '/ˈsɛn.tə(ɹ)/', 'The point in the interior of a circle that is equidistant from all points on the circumference.', '中心、核心、焦點', 'https://dictionaryapi.dev/center', 1, '2026-06-01 14:48:14'),
