(1232, 'compartment', 1, '/kəmˈpɑː(ɹ)tmənt/', 'A room, or section, or chamber', '隔間、（列車的）小客艙', 'https://dictionaryapi.dev/compartment', 1, '2026-06-01 14:48:14'),
(1233, 'compass', 1, '/ˈkʌm.pəs/', 'A magnetic or electronic device used to determine the cardinal directions (usually magnetic or true north).', '指南針、羅盤、圓規、範圍', 'https://api.dictionaryapi.dev/media/pronunciations/en/compass-us.mp3', 1, '2026-06-01 14:48:14'),
(1234, 'compassionate', 3, '/kəmˈpæʃənət/', 'Having, feeling or showing compassion (to or toward someone).', '有同情心的、慈悲的', 'https://dictionaryapi.dev/compassionate', 1, '2026-06-01 14:48:14'),
(1235, 'compatible', 3, '/kəmˈpætəbəl/', 'Capable of easy interaction.', '相容的、協調的、相容的', 'https://dictionaryapi.dev/compatible', 1, '2026-06-01 14:48:14'),
(1236, 'compatibly', 4, '', 'N/A', '和諧地、相容地、相配地', NULL, 1, '2026-06-01 14:48:14'),
(1237, 'compensate', 2, '/ˈkɒm.pən.seɪt/', 'To do (something good) after (something bad) happens', '補償、賠償、彌補', 'https://api.dictionaryapi.dev/media/pronunciations/en/compensate-us.mp3', 1, '2026-06-01 14:48:14'),
(1238, 'compensation', 1, '/ˌkɒmpɛnˈseɪʃən/', 'The act or principle of compensating.', '補償、賠償金、薪酬', 'https://api.dictionaryapi.dev/media/pronunciations/en/compensation-us.mp3', 1, '2026-06-01 14:48:14'),
(1239, 'compete', 2, '/kəm.ˈpiːt/', 'To be in battle or in a rivalry with another for the same thing, position, or reward; to contend', '競爭、對抗、比賽', '', 1, '2026-06-01 14:48:14'),
(1240, 'competence', 1, '/ˈkɒmpətəns/', 'The quality or state of being competent, i.e. able or suitable for a general role.', '能力、勝任、稱職', 'https://dictionaryapi.dev/competence', 1, '2026-06-01 14:48:14'),
(1241, 'competition', 1, '/ˌkɒmpəˈtɪʃən/', 'The action of competing.', '競爭、比賽、角逐', 'https://api.dictionaryapi.dev/media/pronunciations/en/competition-us.mp3', 1, '2026-06-01 14:48:14'),
