(1243, 'competitor', 1, '', 'A person or organization against whom one is competing.', '競爭者、對手', 'https://dictionaryapi.dev/competitor', 1, '2026-06-01 14:48:14'),
(1244, 'compile', 2, '/kəmpʌɪl/', 'To put together; to assemble; to make by gathering things from various sources.', '匯編、編輯、蒐集', 'https://api.dictionaryapi.dev/media/pronunciations/en/compile-uk.mp3', 1, '2026-06-01 14:48:14'),
(1245, 'complain', 2, '/kəmˈpleɪn/', 'To express feelings of pain, dissatisfaction, or resentment.', '抱怨、發牢騷、控訴', 'https://api.dictionaryapi.dev/media/pronunciations/en/complain-us.mp3', 1, '2026-06-01 14:48:14'),
(1246, 'complaint', 1, '/kəmˈpleɪnt/', 'The act of complaining.', '抱怨、投訴、控告、疾病', 'https://api.dictionaryapi.dev/media/pronunciations/en/complaint-us.mp3', 1, '2026-06-01 14:48:14'),
