(1262, 'composer', 1, '', 'One who composes; an author.', '作曲家', 'https://api.dictionaryapi.dev/media/pronunciations/en/composer-us.mp3', 1, '2026-06-01 14:48:14'),
(1263, 'composite', 3, '/ˈkɒmpəzɪt/', 'Made up of multiple components; compound or complex.', '合成的、複合的', 'https://api.dictionaryapi.dev/media/pronunciations/en/composite-ca.mp3', 1, '2026-06-01 14:48:14'),
(1264, 'composition', 1, '/ˌkɒmpəˈzɪʃən/', 'The act of putting together; assembly.', '作文、成分、作品、結構', 'https://api.dictionaryapi.dev/media/pronunciations/en/composition-us.mp3', 1, '2026-06-01 14:48:14'),
(1265, 'comprehend', 2, '/kɒmpɹɪˈhɛnd/', 'To include, comprise; to contain.', '理解、領會', 'https://api.dictionaryapi.dev/media/pronunciations/en/comprehend-us.mp3', 1, '2026-06-01 14:48:14'),
(1266, 'comprehensible', 3, '/kɒmpɹəˈhɛnsɪbəl/', 'Able to be comprehended.', '可理解的、易於了解的', 'https://dictionaryapi.dev/comprehensible', 1, '2026-06-01 14:48:14'),
(1267, 'comprehension', 1, '/kɒmpɹɪˈhɛnʃn̩/', 'Thorough understanding', '理解（力）、領悟', 'https://dictionaryapi.dev/comprehension', 1, '2026-06-01 14:48:14'),
(1268, 'comprehensive', 3, '', 'Broadly or completely covering; including a large proportion of something.', '全面的、廣泛的、詳盡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/comprehensive-au.mp3', 1, '2026-06-01 14:48:14'),
(1269, 'compress', 2, '/kəmˈpɹɛs/', 'To make smaller; to press or squeeze together, or to make something occupy a smaller space or volume.', '壓縮、壓緊、精簡', 'https://api.dictionaryapi.dev/media/pronunciations/en/compress-1.mp3', 1, '2026-06-01 14:48:14'),
