(1645, 'debt', 1, '/dɛt/', 'An action, state of mind, or object one has an obligation to perform for another, adopt toward another, or give to another.', '債務、借款、恩情', 'https://api.dictionaryapi.dev/media/pronunciations/en/debt-us.mp3', 1, '2026-06-01 14:48:14'),
(1646, 'debut', 1, '/dəˈbʉː/', 'A performer\'s first performance to the public, in sport, the arts or some other area.', '初次登場、出道、首次演出', 'https://api.dictionaryapi.dev/media/pronunciations/en/debut-us.mp3', 1, '2026-06-01 14:48:14'),
(1647, 'decease', 1, '/dɪˈsiːs/', 'Death, departure from life.', '死亡', 'https://api.dictionaryapi.dev/media/pronunciations/en/decease-uk.mp3', 1, '2026-06-01 14:48:14'),
(1648, 'deceive', 2, '/dɪˈsiːv/', 'To trick or mislead.', '欺騙、瞞騙', 'https://api.dictionaryapi.dev/media/pronunciations/en/deceive-us.mp3', 1, '2026-06-01 14:48:14'),
(1649, 'December', 1, '', 'N/A', '十二月', NULL, 1, '2026-06-01 14:48:14'),
(1650, 'decency', 1, '/ˈdiːsənsi/', 'The quality of being decent; propriety.', '正派、端莊、體面', 'https://api.dictionaryapi.dev/media/pronunciations/en/decency-uk.mp3', 1, '2026-06-01 14:48:14'),
