(1652, 'deception', 1, '/dɪˈsɛpʃən/', 'An instance of actions and/or schemes fabricated to mislead someone into believing a lie or inaccuracy.', '欺騙、騙局、詭計', 'https://api.dictionaryapi.dev/media/pronunciations/en/deception-us.mp3', 1, '2026-06-01 14:48:14'),
(1653, 'deceptive', 3, '/dɪ.ˈsɛp.tɪv/', 'Likely or attempting to deceive.', '欺騙性的、誤導的', 'https://api.dictionaryapi.dev/media/pronunciations/en/deceptive-us.mp3', 1, '2026-06-01 14:48:14'),
(1654, 'decide', 2, '/dɪˈsaɪd/', 'To resolve (a contest, problem, dispute, etc.); to choose, determine, or settle', '決定、下決心、解決', 'https://api.dictionaryapi.dev/media/pronunciations/en/decide-us.mp3', 1, '2026-06-01 14:48:14'),
