(1663, 'decoration', 1, '/ˌdɛkəˈɹeɪʃən/', 'The act of adorning, embellishing, or honoring; ornamentation.', '裝飾、裝飾品、勳章', 'https://api.dictionaryapi.dev/media/pronunciations/en/decoration-us.mp3', 1, '2026-06-01 14:48:14'),
(1664, 'decrease', 1, '', 'An amount by which a quantity is decreased.', '減少、減少量', 'https://api.dictionaryapi.dev/media/pronunciations/en/decrease-us.mp3', 1, '2026-06-01 14:48:14'),
(1665, 'decrease', 2, '', 'Of a quantity, to become smaller.', '減少、降低', 'https://api.dictionaryapi.dev/media/pronunciations/en/decrease-us.mp3', 1, '2026-06-01 14:48:14'),
(1666, 'decree', 1, '/dɪˈkɹiː/', 'An edict or law.', '法令、政令、判決', 'https://api.dictionaryapi.dev/media/pronunciations/en/decree-uk.mp3', 1, '2026-06-01 14:48:14'),
