(1668, 'dedicate', 2, '/ˈdɛdɪkeɪt/', 'To set apart for a deity or for religious purposes; consecrate.', '奉獻、致力於、題獻', 'https://api.dictionaryapi.dev/media/pronunciations/en/dedicate-uk.mp3', 1, '2026-06-01 14:48:14'),
(1669, 'deduction', 1, '/dɪˈdʊkʃən/', 'That which is deducted; that which is subtracted or removed', '扣除、推論、演繹法', 'https://api.dictionaryapi.dev/media/pronunciations/en/deduction-us.mp3', 1, '2026-06-01 14:48:14'),
(1670, 'deed', 1, '/diːd/', 'An action or act; something that is done.', '行為、契據、證書', 'https://api.dictionaryapi.dev/media/pronunciations/en/deed-us.mp3', 1, '2026-06-01 14:48:14'),
(1671, 'deem', 2, '', 'To judge, to pass judgment on; to doom, to sentence.', '認為、視為', 'https://api.dictionaryapi.dev/media/pronunciations/en/deem-au.mp3', 1, '2026-06-01 14:48:14'),
(1672, 'deep', 3, '/diːp/', '(of a physical distance) Extending far away from a point of reference, especially downwards.', '深的、深奧的、濃厚的', 'https://api.dictionaryapi.dev/media/pronunciations/en/deep-au.mp3', 1, '2026-06-01 14:48:14'),
(1673, 'deep', 4, '/diːp/', 'Deeply.', '深深地、深入地', 'https://api.dictionaryapi.dev/media/pronunciations/en/deep-au.mp3', 1, '2026-06-01 14:48:14'),
(1674, 'deepen', 2, '/ˈdiːpən/', 'To make deep or deeper', '加深、變深、變劇烈', 'https://dictionaryapi.dev/deepen', 1, '2026-06-01 14:48:14'),
(1675, 'deer', 1, '/diːɹ/', 'A ruminant mammal with antlers and hooves of the family Cervidae, or one of several similar animals from related families of the order Artiodactyla', '鹿', 'https://api.dictionaryapi.dev/media/pronunciations/en/deer-us.mp3', 1, '2026-06-01 14:48:14'),
(1676, 'defeat', 1, '/dɪˈfiːt/', 'To overcome in battle or contest.', '失敗、戰敗、挫敗', 'https://api.dictionaryapi.dev/media/pronunciations/en/defeat-us.mp3', 1, '2026-06-01 14:48:14'),
(1677, 'defeat', 2, '/dɪˈfiːt/', 'To overcome in battle or contest.', '擊敗、戰勝、使挫敗', 'https://api.dictionaryapi.dev/media/pronunciations/en/defeat-us.mp3', 1, '2026-06-01 14:48:14'),
(1678, 'defect', 1, '', 'A fault or malfunction.', '缺點、瑕疵、缺陷', 'https://api.dictionaryapi.dev/media/pronunciations/en/defect-uk.mp3', 1, '2026-06-01 14:48:14'),
(1679, 'defend', 2, '/dɪˈfɛnd/', 'To ward off attacks against; to fight to protect; to guard.', '防守、辯護、保衛', 'https://api.dictionaryapi.dev/media/pronunciations/en/defend-us.mp3', 1, '2026-06-01 14:48:14'),
(1680, 'defense', 1, '/dɪˈfɛns/', 'The action of defending or protecting from attack, danger, or injury.', '防禦、防衛、辯護', 'https://api.dictionaryapi.dev/media/pronunciations/en/defense-us.mp3', 1, '2026-06-01 14:48:14'),
(1681, 'defensive', 3, '', 'Intended for defence; protective.', '防禦性的、自衛的', 'https://api.dictionaryapi.dev/media/pronunciations/en/defensive-au.mp3', 1, '2026-06-01 14:48:14'),
(1682, 'deficiency', 1, '/dɪˈfɪʃənsi/', 'Inadequacy or incompleteness.', '缺乏、不足、缺陷', 'https://dictionaryapi.dev/deficiency', 1, '2026-06-01 14:48:14'),
(1683, 'deficit', 1, '/ˈdɛfɪsɪt/', 'Deficiency in amount or quality; a falling short; lack.', '赤字、虧損', 'https://dictionaryapi.dev/deficit', 1, '2026-06-01 14:48:14'),
(1684, 'define', 2, '/dɪˈfaɪn/', 'To determine with precision; to mark out with distinctness; to ascertain or exhibit clearly.', '下定義、限定、解釋', 'https://api.dictionaryapi.dev/media/pronunciations/en/define-us.mp3', 1, '2026-06-01 14:48:14'),
(1685, 'definite', 3, '/ˈdɛfɪnɪt/', 'Having distinct limits.', '明確的、肯定的、限定的', 'https://api.dictionaryapi.dev/media/pronunciations/en/definite-us.mp3', 1, '2026-06-01 14:48:14'),
(1686, 'defy', 2, '/dɪˈfaɪ/', 'To challenge (someone) or brave (a hazard or opposition).', '違抗、反抗、公然藐視', 'https://api.dictionaryapi.dev/media/pronunciations/en/defy-us.mp3', 1, '2026-06-01 14:48:14'),
(1687, 'degree', 1, '/dɪˈɡɹiː/', 'A stage of proficiency or qualification in a course of study, now especially an award bestowed by a university or, in some countries, a college, as a certification of academic achievement. (In the United States, can include secondary schools.)', '程度、度數、學位', 'https://api.dictionaryapi.dev/media/pronunciations/en/degree-uk.mp3', 1, '2026-06-01 14:48:14'),
(1688, 'delay', 1, '/dɪˈleɪ/', 'A period of time before an event occurs; the act of delaying; procrastination; lingering inactivity.', '延誤、延期', 'https://api.dictionaryapi.dev/media/pronunciations/en/delay-1-us.mp3', 1, '2026-06-01 14:48:14'),
(1689, 'delay', 2, '/dɪˈleɪ/', 'To put off until a later time; to defer.', '推遲、耽擱、延誤', 'https://api.dictionaryapi.dev/media/pronunciations/en/delay-1-us.mp3', 1, '2026-06-01 14:48:14'),
(1690, 'delegate', 2, '', 'To authorize someone to be a delegate', '委派...為代表、授權', 'https://dictionaryapi.dev/delegate', 1, '2026-06-01 14:48:14'),
(1691, 'delegation', 1, '/dɛlɪˈɡeɪʃən/', 'An act of delegating.', '代表團、委派', 'https://dictionaryapi.dev/delegation', 1, '2026-06-01 14:48:14'),
(1692, 'deliberately', 4, '/dəˈlɪb(ə)ɹətli/', 'Intentionally, or after deliberation; not accidentally.', '故意地、蓄意地、審慎地', 'https://api.dictionaryapi.dev/media/pronunciations/en/deliberately-us.mp3', 1, '2026-06-01 14:48:14'),
(1693, 'deliberation', 1, '/dɪˌlɪbəˈɹeɪʃən/', 'The act of deliberating, or of weighing and examining the reasons for and against a choice or measure; careful consideration; mature reflection.', '深思熟慮、審議、從容', 'https://dictionaryapi.dev/deliberation', 1, '2026-06-01 14:48:14'),
(1694, 'delicacy', 1, '/ˈdɛlɪkəsi/', 'The quality of being delicate.', '佳餚、精緻、脆弱', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicacy-us.mp3', 1, '2026-06-01 14:48:14'),
(1695, 'delicate', 3, '/ˈdɛlɪkət/', 'Easily damaged or requiring careful handling.', '精緻的、脆弱的、微妙的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicate-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(1696, 'delicious', 3, '/dɪˈlɪʃəs/', 'Pleasing to taste; tasty.', '美味的、令人愉快的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicious-us.mp3', 1, '2026-06-01 14:48:14'),
(1697, 'delight', 1, '/dəˈlaɪt/', 'Joy; pleasure.', '欣喜、快樂、令人高興的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/delight-us.mp3', 1, '2026-06-01 14:48:14'),
(1698, 'delight', 2, '/dəˈlaɪt/', 'To give delight to; to affect with great pleasure; to please highly.', '使高興、使欣喜', 'https://api.dictionaryapi.dev/media/pronunciations/en/delight-us.mp3', 1, '2026-06-01 14:48:14'),
(1699, 'delightful', 3, '[dəˈlaɪ̯t̚.fəɫ]', 'Pleasant; pleasing, bringing enjoyment, satisfaction, or pleasure.', '令人愉快的、討人喜歡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delightful-us.mp3', 1, '2026-06-01 14:48:14'),
(1700, 'delinquent', 3, '/dɪˈlɪŋkwənt/', 'Late or failing to pay a debt or other financial obligation, like a mortgage or loan.', '違法的、拖欠的、有過失的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delinquent-us.mp3', 1, '2026-06-01 14:48:14'),
