(2391, 'extension', 1, '/ɪkˈstɛnʃən/', 'The act of extending; a stretching out; enlargement in length or breadth; an increase', '延長、擴大、電話分機', 'https://api.dictionaryapi.dev/media/pronunciations/en/extension-us.mp3', 1, '2026-06-01 14:48:14'),
(2392, 'extensive', 3, '/ɛksˈtɛn.sɪv/', 'Having a great extent; covering a large area; vast', '廣泛的、廣闊的、大量的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extensive-us.mp3', 1, '2026-06-01 14:48:14'),
