(2394, 'extinct', 3, '/ɛkˈstɪŋkt/', 'Extinguished, no longer alight (of fire, candles etc.)', '絕種的、滅絕的、熄滅的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extinct-uk.mp3', 1, '2026-06-01 14:48:14'),
(2395, 'extra', 1, '', 'Something additional, such as an item above and beyond the ordinary school curriculum, or added to the usual charge on a bill.', '額外的人（或物）、臨時演員', 'https://api.dictionaryapi.dev/media/pronunciations/en/extra-au.mp3', 1, '2026-06-01 14:48:14'),
(2396, 'extra', 3, '', 'Beyond what is due, usual, expected, or necessary; extraneous; additional; supernumerary.', '額外的、附加的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extra-au.mp3', 1, '2026-06-01 14:48:14'),
(2397, 'extra', 4, '', 'To an extraordinary degree.', '特別地、格外地', 'https://api.dictionaryapi.dev/media/pronunciations/en/extra-au.mp3', 1, '2026-06-01 14:48:14'),
(2398, 'extract', 2, '', 'To draw out; to pull out; to remove forcibly from a fixed position, as by traction or suction, etc.', '提取、拔出、榨出、摘錄', 'https://dictionaryapi.dev/extract', 1, '2026-06-01 14:48:14'),
(2399, 'extracurricular', 3, '', 'Outside of the normal curriculum of an educational establishment', '課外的', 'https://dictionaryapi.dev/extracurricular', 1, '2026-06-01 14:48:14'),
(2400, 'extraordinary', 3, '/ɪksˈtɹɔː(ɹ)dɪnəɹi/', 'Not ordinary; exceptional; unusual.', '非凡的、特別的、離奇的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extraordinary-us.mp3', 1, '2026-06-01 14:48:14'),
(2401, 'extravagance', 1, '/ɪkˈstɹævəɡəns/', 'Excessive or superfluous expenditure of money.', '奢侈、浪費、揮霍、奢侈品', 'https://dictionaryapi.dev/extravagance', 1, '2026-06-01 14:48:14'),
(2402, 'extreme', 1, '/ɛkˈstɹiːm/', 'The greatest or utmost point, degree or condition.', '極端、末端、極度', 'https://api.dictionaryapi.dev/media/pronunciations/en/extreme-us.mp3', 1, '2026-06-01 14:48:14'),
(2403, 'extreme', 3, '/ɛkˈstɹiːm/', 'Of a place, the most remote, farthest or outermost.', '極端的、極度的、偏激的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extreme-us.mp3', 1, '2026-06-01 14:48:14'),
(2404, 'eye', 1, '/aɪ/', 'An organ through which animals see (perceive surroundings via light).', '眼睛、目光、見解', 'https://api.dictionaryapi.dev/media/pronunciations/en/eye-us.mp3', 1, '2026-06-01 14:48:14'),
(2405, 'eye', 2, '/aɪ/', 'To observe carefully or appraisingly.', '看、注視、觀察', 'https://api.dictionaryapi.dev/media/pronunciations/en/eye-us.mp3', 1, '2026-06-01 14:48:14'),
