(2652, 'frost', 1, '/fɹɑst/', 'A cover of minute ice crystals on objects that are exposed to the air. Frost is formed by the same process as dew, except that the temperature of the frosted object is below freezing.', '霜、嚴寒', 'https://api.dictionaryapi.dev/media/pronunciations/en/frost-us.mp3', 1, '2026-06-01 14:48:14'),
(2653, 'frost', 2, '/fɹɑst/', 'To cover with frost.', '結霜、凍壞', 'https://api.dictionaryapi.dev/media/pronunciations/en/frost-us.mp3', 1, '2026-06-01 14:48:14'),
(2654, 'frown', 1, '/fɹaʊn/', 'A facial expression in which the eyebrows are brought together, and the forehead is wrinkled, usually indicating displeasure, sadness or worry, or less often confusion or concentration.', '皺眉、不悅的神色', 'https://api.dictionaryapi.dev/media/pronunciations/en/frown-us.mp3', 1, '2026-06-01 14:48:14'),
(2655, 'frown', 2, '/fɹaʊn/', 'A facial expression in which the eyebrows are brought together, and the forehead is wrinkled, usually indicating displeasure, sadness or worry, or less often confusion or concentration.', '皺眉、表示不滿', 'https://api.dictionaryapi.dev/media/pronunciations/en/frown-us.mp3', 1, '2026-06-01 14:48:14'),
(2656, 'fruit', 1, '/fɹuːt/', '(often in the plural) In general, a product of plant growth useful to man or animals.', '水果、成果、產物', 'https://api.dictionaryapi.dev/media/pronunciations/en/fruit-uk.mp3', 1, '2026-06-01 14:48:14'),
(2657, 'frustrate', 2, '/fɹəˈstɹeɪt/', 'To disappoint or defeat; to vex by depriving of something expected or desired.', '使沮喪、使挫敗、阻撓', 'https://api.dictionaryapi.dev/media/pronunciations/en/frustrate-uk.mp3', 1, '2026-06-01 14:48:14'),
(2658, 'fry', 2, '/fɹaɪ/', 'A method of cooking food.', '油炸、油煎、油炒', 'https://api.dictionaryapi.dev/media/pronunciations/en/fry-us.mp3', 1, '2026-06-01 14:48:14'),
(2659, 'fuel', 1, '/ˈfjuːl/', 'Substance consumed to provide energy through combustion, or through chemical or nuclear reaction.', '燃料、刺激因素', 'https://api.dictionaryapi.dev/media/pronunciations/en/fuel-uk.mp3', 1, '2026-06-01 14:48:14'),
(2660, 'fuel', 2, '/ˈfjuːl/', 'To provide with fuel.', '加燃料、激起、加油', 'https://api.dictionaryapi.dev/media/pronunciations/en/fuel-uk.mp3', 1, '2026-06-01 14:48:14'),
(2661, 'fught', 1, '', 'N/A', '打架、戰鬥（應為 fight 之拼寫錯誤）', NULL, 1, '2026-06-01 14:48:14'),
(2662, 'fulfill', 1, '/fəˈfɪl/', 'To satisfy, carry out, bring to completion (an obligation, a requirement, etc.).', '履行、實現、完成（此處作名詞用，或拼寫通後者）', 'https://api.dictionaryapi.dev/media/pronunciations/en/fulfill-us.mp3', 1, '2026-06-01 14:48:14'),
(2663, 'fulfill', 2, '/fəˈfɪl/', 'To satisfy, carry out, bring to completion (an obligation, a requirement, etc.).', '履行、實現、完成、滿足', 'https://api.dictionaryapi.dev/media/pronunciations/en/fulfill-us.mp3', 1, '2026-06-01 14:48:14'),
(2664, 'full', 3, '/fʊl/', 'Containing the maximum possible amount that can fit in the space available.', '滿的、完全的、飽的', 'https://api.dictionaryapi.dev/media/pronunciations/en/full-au.mp3', 1, '2026-06-01 14:48:14'),
(2665, 'fun', 1, '/fʊn/', 'Amusement, enjoyment or pleasure', '樂趣、好玩的事、娛樂', 'https://api.dictionaryapi.dev/media/pronunciations/en/fun-us.mp3', 1, '2026-06-01 14:48:14'),
(2666, 'function', 1, '/ˈfʌŋ(k)ʃən/', 'What something does or is used for.', '功能、職責、函數、重大聚會', 'https://api.dictionaryapi.dev/media/pronunciations/en/function-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(2667, 'function', 2, '/ˈfʌŋ(k)ʃən/', 'To have a function.', '運作、起作用、行使職責', 'https://api.dictionaryapi.dev/media/pronunciations/en/function-us.mp3', 1, '2026-06-01 14:48:14'),
(2668, 'functional', 3, '/ˈfʌŋk(t)ʃnəl/', 'In good working order.', '實用的、功能性的、運轉正常的', 'https://api.dictionaryapi.dev/media/pronunciations/en/functional-us.mp3', 1, '2026-06-01 14:48:14'),
(2669, 'fund', 1, '/ˈfʌnd/', 'A sum or source of money.', '資金、基金、專款', 'https://api.dictionaryapi.dev/media/pronunciations/en/fund-uk.mp3', 1, '2026-06-01 14:48:14'),
(2670, 'fund', 2, '/ˈfʌnd/', 'To pay for.', '資助、提供資金', 'https://api.dictionaryapi.dev/media/pronunciations/en/fund-uk.mp3', 1, '2026-06-01 14:48:14'),
(2671, 'fundamental', 3, '/ˌfʌndəˈmɛntəl/', 'Pertaining to the foundation or basis; serving for the foundation.', '基本的、根本的、重要的', 'https://api.dictionaryapi.dev/media/pronunciations/en/fundamental-us.mp3', 1, '2026-06-01 14:48:14'),
(2672, 'funeral', 1, '/ˈfjuːnəɹəl/', 'A ceremony to honour and remember a deceased person. Often distinguished from a memorial service by the presence of the body of the deceased.', '葬禮、喪禮', 'https://api.dictionaryapi.dev/media/pronunciations/en/funeral-us.mp3', 1, '2026-06-01 14:48:14'),
(2673, 'funny', 3, '/ˈfʊnɪ/', 'Amusing; humorous; comical.', '滑稽的、有趣的、古怪的', 'https://api.dictionaryapi.dev/media/pronunciations/en/funny-uk.mp3', 1, '2026-06-01 14:48:14'),
(2674, 'fur', 1, '/fɜː(ɹ)/', 'The hairy coat of various mammal species, especially when fine, soft and thick.', '毛皮、軟毛、皮草', 'https://api.dictionaryapi.dev/media/pronunciations/en/fur-1-us.mp3', 1, '2026-06-01 14:48:14'),
(2675, 'furious', 3, '/ˈfjʊə.ɹɪəs/', 'Feeling great anger; raging; violent.', '暴怒的、狂暴的、猛烈的', 'https://api.dictionaryapi.dev/media/pronunciations/en/furious-us.mp3', 1, '2026-06-01 14:48:14'),
(2676, 'furnish', 2, '/ˈfɜːnɪʃ/', 'To provide a place with furniture, or other equipment.', '配備家具、提供、供應', 'https://api.dictionaryapi.dev/media/pronunciations/en/furnish-us.mp3', 1, '2026-06-01 14:48:14'),
(2677, 'furniture', 1, '/ˈfɜːnɪtʃə/', 'Large movable item(s), usually in a room, which enhance(s) the room\'s characteristics, functionally or decoratively.', '家具', 'https://api.dictionaryapi.dev/media/pronunciations/en/furniture-us.mp3', 1, '2026-06-01 14:48:14'),
(2678, 'further', 2, '/fɜː(ɹ)ðə(ɹ)/', 'To help forward; to assist.', '促進、助長、推動', 'https://api.dictionaryapi.dev/media/pronunciations/en/further-us.mp3', 1, '2026-06-01 14:48:14'),
(2679, 'further', 3, '/fɜː(ɹ)ðə(ɹ)/', '(comparative form of far) More distant; relatively distant.', '更遠的、進一步的', 'https://api.dictionaryapi.dev/media/pronunciations/en/further-us.mp3', 1, '2026-06-01 14:48:14'),
(2680, 'further', 4, '/fɜː(ɹ)ðə(ɹ)/', '(comparative form of far) To, at or over a greater distance in space, time or other extent.', '更遠地、進一步地、此外', 'https://api.dictionaryapi.dev/media/pronunciations/en/further-us.mp3', 1, '2026-06-01 14:48:14'),
(2681, 'furthermore', 4, '/ˈfɜː(ɹ).ðə(ɹ).mɔː(ɹ)/', 'In addition; besides; what\'s more; used to denote additional information.', '而且、此外、再者', 'https://api.dictionaryapi.dev/media/pronunciations/en/furthermore-us.mp3', 1, '2026-06-01 14:48:14'),
(2682, 'future', 1, '/ˈfjuːt͡ʃə/', 'The time ahead; those moments yet to be experienced.', '未來、前途、將來', 'https://api.dictionaryapi.dev/media/pronunciations/en/future-us.mp3', 1, '2026-06-01 14:48:14'),
(2683, 'future', 3, '/ˈfjuːt͡ʃə/', 'Having to do with or occurring in the future.', '未來的、將來的', 'https://api.dictionaryapi.dev/media/pronunciations/en/future-us.mp3', 1, '2026-06-01 14:48:14'),
(2684, 'gaiety', 1, '/ˈɡeɪ.ə.ti/', 'The state of being happy or merry.', '歡樂、高興、愉快', 'https://dictionaryapi.dev/gaiety', 1, '2026-06-01 14:48:14'),
(2685, 'gain', 1, '/ɡeɪn/', 'The act of gaining; acquisition.', '利益、獲得、增加、獲利', 'https://api.dictionaryapi.dev/media/pronunciations/en/gain-us.mp3', 1, '2026-06-01 14:48:14'),
(2686, 'gain', 2, '/ɡeɪn/', 'To acquire possession of.', '獲得、贏得、增加、（鐘錶）走快', 'https://api.dictionaryapi.dev/media/pronunciations/en/gain-us.mp3', 1, '2026-06-01 14:48:14'),
(2687, 'galaxy', 1, '/ˈɡaləksi/', 'The Milky Way; the apparent band of concentrated stars which appears in the night sky over earth.', '銀河、銀河系、星系、群英', 'https://api.dictionaryapi.dev/media/pronunciations/en/galaxy-us.mp3', 1, '2026-06-01 14:48:14'),
(2688, 'gallery', 1, '/ˈɡæləɹi/', 'An institution, building, or room for the exhibition and conservation of works of art.', '畫廊、美術館、長廊', 'https://dictionaryapi.dev/gallery', 1, '2026-06-01 14:48:14'),
(2689, 'gallon', 1, '/ˈɡælən/', 'A unit of volume, equivalent to eight pints', '加侖（容量單位）', 'https://api.dictionaryapi.dev/media/pronunciations/en/gallon-us.mp3', 1, '2026-06-01 14:48:14'),
(2690, 'gamble', 2, '/ˈɡæm.bəl/', 'To take a risk, with the potential of a positive outcome.', '賭博、投機、冒險', 'https://dictionaryapi.dev/gamble', 1, '2026-06-01 14:48:14'),
(2691, 'game', 1, '/ɡeɪm/', 'A playful or competitive activity.', '遊戲、比賽、獵物', 'https://api.dictionaryapi.dev/media/pronunciations/en/game-us.mp3', 1, '2026-06-01 14:48:14'),
(2692, 'gang', 1, '/ɡæŋ/', 'To go; walk; proceed.', '幫派、一夥、一幫人', 'https://api.dictionaryapi.dev/media/pronunciations/en/gang-uk.mp3', 1, '2026-06-01 14:48:14'),
(2693, 'gap', 1, '/ɡæp/', 'An opening in anything made by breaking or parting.', '裂口、差距、隔閡、空白', 'https://api.dictionaryapi.dev/media/pronunciations/en/gap-au.mp3', 1, '2026-06-01 14:48:14'),
(2694, 'garage', 1, '/ɡəˈɹɑː(d)ʒ/', 'A building (or section of a building) used to store a car or cars, tools and other miscellaneous items.', '車庫、汽車修理廠', 'https://api.dictionaryapi.dev/media/pronunciations/en/garage-au.mp3', 1, '2026-06-01 14:48:14'),
(2695, 'garbage', 1, '/ˈɡɑːbɪd͡ʒ/', 'Food waste material of any kind.', '垃圾、廢物、廢話', 'https://api.dictionaryapi.dev/media/pronunciations/en/garbage-us.mp3', 1, '2026-06-01 14:48:14'),
(2696, 'garden', 1, '', 'An outdoor area containing one or more types of plants, usually plants grown for food or ornamental purposes.', '花園、菜園、庭園', 'https://api.dictionaryapi.dev/media/pronunciations/en/garden-au.mp3', 1, '2026-06-01 14:48:14'),
(2697, 'garden', 2, '', 'To grow plants in a garden; to create or maintain a garden.', '從事園藝、種植花卉', 'https://api.dictionaryapi.dev/media/pronunciations/en/garden-au.mp3', 1, '2026-06-01 14:48:14'),
(2698, 'gardener', 1, '/ˈɡɑːdnə/', 'One who gardens; one who grows plants or cultivates a garden.', '園丁、花匠', 'https://api.dictionaryapi.dev/media/pronunciations/en/gardener-us.mp3', 1, '2026-06-01 14:48:14'),
(2699, 'garlic', 1, '/ˈɡɑːlɪk/', 'A plant, Allium sativum, related to the onion, having a pungent bulb much used in cooking.', '大蒜', 'https://api.dictionaryapi.dev/media/pronunciations/en/garlic-uk.mp3', 1, '2026-06-01 14:48:14'),
(2700, 'gas', 1, '/ɡæs/', 'Matter in a state intermediate between liquid and plasma that can be contained only if it is fully surrounded by a solid (or in a bubble of liquid) (or held together by gravitational pull); it can condense into a liquid, or can (rarely) become a solid directly.', '氣體、瓦斯、汽油', 'https://api.dictionaryapi.dev/media/pronunciations/en/gas-us.mp3', 1, '2026-06-01 14:48:14'),
(2701, 'gas', 2, '/ɡæs/', 'To kill with poisonous gas.', '（因吸入毒氣等）窒息、給...加汽油', 'https://api.dictionaryapi.dev/media/pronunciations/en/gas-us.mp3', 1, '2026-06-01 14:48:14'),
(2702, 'gasoline', 1, '/ˈɡæs.ə.lin/', 'A flammable liquid consisting of a mixture of refined petroleum hydrocarbons, mainly used as a motor fuel; petrol.', '汽油', 'https://api.dictionaryapi.dev/media/pronunciations/en/gasoline-us.mp3', 1, '2026-06-01 14:48:14'),
(2703, 'gasp', 2, '/ɡɑːsp/', 'To draw in the breath suddenly, as if from a shock.', '倒吸一口氣、喘息、渴望', 'https://dictionaryapi.dev/gasp', 1, '2026-06-01 14:48:14'),
(2704, 'gate', 1, '/ɡeɪt/', 'A doorlike structure outside a house.', '大門、柵門、出入口', 'https://api.dictionaryapi.dev/media/pronunciations/en/gate-au.mp3', 1, '2026-06-01 14:48:14'),
(2705, 'gather', 2, '/ˈɡæðə/', 'To collect; normally separate things.', '聚集、集合、收集、推斷', 'https://api.dictionaryapi.dev/media/pronunciations/en/gather-us.mp3', 1, '2026-06-01 14:48:14'),
(2706, 'gauge', 1, '/ˈɡeɪdʒ/', 'A measure; a standard of measure; an instrument to determine dimensions, distance, or capacity; a standard', '測量儀表、標準、厚度', 'https://api.dictionaryapi.dev/media/pronunciations/en/gauge-us.mp3', 1, '2026-06-01 14:48:14'),
(2707, 'gaze', 2, '/ɡeɪz/', 'To stare intently or earnestly.', '凝視、注視', 'https://api.dictionaryapi.dev/media/pronunciations/en/gaze-us.mp3', 1, '2026-06-01 14:48:14'),
(2708, 'gear', 1, '', 'Equipment or paraphernalia, especially that used for an athletic endeavor.', '齒輪、排檔、工具、裝備', 'https://api.dictionaryapi.dev/media/pronunciations/en/gear-au.mp3', 1, '2026-06-01 14:48:14'),
(2709, 'gear', 1, '', 'Equipment or paraphernalia, especially that used for an athletic endeavor.', '（重複資料，同為名詞）齒輪、裝備、工具', 'https://api.dictionaryapi.dev/media/pronunciations/en/gear-au.mp3', 1, '2026-06-01 14:48:14'),
(2710, 'gear', 2, '', 'To provide with gearing; to fit with gears in order to achieve a desired gear ratio.', '使適應、使適合、搭上齒輪', 'https://api.dictionaryapi.dev/media/pronunciations/en/gear-au.mp3', 1, '2026-06-01 14:48:14'),
(2711, 'Gemini', 1, '', 'N/A', '雙子座、雙子星座', NULL, 1, '2026-06-01 14:48:14'),
(2712, 'gender', 1, '/ˈdʒɛndə/', 'Class; kind.', '性別', 'https://dictionaryapi.dev/gender', 1, '2026-06-01 14:48:14'),
(2713, 'gene', 1, '/dʒiːn/', 'A theoretical unit of heredity of living organisms; a gene may take several values and in principle predetermines a precise trait of an organism\'s form (phenotype), such as hair color.', '基因', 'https://api.dictionaryapi.dev/media/pronunciations/en/gene-us.mp3', 1, '2026-06-01 14:48:14'),
(2714, 'general', 3, '/ˈd͡ʒɛnɹəl/', 'Including or involving every part or member of a given or implied entity, whole etc.; as opposed to specific or particular.', '一般的、普遍的、總體上的', 'https://api.dictionaryapi.dev/media/pronunciations/en/general-us.mp3', 1, '2026-06-01 14:48:14'),
(2715, 'generalize', 2, '', 'To speak in generalities, or in vague terms.', '概括、歸納、推論', 'https://dictionaryapi.dev/generalize', 1, '2026-06-01 14:48:14'),
(2716, 'generate', 2, '/ˈdʒɛn.əɹ.eɪt/', 'To bring into being; give rise to.', '產生、引起、發電', 'https://api.dictionaryapi.dev/media/pronunciations/en/generate-us.mp3', 1, '2026-06-01 14:48:14'),
(2717, 'generation', 1, '/ˌd͡ʒɛnəˈɹeɪʃən/', 'The fact of creating something, or bringing something into being; production, creation.', '世代、一代、產生', 'https://api.dictionaryapi.dev/media/pronunciations/en/generation-us.mp3', 1, '2026-06-01 14:48:14'),
(2718, 'generator', 1, '', 'One who, or that which, generates, begets, causes, or produces.', '發電機、產生器', 'https://dictionaryapi.dev/generator', 1, '2026-06-01 14:48:14'),
(2719, 'generosity', 1, '/ˌd͡ʒɛnəˈɹɒsɪti/', 'The trait of being willing to donate money, time or resources.', '慷慨、大方', 'https://dictionaryapi.dev/generosity', 1, '2026-06-01 14:48:14'),
(2720, 'generous', 3, '/ˈdʒɛn(ə)ɹəs/', 'Noble in behaviour or actions; principled, not petty; kind, magnanimous.', '慷慨的、大方的、豐盛的', 'https://api.dictionaryapi.dev/media/pronunciations/en/generous-us.mp3', 1, '2026-06-01 14:48:14'),
(2721, 'generously', 2, '', 'In a generous manner, in a way that is giving or ample.', '（此處代碼2應為副詞）慷慨地、大方地、豐厚地', 'https://api.dictionaryapi.dev/media/pronunciations/en/generously-us.mp3', 1, '2026-06-01 14:48:14'),
(2722, 'genetics', 1, '/dʒɛˈnɛ.tɪks/', 'The branch of biology that deals with the transmission and variation of inherited characteristics, in particular chromosomes and DNA.', '遺傳學', 'https://api.dictionaryapi.dev/media/pronunciations/en/genetics-uk.mp3', 1, '2026-06-01 14:48:14'),
(2723, 'genius', 1, '/ˈdʒiː.nɪəs/', 'Someone possessing extraordinary intelligence or skill; especially somebody who has demonstrated this by a creative or original work in science, music, art etc.', '天才、天賦、才華', 'https://api.dictionaryapi.dev/media/pronunciations/en/genius-us.mp3', 1, '2026-06-01 14:48:14'),
(2724, 'gentle', 3, '/ˈdʒɛntl̩/', 'Tender and amiable; of a considerate or kindly disposition.', '溫和的、溫柔的、文雅的', 'https://api.dictionaryapi.dev/media/pronunciations/en/gentle-us.mp3', 1, '2026-06-01 14:48:14'),
(2725, 'gentleman', 1, '/ˈdʒɛn.təl.mən/', 'A man of gentle but not noble birth, particularly a man of means (originally ownership of property) who does not work for a living but has no official status in a peerage; an armiferous man ranking below a knight.', '紳士、先生', 'https://api.dictionaryapi.dev/media/pronunciations/en/gentleman-au.mp3', 1, '2026-06-01 14:48:14'),
(2726, 'genuine', 3, '/ˈdʒɛnjuːˌaɪn/', 'Belonging to, or proceeding from the original stock; native', '真正的、真誠的、地道的', 'https://api.dictionaryapi.dev/media/pronunciations/en/genuine-us.mp3', 1, '2026-06-01 14:48:14'),
(2727, 'geographical', 3, '/d͡ʒiəˈɡɹæfɪkl̩/', 'Of or relating to geography; geographic.', '地理學的、地理的', 'https://dictionaryapi.dev/geographical', 1, '2026-06-01 14:48:14'),
(2728, 'geography', 1, '/dʒɪˈɒɡɹəfi/', 'A description of the earth: a treatise or textbook on geography; an atlas or gazetteer.', '地理、地理學', 'https://api.dictionaryapi.dev/media/pronunciations/en/geography-us.mp3', 1, '2026-06-01 14:48:14'),
(2729, 'geometry', 1, '/dʒiːˈɒmɪtɹi/', 'The branch of mathematics dealing with spatial relationships.', '幾何學', 'https://api.dictionaryapi.dev/media/pronunciations/en/geometry-us.mp3', 1, '2026-06-01 14:48:14'),
(2730, 'germ', 1, '/d͡ʒɜːm/', 'The small mass of cells from which a new organism develops; a seed, bud or spore.', '微生物、細菌、胚芽', 'https://api.dictionaryapi.dev/media/pronunciations/en/germ-us.mp3', 1, '2026-06-01 14:48:14'),
(2731, 'gesture', 1, '/ˈdʒɛs.tʃɚ/', 'A motion of the limbs or body, especially one made to emphasize speech.', '手勢、姿勢、姿態、表示', 'https://api.dictionaryapi.dev/media/pronunciations/en/gesture-us.mp3', 1, '2026-06-01 14:48:14'),
(2732, 'gesture', 2, '/ˈdʒɛs.tʃɚ/', 'To make a gesture or gestures.', '做手勢、用手勢表示', 'https://api.dictionaryapi.dev/media/pronunciations/en/gesture-us.mp3', 1, '2026-06-01 14:48:14'),
