(3333, 'integral', 3, '/ˈɪntɪɡɹəl/', 'Constituting a whole together with other parts or factors; not omittable or removable', '不可或缺的、整體的、構成整體所必需的', 'https://api.dictionaryapi.dev/media/pronunciations/en/integral-uk.mp3', 1, '2026-06-01 14:48:14'),
(3334, 'integrity', 1, '/ɪnˈtɛɡɹəti/', 'Steadfast adherence to a strict moral or ethical code.', '正直、廉潔、完整', 'https://api.dictionaryapi.dev/media/pronunciations/en/integrity-us.mp3', 1, '2026-06-01 14:48:14'),
(3335, 'intellect', 1, '/ˈɪntəlɛkt/', 'The faculty of thinking, judging, abstract reasoning, and conceptual understanding; the cognitive faculty (uncountable)', '智力、才智、理解力', 'https://api.dictionaryapi.dev/media/pronunciations/en/intellect-us.mp3', 1, '2026-06-01 14:48:14'),
(3336, 'intelligence', 1, '/ɪnˈtɛl.ɪ.d͡ʒəns/', 'Capacity of mind, especially to understand principles, truths, facts or meanings, acquire knowledge, and apply it to practice; the ability to comprehend and learn.', '智力、智慧、情報', 'https://api.dictionaryapi.dev/media/pronunciations/en/intelligence-us.mp3', 1, '2026-06-01 14:48:14'),
(3337, 'intelligent', 3, '/ɪnˈtɛlɪd͡ʒənt/', 'Of high or especially quick cognitive capacity, bright.', '聰明的、有才智的、有靈性的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intelligent-us.mp3', 1, '2026-06-01 14:48:14'),
(3338, 'intelligible', 3, '/ɪnˈtɛlədʒəbl̩/', 'Capable of being understood; clear to the mind.', '可理解的、清晰易懂的', 'https://dictionaryapi.dev/intelligible', 1, '2026-06-01 14:48:14'),
(3339, 'intend', 2, '/ɪnˈtɛnd/', '(usually followed by the particle \"to\") To hope; to wish (something, or something to be accomplished); be intent upon', '打算、企圖、意圖', 'https://api.dictionaryapi.dev/media/pronunciations/en/intend-us.mp3', 1, '2026-06-01 14:48:14'),
(3340, 'intense', 3, '/ɪnˈtɛns/', 'Strained; tightly drawn.', '強烈的、劇烈的、熱烈的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intense-us.mp3', 1, '2026-06-01 14:48:14'),
(3341, 'intensify', 2, '', 'To render more intense', '增強、加劇', 'https://dictionaryapi.dev/intensify', 1, '2026-06-01 14:48:14'),
(3342, 'intensity', 1, '/ɪnˈtɛnsɪti/', 'The quality of being intense.', '強度、強烈、密集', 'https://dictionaryapi.dev/intensity', 1, '2026-06-01 14:48:14'),
(3343, 'intensive', 3, '/ɪnˈtɛnsɪv/', 'Thorough; to a great degree; with intensity.', '加強的、密集的、精深的', 'https://dictionaryapi.dev/intensive', 1, '2026-06-01 14:48:14'),
(3344, 'intent', 1, '/ɪnˈtɛnt/', 'A purpose; something that is intended.', '意圖、目的', 'https://dictionaryapi.dev/intent', 1, '2026-06-01 14:48:14'),
(3345, 'intention', 1, '/ɪnˈtɛnʃən/', 'The goal or purpose behind a specific action or set of actions.', '意圖、目的、打算', 'https://api.dictionaryapi.dev/media/pronunciations/en/intention-us.mp3', 1, '2026-06-01 14:48:14'),
(3346, 'interact', 2, '/ɪntəɹˈækt/', 'To act upon each other.', '互動、交流、相互作用', 'https://dictionaryapi.dev/interact', 1, '2026-06-01 14:48:14'),
(3347, 'interaction', 1, '/ˌɪntəɹˈækʃən/', 'The situation or occurrence in which two or more objects or events act upon one another to produce a new effect; the effect resulting from such a situation or occurrence.', '互動、相互影響', 'https://api.dictionaryapi.dev/media/pronunciations/en/interaction-us.mp3', 1, '2026-06-01 14:48:14'),
(3348, 'intercept', 2, '', 'To stop, deflect or divert (something in progress or motion).', '攔截、截擊、截聽', 'https://dictionaryapi.dev/intercept', 1, '2026-06-01 14:48:14'),
(3349, 'interchangeable', 3, '/ɪntɚˈtʃeɪndʒəbl̩/', 'Freely substitutable; that may be swapped at will.', '可互換的、可交換的', 'https://dictionaryapi.dev/interchangeable', 1, '2026-06-01 14:48:14'),
(3350, 'intercourse', 1, '/ˈɪn.təˌkɔːs/', 'Communication, conversation.', '交流、交往、性交', 'https://api.dictionaryapi.dev/media/pronunciations/en/intercourse-us.mp3', 1, '2026-06-01 14:48:14'),
(3351, 'interest', 1, '/ˈɪntəɹɪst/', 'The price paid for obtaining, or price received for providing, money or goods in a credit transaction, calculated as a fraction of the amount or value of what was borrowed.', '興趣、愛好、利益、利息', 'https://api.dictionaryapi.dev/media/pronunciations/en/interest-us.mp3', 1, '2026-06-01 14:48:14'),
(3352, 'interest', 2, '/ˈɪntəɹɪst/', 'To engage the attention of; to awaken interest in; to excite emotion or passion in, in behalf of a person or thing.', '使發生興趣、引起...的注意', 'https://api.dictionaryapi.dev/media/pronunciations/en/interest-us.mp3', 1, '2026-06-01 14:48:14'),
(3353, 'interesting', 3, '/ˈɪnt(ə)ɹɛstɪŋ/', 'Of concern; affecting, important.', '有趣的、引起興趣的', 'https://api.dictionaryapi.dev/media/pronunciations/en/interesting-us.mp3', 1, '2026-06-01 14:48:14'),
(3354, 'interfere', 2, '/ˌɪntəˈfɪə/', 'To get involved or involve oneself, causing disturbance.', '干涉、干預、妨礙', 'https://api.dictionaryapi.dev/media/pronunciations/en/interfere-us.mp3', 1, '2026-06-01 14:48:14'),
(3355, 'interference', 1, '/ˌɪntəɹˈfiɹɨns/', 'The act of interfering with something, or something that interferes.', '干涉、干預、干擾', 'https://dictionaryapi.dev/interference', 1, '2026-06-01 14:48:14'),
(3356, 'interior', 1, '/ɪnˈtɪəɹɪə/', 'The inside of a building, container, cavern, or other enclosed structure.', '內部、內陸、內政', 'https://api.dictionaryapi.dev/media/pronunciations/en/interior-us.mp3', 1, '2026-06-01 14:48:14'),
(3357, 'interior', 3, '/ɪnˈtɪəɹɪə/', 'Within any limits, enclosure, or substance; inside; internal; inner.', '內部的、室內的、內陸的', 'https://api.dictionaryapi.dev/media/pronunciations/en/interior-us.mp3', 1, '2026-06-01 14:48:14'),
(3358, 'intermediate', 3, '/ɪntə(ɹ)ˈmidi.ət/', 'Being between two extremes, or in the middle of a range.', '中級的、中間的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intermediate-uk.mp3', 1, '2026-06-01 14:48:14'),
(3359, 'internal', 3, '/ɪnˈtɝnəl/', 'Inside of something', '內部的、國內的、內心的', 'https://api.dictionaryapi.dev/media/pronunciations/en/internal-us.mp3', 1, '2026-06-01 14:48:14'),
(3360, 'international', 3, '/ˌɪntəˈnæʃ(ə)n(ə)l/', 'Of or having to do with more than one nation.', '國際的、國際性的', 'https://api.dictionaryapi.dev/media/pronunciations/en/international-us.mp3', 1, '2026-06-01 14:48:14'),
(3361, 'Internet', 1, '/ˈɪntəˌnɛt/', 'Any set of computer networks that communicate using the Internet Protocol. (An intranet.)', '網際網路', 'https://api.dictionaryapi.dev/media/pronunciations/en/internet-us.mp3', 1, '2026-06-01 14:48:14'),
(3362, 'interpret', 2, '/ɪnˈtɜː.pɹɪt/', 'To explain or tell the meaning of; to translate orally into intelligible or familiar language or terms. applied especially to language, but also to dreams, signs, conduct, mysteries, etc.', '詮釋、解釋、口譯、理解', 'https://api.dictionaryapi.dev/media/pronunciations/en/interpret-us.mp3', 1, '2026-06-01 14:48:14'),
(3363, 'interpretation', 1, '/ɪntəpɹəˈteɪʃən/', 'An act of interpreting or explaining what is obscure; a translation; a version; a construction.', '理解、解釋、闡明、演出手法的演繹', 'https://api.dictionaryapi.dev/media/pronunciations/en/interpretation-uk.mp3', 1, '2026-06-01 14:48:14'),
(3364, 'interpreter', 1, '/ɪnˈtɜːpɹɪtə/', 'One who conveys what a user of one language is saying or signing, in real time or shortly after that person has finished communicating, to a user of a different language. (Contrasted with a translator.)', '口譯員、解說員、傳譯程序', 'https://dictionaryapi.dev/interpreter', 1, '2026-06-01 14:48:14'),
(3365, 'interrupt', 2, '/ˌɪntəˈɹʌpt/', 'To disturb or halt (an ongoing process or action, or the person performing it) by interfering suddenly.', '打斷、中斷、妨礙', 'https://api.dictionaryapi.dev/media/pronunciations/en/interrupt-us-verb.mp3', 1, '2026-06-01 14:48:14'),
(3366, 'interruption', 1, '/ˌɪntəˈɹʌpʃən/', 'The act of interrupting, or the state of being interrupted.', '打斷、中斷、干擾', 'https://api.dictionaryapi.dev/media/pronunciations/en/interruption-us.mp3', 1, '2026-06-01 14:48:14'),
(3367, 'intersection', 1, '/ˈɪntəɹˌsɛkʃən/', 'The junction of two (or more) paths, streets, highways, or other thoroughfares.', '十字路口、交叉點、交集', '', 1, '2026-06-01 14:48:14'),
(3368, 'interview', 1, '/ˈɪntəvjuː/', 'An official face-to-face meeting of monarchs or other important figures.', '面試、訪談、採訪', 'https://api.dictionaryapi.dev/media/pronunciations/en/interview-us.mp3', 1, '2026-06-01 14:48:14'),
(3369, 'interview', 2, '/ˈɪntəvjuː/', 'To ask questions of (somebody); to have an interview.', '面試、採訪、訪問', 'https://api.dictionaryapi.dev/media/pronunciations/en/interview-us.mp3', 1, '2026-06-01 14:48:14'),
(3370, 'intimate', 3, '/ˈɪn.tɪ.mət/', 'Closely acquainted; familiar.', '親密的、密切的、私人的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intimate-us.mp3', 1, '2026-06-01 14:48:14'),
(3371, 'intimidate', 2, '/ɪnˈtɪmɪdeɪt/', 'To make timid or afraid; to cause to feel fear or nervousness; to deter, especially by threats of violence', '恐嚇、威脅', 'https://dictionaryapi.dev/intimidate', 1, '2026-06-01 14:48:14'),
(3372, 'intonation', 1, '/ɪntɵˈneɪʃən/', 'The rise and fall of the voice in speaking.', '語調、聲調', 'https://dictionaryapi.dev/intonation', 1, '2026-06-01 14:48:14'),
(3373, 'intricate', 3, '/ˈɪn.tɹɪ.kət/', 'Having a great deal of fine detail or complexity.', '錯綜複雜的、難懂的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intricate-1-us.mp3', 1, '2026-06-01 14:48:14'),
(3374, 'intrigue', 1, '', 'A complicated or clandestine plot or scheme intended to effect some purpose by secret artifice; conspiracy; stratagem.', '陰謀、詭計、私通', 'https://api.dictionaryapi.dev/media/pronunciations/en/intrigue-uk.mp3', 1, '2026-06-01 14:48:14'),
(3375, 'intrigue', 2, '', 'To conceive or carry out a secret plan intended to harm; to form a plot or scheme.', '激起...的好奇心、激起...的興趣', 'https://api.dictionaryapi.dev/media/pronunciations/en/intrigue-uk.mp3', 1, '2026-06-01 14:48:14'),
(3376, 'intriguing', 3, '/ɪnˈtɹiːɡɪŋ/', 'Causing a desire to know more; mysterious.', '引人入勝的、迷人的', 'https://api.dictionaryapi.dev/media/pronunciations/en/intriguing-uk.mp3', 1, '2026-06-01 14:48:14'),
(3377, 'introduce', 2, '/ˌɪntɹəˈdjuːs/', '(of people) To cause (someone) to be acquainted (with someone else).', '介紹、引進、採用、推行', 'https://api.dictionaryapi.dev/media/pronunciations/en/introduce-us.mp3', 1, '2026-06-01 14:48:14'),
(3378, 'introduction', 1, '/ˌɪntɹəˈdʌkʃən/', 'The act or process of introducing.', '介紹、引進、導言、序幕', 'https://api.dictionaryapi.dev/media/pronunciations/en/introduction-us.mp3', 1, '2026-06-01 14:48:14'),
(3379, 'intuition', 1, '/ˌɪntjʊˈɪʃən/', 'Immediate cognition without the use of conscious rational processes.', '直覺、憑直覺發覺的事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/intuition-us.mp3', 1, '2026-06-01 14:48:14'),
(3380, 'invade', 2, '/ɪnˈveɪd/', 'To move into.', '侵略、侵入、侵犯', 'https://api.dictionaryapi.dev/media/pronunciations/en/invade-us.mp3', 1, '2026-06-01 14:48:14'),
(3381, 'invasion', 1, '/ɪnˈveɪʒən/', 'A military action consisting of armed forces of one geopolitical entity entering territory controlled by another such entity, generally with the objective of conquering territory or altering the established government.', '入侵、侵略、侵犯', 'https://dictionaryapi.dev/invasion', 1, '2026-06-01 14:48:14'),
(3382, 'invent', 2, '/ɪnˈvɛnt/', 'To design a new process or mechanism.', '發明、虛構、捏造', 'https://api.dictionaryapi.dev/media/pronunciations/en/invent-us.mp3', 1, '2026-06-01 14:48:14'),
(3383, 'invention', 1, '/ɪnˈvɛnʃən/', 'Something invented.', '發明、創造、發明物、捏造', 'https://api.dictionaryapi.dev/media/pronunciations/en/invention-us.mp3', 1, '2026-06-01 14:48:14'),
(3384, 'inventor', 1, '/ɪnˈvɛntə/', 'One who invents, either as a hobby or as an occupation.', '發明家', 'https://dictionaryapi.dev/inventor', 1, '2026-06-01 14:48:14'),
(3385, 'invest', 1, '/ɪnˈvɛst/', 'To spend money, time, or energy on something, especially for some benefit or purpose; used with in.', '投資、投入（時間或精力）（此處代碼 1 應指投資行爲之意）', 'https://api.dictionaryapi.dev/media/pronunciations/en/invest-uk.mp3', 1, '2026-06-01 14:48:14'),
(3386, 'invest', 2, '/ɪnˈvɛst/', 'To spend money, time, or energy on something, especially for some benefit or purpose; used with in.', '投資、投入、授予', 'https://api.dictionaryapi.dev/media/pronunciations/en/invest-uk.mp3', 1, '2026-06-01 14:48:14'),
(3387, 'investigate', 2, '[ɪn.ˈves.tɪ.ɡeɪ̯t]', 'To inquire into or study in order to ascertain facts or information.', '調查、研究', 'https://api.dictionaryapi.dev/media/pronunciations/en/investigate-us.mp3', 1, '2026-06-01 14:48:14'),
(3388, 'investigation', 1, '/ɪnˌvɛstəˈɡeɪʃən/', 'The act of investigating; the process of inquiring into or following up; research, especially patient or thorough inquiry or examination', '調查、研究', 'https://api.dictionaryapi.dev/media/pronunciations/en/investigation-us.mp3', 1, '2026-06-01 14:48:14'),
(3389, 'investigator', 1, '', 'One who investigates.', '調查員、偵查員', 'https://dictionaryapi.dev/investigator', 1, '2026-06-01 14:48:14'),
(3390, 'investor', 1, '/ɪnˈvɛstɚ/', 'A person who invests money in order to make a profit.', '投資者', '', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(3391, 'invisible', 3, '/ɪnˈvɪzəb(ə)l/', 'Unable to be seen; out of sight; not visible.', '看不見的、隱形的', 'https://api.dictionaryapi.dev/media/pronunciations/en/invisible-us.mp3', 1, '2026-06-01 14:48:14'),
(3392, 'invitation', 1, '/ɪn.vɪˈteɪ.ʃn̩/', 'The act of inviting; solicitation; the requesting of a person\'s company.', '邀請、邀請函、請帖', 'https://api.dictionaryapi.dev/media/pronunciations/en/invitation-us.mp3', 1, '2026-06-01 14:48:14'),
(3393, 'invite', 2, '/ɪnˈvaɪt/', 'To ask for the presence or participation of someone or something.', '邀請、招致、吸引', 'https://api.dictionaryapi.dev/media/pronunciations/en/invite-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(3394, 'inviting', 3, '/ɪnˈvaɪtɪŋ/', 'Alluring; tempting; attractive.', '吸引人的、誘人的、款待周到的', 'https://dictionaryapi.dev/inviting', 1, '2026-06-01 14:48:14'),
(3395, 'invoke', 2, '/ɪnˈvoʊk/', 'To call upon (a person, a god) for help, assistance or guidance.', '援引、祈求、訴諸（法律）', 'https://dictionaryapi.dev/invoke', 1, '2026-06-01 14:48:14'),
(3396, 'involve', 1, '/ɪnˈvɒlv/', 'To roll or fold up; to wind round; to entwine.', '涉及、包含、使參與（此處代碼 1 應指關聯之意）', 'https://api.dictionaryapi.dev/media/pronunciations/en/involve-uk.mp3', 1, '2026-06-01 14:48:14'),
(3397, 'involve', 2, '/ɪnˈvɒlv/', 'To roll or fold up; to wind round; to entwine.', '包含、需要、使捲入、牽涉', 'https://api.dictionaryapi.dev/media/pronunciations/en/involve-uk.mp3', 1, '2026-06-01 14:48:14'),
(3398, 'inward', 3, '/ˈɪnwəd/', 'Situated on the inside; that is within, inner; belonging to the inside.', '向內的、內心的、裡面的', 'https://api.dictionaryapi.dev/media/pronunciations/en/inward-us.mp3', 1, '2026-06-01 14:48:14'),
(3399, 'iron', 1, '/ˈaɪən/', 'A common, inexpensive metal, silvery grey when untarnished, that rusts, is attracted by magnets, and is used in making steel.', '鐵、熨斗', 'https://api.dictionaryapi.dev/media/pronunciations/en/iron-us.mp3', 1, '2026-06-01 14:48:14'),
(3400, 'iron', 3, '/ˈaɪən/', 'Made of the metal iron.', '鐵製的、堅強的', 'https://api.dictionaryapi.dev/media/pronunciations/en/iron-us.mp3', 1, '2026-06-01 14:48:14'),
(3401, 'ironic', 3, '/aɪˈɹɒn.ɪk/', 'Characterized by or constituting (any kind of) irony.', '諷刺的、挖苦的、出人意料的', 'https://api.dictionaryapi.dev/media/pronunciations/en/ironic-uk.mp3', 1, '2026-06-01 14:48:14'),
(3402, 'irony', 1, '', 'A statement that, when taken in context, may actually mean something different from, or the opposite of, what is written literally; the use of words expressing something other than their literal intention, often in a humorous context.', '諷刺、反諷、具有 community 諷刺意味的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/irony-1-au.mp3', 1, '2026-06-01 14:48:14'),
(3403, 'irregular', 3, '/ɪˈɹɛɡjəlɚ/', 'Nonstandard; not conforming to rules or expectations', '不規則的、不整齊的、不合常規的', 'https://dictionaryapi.dev/irregular', 1, '2026-06-01 14:48:14'),
(3404, 'irrelevant', 3, '', 'Not related, not applicable, unimportant, not connected.', '不相關的、無關係的', 'https://dictionaryapi.dev/irrelevant', 1, '2026-06-01 14:48:14'),
(3405, 'irresponsible', 3, '/ɪrəˈspɑnsɪbəl/', 'Not responsible; exempt from legal responsibility, not to be held accountable.', '不負責任的', 'https://dictionaryapi.dev/irresponsible', 1, '2026-06-01 14:48:14'),
(3406, 'irritable', 3, '/ˈɪɹɪtəbl/', 'Capable of being irritated.', '易怒的、急躁的、過敏的', 'https://dictionaryapi.dev/irritable', 1, '2026-06-01 14:48:14'),
(3407, 'irritate', 2, '/ˈɪɹɪteɪt/', 'To provoke impatience, anger, or displeasure in.', '使憤怒、使過敏、激怒', 'https://api.dictionaryapi.dev/media/pronunciations/en/irritate-us.mp3', 1, '2026-06-01 14:48:14'),
(3408, 'island', 1, '/ˈaɪ̯lənd/', 'A contiguous area of land, smaller than a continent, totally surrounded by water.', '島嶼', 'https://api.dictionaryapi.dev/media/pronunciations/en/island-uk.mp3', 1, '2026-06-01 14:48:14'),
(3409, 'isolate', 2, '', 'To set apart or cut off from others.', '使隔離、使孤立、分離', 'https://api.dictionaryapi.dev/media/pronunciations/en/isolate-us.mp3', 1, '2026-06-01 14:48:14'),
(3410, 'isolated', 3, '/ˈaɪsəleɪtɪd/', 'Placed or standing apart or alone; in isolation.', '孤立的、隔離的、偏遠的', 'https://api.dictionaryapi.dev/media/pronunciations/en/isolated-us.mp3', 1, '2026-06-01 14:48:14'),
(3411, 'isolation', 1, '/ˌaɪsəˈleɪʃən/', 'The state of being isolated, detached, or separated.', '隔離、孤立、孤獨', 'https://dictionaryapi.dev/isolation', 1, '2026-06-01 14:48:14'),
(3412, 'Italian', 1, '', 'N/A', '義大利人、義大利語', NULL, 1, '2026-06-01 14:48:14'),
(3413, 'itch', 2, '/ɪt͡ʃ/', 'A sensation felt on an area of the skin that causes a person or animal to want to scratch.', '發癢、渴望', 'https://api.dictionaryapi.dev/media/pronunciations/en/itch-us.mp3', 1, '2026-06-01 14:48:14'),
