(3590, 'legacy', 1, '/ˈleɪɡəsi/', 'Money or property bequeathed to someone in a will.', '遺產、遺留之物', 'https://api.dictionaryapi.dev/media/pronunciations/en/legacy-us.mp3', 1, '2026-06-01 14:48:14'),
(3591, 'legal', 3, '/ˈliː.ɡəl/', 'Relating to the law or to lawyers.', '法律上的、合法的', 'https://api.dictionaryapi.dev/media/pronunciations/en/legal-us.mp3', 1, '2026-06-01 14:48:14'),
(3592, 'legally', 4, '/ˈliːɡəli/', 'As permitted by law; not contrary to law.', '法律上、合法地', 'https://api.dictionaryapi.dev/media/pronunciations/en/legally-uk.mp3', 1, '2026-06-01 14:48:14'),
(3593, 'legend', 1, '/ˈlɛdʒ.ənd/', 'An unrealistic story depicting past events.', '傳說、傳奇人物、圖例', 'https://api.dictionaryapi.dev/media/pronunciations/en/legend-au.mp3', 1, '2026-06-01 14:48:14'),
(3594, 'leisure', 1, '/ˈliːʒə(ɹ)/', 'Freedom provided by the cessation of activities.', '閒暇、空閒', 'https://api.dictionaryapi.dev/media/pronunciations/en/leisure-au-uk.mp3', 1, '2026-06-01 14:48:14'),
(3595, 'leisure', 3, '/ˈliːʒə(ɹ)/', 'Freedom provided by the cessation of activities.', '空閒的、閒暇的', 'https://api.dictionaryapi.dev/media/pronunciations/en/leisure-au-uk.mp3', 1, '2026-06-01 14:48:14'),
(3596, 'leisurely', 3, '/ˈlɛʒɜli/', 'Characterized by leisure; taking plenty of time; unhurried', '從容的、悠閒的', 'https://dictionaryapi.dev/leisurely', 1, '2026-06-01 14:48:14'),
(3597, 'leisurely', 4, '/ˈlɛʒɜli/', 'Characterized by leisure; taking plenty of time; unhurried', '從容地、悠閒地', 'https://dictionaryapi.dev/leisurely', 1, '2026-06-01 14:48:14'),
(3598, 'lemon', 1, '/ˈlɛmən/', 'A yellowish citrus fruit.', '檸檬、檸檬黃', 'https://api.dictionaryapi.dev/media/pronunciations/en/lemon-uk.mp3', 1, '2026-06-01 14:48:14'),
(3599, 'lemonade', 1, '', 'A flavoured beverage consisting of water, lemon, and sweetener, sometimes ice, served mainly as a refreshment.', '檸檬水', 'https://api.dictionaryapi.dev/media/pronunciations/en/lemonade-au.mp3', 1, '2026-06-01 14:48:14'),
(3600, 'lend', 2, '/lɛnd/', 'The lumbar region; loin.', '借出、借給', 'https://api.dictionaryapi.dev/media/pronunciations/en/lend-us.mp3', 1, '2026-06-01 14:48:14'),
(3601, 'length', 1, '', 'The distance measured along the longest dimension of an object.', '長度、距離、一段時間', 'https://api.dictionaryapi.dev/media/pronunciations/en/length-au.mp3', 1, '2026-06-01 14:48:14'),
(3602, 'lengthen', 2, '/ˈlɛŋ(k)θən/', 'To make longer, to extend the length of.', '加長、延長', 'https://dictionaryapi.dev/lengthen', 1, '2026-06-01 14:48:14'),
(3603, 'lengthy', 3, '', 'Having length; long and overextended, especially in time rather than dimension.', '漫長的、冗長的', 'https://dictionaryapi.dev/lengthy', 1, '2026-06-01 14:48:14'),
(3604, 'lens', 1, '/lɛnz/', 'An object, usually made of glass, that focuses or defocuses the light that passes through it.', '透鏡、鏡片', 'https://api.dictionaryapi.dev/media/pronunciations/en/lens-us.mp3', 1, '2026-06-01 14:48:14'),
(3605, 'lesbian', 1, '/ˈlɛzbi.ən/', 'A homosexual woman, one who is mostly or exclusively sexually or romantically attracted to other women.', '女同性戀者', 'https://api.dictionaryapi.dev/media/pronunciations/en/lesbian-us.mp3', 1, '2026-06-01 14:48:14'),
(3606, 'less', 3, '/lɛs/', 'A smaller amount or quantity.', '較少的、較小的', 'https://api.dictionaryapi.dev/media/pronunciations/en/less-uk.mp3', 1, '2026-06-01 14:48:14'),
(3607, 'less', 4, '/lɛs/', 'To a smaller extent or degree.', '較少地、更少地', 'https://api.dictionaryapi.dev/media/pronunciations/en/less-uk.mp3', 1, '2026-06-01 14:48:14'),
(3608, 'lesser', 3, '/ˈlɛsə/', 'Of two (or, rarely, more than two) things: the smaller in size (littler), in value, in importance etc.', '較小的、次要的、較少的', 'https://api.dictionaryapi.dev/media/pronunciations/en/lesser-us.mp3', 1, '2026-06-01 14:48:14'),
(3609, 'lesser', 4, '/ˈlɛsə/', 'A thing that is of smaller size, value, importance etc.', '較小地、次要地', 'https://api.dictionaryapi.dev/media/pronunciations/en/lesser-us.mp3', 1, '2026-06-01 14:48:14'),
(3610, 'lesson', 1, '/ˈlɛsn̩/', 'A section of learning or teaching into which a wider learning content is divided.', '課、功課、教訓', 'https://api.dictionaryapi.dev/media/pronunciations/en/lesson-uk.mp3', 1, '2026-06-01 14:48:14'),
(3611, 'let', 2, '/lɛt/', 'To allow to, not to prevent (+ infinitive, but usually without to).', '讓、允許、出租', 'https://api.dictionaryapi.dev/media/pronunciations/en/let-us.mp3', 1, '2026-06-01 14:48:14'),
(3612, 'letter', 1, '/-ɾə(ɹ)/', 'A symbol in an alphabet.', '信、信件、字母', 'https://api.dictionaryapi.dev/media/pronunciations/en/letter-uk.mp3', 1, '2026-06-01 14:48:14'),
(3613, 'level', 1, '/ˈlɛv.əl/', 'A tool for finding whether a surface is level, or for creating a horizontal or vertical line of reference.', '高度、級別、水平面、層', 'https://api.dictionaryapi.dev/media/pronunciations/en/level-uk.mp3', 1, '2026-06-01 14:48:14'),
(3614, 'liability', 1, '/laɪəˈbɪlɪti/', 'An obligation, debt or responsibility owed to someone.', '責任、義務、債務、負擔', 'https://api.dictionaryapi.dev/media/pronunciations/en/liability-us.mp3', 1, '2026-06-01 14:48:14'),
(3615, 'liar', 1, '/ˈlaɪ.ə/', 'One who tells lies.', '說謊者、騙子', 'https://dictionaryapi.dev/liar', 1, '2026-06-01 14:48:14'),
(3616, 'liberal', 3, '/ˈlɪbɹəl/', '(now rare outside set phrases) Pertaining to those arts and sciences the study of which is considered to provide general knowledge, as opposed to vocational/occupational, technical or mechanical training.', '自由主義的、慷慨的、開明的', 'https://api.dictionaryapi.dev/media/pronunciations/en/liberal-us.mp3', 1, '2026-06-01 14:48:14'),
(3617, 'liberate', 2, '/ˈlɪbəɹeɪt/', 'To set free, to make or allow to be free, particularly', '解放、使自由、釋放', 'https://dictionaryapi.dev/liberate', 1, '2026-06-01 14:48:14'),
(3618, 'liberation', 1, '', 'The act of liberating or the state of being liberated.', '解放、釋放', 'https://dictionaryapi.dev/liberation', 1, '2026-06-01 14:48:14'),
(3619, 'liberty', 1, '/ˈlɪbɚti/', 'The condition of being free from control or restrictions.', '自由、特權', 'https://api.dictionaryapi.dev/media/pronunciations/en/liberty-us.mp3', 1, '2026-06-01 14:48:14'),
(3620, 'librarian', 1, '/laɪˈbɹɛɹ.i.ən/', 'The keeper, manager of a library.', '圖書館員、圖書管理員', 'https://dictionaryapi.dev/librarian', 1, '2026-06-01 14:48:14'),
(3621, 'library', 1, '/ˈlaɪbɹi/', 'An institution which holds books and/or other forms of media for use by the public or qualified people often lending them out, as well as providing various other services for its users.', '圖書館', 'https://api.dictionaryapi.dev/media/pronunciations/en/library-us.mp3', 1, '2026-06-01 14:48:14'),
(3622, 'license', 1, '/ˈlaɪsəns/', 'A legal document giving official permission to do something; a permit.', '執照、許可證', 'https://api.dictionaryapi.dev/media/pronunciations/en/license-us.mp3', 1, '2026-06-01 14:48:14'),
(3623, 'license', 2, '/ˈlaɪsəns/', 'To give a formal (usually written) authorization.', '許可、准許、發牌照給', 'https://api.dictionaryapi.dev/media/pronunciations/en/license-us.mp3', 1, '2026-06-01 14:48:14'),
(3624, 'lick', 1, '/lɪk/', 'The act of licking; a stroke of the tongue.', '舔、少許', 'https://api.dictionaryapi.dev/media/pronunciations/en/lick-us.mp3', 1, '2026-06-01 14:48:14'),
(3625, 'lick', 2, '/lɪk/', 'To stroke with the tongue.', '舔、舐、輕彈', 'https://api.dictionaryapi.dev/media/pronunciations/en/lick-us.mp3', 1, '2026-06-01 14:48:14'),
(3626, 'lid', 1, '/lɪd/', 'A thin skin membrane that covers and moves over an eye.', '蓋子、眼瞼', 'https://api.dictionaryapi.dev/media/pronunciations/en/lid-au.mp3', 1, '2026-06-01 14:48:14'),
(3627, 'lie', 1, '/laɪ̯/', 'The terrain and conditions surrounding the ball before it is struck.', '謊話、謊言', 'https://api.dictionaryapi.dev/media/pronunciations/en/lie-us.mp3', 1, '2026-06-01 14:48:14'),
(3628, 'lie', 2, '/laɪ̯/', 'To rest in a horizontal position on a surface.', '躺、臥、位於、說謊', 'https://api.dictionaryapi.dev/media/pronunciations/en/lie-us.mp3', 1, '2026-06-01 14:48:14'),
(3629, 'lieutenant', 1, '/ləˈtɛnənt/', 'The lowest Junior Commissioned Officer rank(s) in many military forces, often Army and Marines.', '陸軍中尉、海軍上尉', 'https://api.dictionaryapi.dev/media/pronunciations/en/lieutenant-au.mp3', 1, '2026-06-01 14:48:14'),
(3630, 'life', 1, '/laɪf/', 'The state of organisms preceding their death, characterized by biological processes such as metabolism and reproduction and distinguishing them from inanimate objects; the state of being alive and living.', '生命、生物、生活、一生', 'https://api.dictionaryapi.dev/media/pronunciations/en/life-uk.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(3631, 'lifeboat', 1, '/ˈlaɪfˌbəʊt/', 'A boat especially designed for saving the lives of shipwrecked people or people in distress at sea (either launched from the shore with a crew, or else carried on board a larger ship)', '救生艇', 'https://api.dictionaryapi.dev/media/pronunciations/en/lifeboat-us.mp3', 1, '2026-06-01 14:48:14'),
(3632, 'lifeguard', 1, '', 'A bodyguard or unit of bodyguards, a guard of someone\'s (especially a king\'s) life or person.', '救生員', 'https://dictionaryapi.dev/lifeguard', 1, '2026-06-01 14:48:14'),
(3633, 'lifelong', 3, '', 'Extending for the entire duration of life.', '終身的、畢生的', 'https://dictionaryapi.dev/lifelong', 1, '2026-06-01 14:48:14'),
(3634, 'lifetime', 1, '/ˈlaɪftaɪm/', 'The duration of the life of someone or something.', '一生、終生、使用壽命', 'https://api.dictionaryapi.dev/media/pronunciations/en/lifetime-us.mp3', 1, '2026-06-01 14:48:14'),
(3635, 'lift', 1, '/lɪft/', 'An act of lifting or raising.', '電梯、搭便車、舉起', 'https://api.dictionaryapi.dev/media/pronunciations/en/lift-au.mp3', 1, '2026-06-01 14:48:14'),
(3636, 'lift', 2, '/lɪft/', 'To raise or rise.', '舉起、抬起、提高、消散', 'https://api.dictionaryapi.dev/media/pronunciations/en/lift-au.mp3', 1, '2026-06-01 14:48:14'),
(3637, 'light', 1, '/lʌɪt/', 'Visible electromagnetic radiation. The human eye can typically detect radiation (light) in the wavelength range of about 400 to 750 nanometers. Nearby shorter and longer wavelength ranges, although not visible, are commonly called ultraviolet and infrared light.', '光、光線、燈', 'https://api.dictionaryapi.dev/media/pronunciations/en/light-uk.mp3', 1, '2026-06-01 14:48:14'),
(3638, 'light', 2, '/lʌɪt/', 'Visible electromagnetic radiation. The human eye can typically detect radiation (light) in the wavelength range of about 400 to 750 nanometers. Nearby shorter and longer wavelength ranges, although not visible, are commonly called ultraviolet and infrared light.', '點燃、照亮', 'https://api.dictionaryapi.dev/media/pronunciations/en/light-uk.mp3', 1, '2026-06-01 14:48:14'),
(3639, 'light', 3, '/lʌɪt/', 'Visible electromagnetic radiation. The human eye can typically detect radiation (light) in the wavelength range of about 400 to 750 nanometers. Nearby shorter and longer wavelength ranges, although not visible, are commonly called ultraviolet and infrared light.', '輕的、明亮的、淺色的', 'https://api.dictionaryapi.dev/media/pronunciations/en/light-uk.mp3', 1, '2026-06-01 14:48:14'),
(3640, 'lighten', 2, '/ˈlaɪ.tən/', 'To make brighter or clearer; to illuminate.', '變亮、減輕、照亮', 'https://dictionaryapi.dev/lighten', 1, '2026-06-01 14:48:14'),
(3641, 'lightning', 1, '/ˈlaɪt.nɪŋ/', 'A flash of light produced by short-duration, high-voltage discharge of electricity within a cloud, between clouds, or between a cloud and the earth.', '閃電', 'https://api.dictionaryapi.dev/media/pronunciations/en/lightning-us.mp3', 1, '2026-06-01 14:48:14'),
(3642, 'lightweight', 1, '', 'A particular weight class, or member of such, as prescribed by the rules, between that of the heavier welterweight and the lighter featherweight. See Wikipedia for the specifics of each sport.', '輕量級選手、無足輕重的人', 'https://api.dictionaryapi.dev/media/pronunciations/en/lightweight-us.mp3', 1, '2026-06-01 14:48:14'),
(3643, 'lightweight', 3, '', 'Lacking in earnestness, ability, or profundity', '輕量級的、微不足道的', 'https://api.dictionaryapi.dev/media/pronunciations/en/lightweight-us.mp3', 1, '2026-06-01 14:48:14'),
(3644, 'like', 1, '/laɪk/', '(usually in the plural) Something that a person likes (prefers).', '相像的人或物、喜好', 'https://api.dictionaryapi.dev/media/pronunciations/en/like-us.mp3', 1, '2026-06-01 14:48:14'),
(3645, 'like', 2, '/laɪk/', 'To enjoy, be pleased by; favor; be in favor of.', '喜歡、喜愛', 'https://api.dictionaryapi.dev/media/pronunciations/en/like-us.mp3', 1, '2026-06-01 14:48:14'),
(3646, 'like', 5, '/laɪk/', '(usually in the plural) Something that a person likes (prefers).', '像、如同（此處代碼 5 視為介係詞/連接詞用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/like-us.mp3', 1, '2026-06-01 14:48:14'),
(3647, 'likelihood', 1, '/ˈlaɪklihʊd/', 'The probability of a specified outcome; the chance of something happening; probability; the state or degree of being probable.', '可能性、機率', 'https://dictionaryapi.dev/likelihood', 1, '2026-06-01 14:48:14'),
(3648, 'likely', 3, '/ˈlaɪkli/', 'Probable; having a greater-than-even chance of occurring', '很可能的、合適的', 'https://api.dictionaryapi.dev/media/pronunciations/en/likely-us.mp3', 1, '2026-06-01 14:48:14'),
(3649, 'likewise', 4, '/ˈlaɪkˌwaɪz/', '(manner) In a similar manner.', '同樣地、照樣地', 'https://api.dictionaryapi.dev/media/pronunciations/en/likewise-us.mp3', 1, '2026-06-01 14:48:14'),
(3650, 'lily', 1, '/ˈlɪli/', 'Any of several flowers in the genus Lilium of the family Liliaceae, which includes a great many ornamental species.', '百合花', 'https://api.dictionaryapi.dev/media/pronunciations/en/lily-us.mp3', 1, '2026-06-01 14:48:14'),
(3651, 'limb', 1, '/lɪm/', 'A major appendage of human or animal, used for locomotion (such as an arm, leg or wing).', '肢、四肢、大樹枝', 'https://api.dictionaryapi.dev/media/pronunciations/en/limb-us.mp3', 1, '2026-06-01 14:48:14'),
(3652, 'limit', 1, '/ˈlɪmt/', 'A restriction; a bound beyond which one may not go.', '限制、界限、極限', 'https://api.dictionaryapi.dev/media/pronunciations/en/limit-us.mp3', 1, '2026-06-01 14:48:14'),
(3653, 'limit', 2, '/ˈlɪmt/', 'A restriction; a bound beyond which one may not go.', '限制、限定', 'https://api.dictionaryapi.dev/media/pronunciations/en/limit-us.mp3', 1, '2026-06-01 14:48:14'),
(3654, 'limitation', 1, '/lɪmɪˈteɪʃən/', 'The act of limiting or the state of being limited.', '限制、局限、極限', 'https://api.dictionaryapi.dev/media/pronunciations/en/limitation-us.mp3', 1, '2026-06-01 14:48:14'),
(3655, 'limited', 3, '/ˈlɪmɪtɪd/', 'With certain (often specified) limits placed upon it.', '有限的、受限的', 'https://api.dictionaryapi.dev/media/pronunciations/en/limited-us.mp3', 1, '2026-06-01 14:48:14'),
(3656, 'limp', 2, '/lɪmp/', 'To walk lamely, as if favouring one leg.', '跛行、一瘸一拐地走', 'https://api.dictionaryapi.dev/media/pronunciations/en/limp-us.mp3', 1, '2026-06-01 14:48:14'),
(3657, 'line', 1, '/laɪn/', 'A path through two or more points (compare ‘segment’); a continuous mark, including as made by a pen; any path, curved or straight.', '線、線條、排、隊伍、行業', 'https://api.dictionaryapi.dev/media/pronunciations/en/line-au.mp3', 1, '2026-06-01 14:48:14'),
(3658, 'line', 2, '/laɪn/', 'To place (objects) into a line (usually used with \"up\"); to form into a line; to align.', '排隊、畫線於、沿...排成一列', 'https://api.dictionaryapi.dev/media/pronunciations/en/line-au.mp3', 1, '2026-06-01 14:48:14'),
(3659, 'linen', 1, '/ˈlɪnɪn/', 'Thread or cloth made from flax fiber.', '亞麻布、亞麻製品', 'https://api.dictionaryapi.dev/media/pronunciations/en/linen-us.mp3', 1, '2026-06-01 14:48:14'),
(3660, 'linger', 2, '/ˈlɪŋɡə/', 'To stay or remain in a place or situation, especially as if unwilling to depart or not easily able to do so; to loiter.', '逗留、徘徊、苟延殘喘', 'https://dictionaryapi.dev/linger', 1, '2026-06-01 14:48:14'),
(3661, 'lingering', 3, '', 'To stay or remain in a place or situation, especially as if unwilling to depart or not easily able to do so; to loiter.', '拖延的、揮之不去的、 lingering 纏綿的', 'https://api.dictionaryapi.dev/media/pronunciations/en/lingering-us.mp3', 1, '2026-06-01 14:48:14'),
(3662, 'linguist', 1, '/ˈliŋɡwɪst/', 'One who studies linguistics.', '語言學家、通曉多種語言的人', 'https://dictionaryapi.dev/linguist', 1, '2026-06-01 14:48:14'),
(3663, 'linguistics', 1, '/liŋˈɡwɪstɪks/', 'The scientific study of language.', '語言學', 'https://api.dictionaryapi.dev/media/pronunciations/en/linguistics-us.mp3', 1, '2026-06-01 14:48:14'),
(3664, 'link', 1, '/lɪŋk/', 'Some text or a graphic in an electronic document that can be activated to display another document or trigger an action.', '連結、環、關係', 'https://api.dictionaryapi.dev/media/pronunciations/en/link-us.mp3', 1, '2026-06-01 14:48:14'),
(3665, 'link', 2, '/lɪŋk/', 'To connect two or more things.', '連結、聯合、連線', 'https://api.dictionaryapi.dev/media/pronunciations/en/link-us.mp3', 1, '2026-06-01 14:48:14'),
(3666, 'lion', 1, '/ˈlaɪən/', 'A big cat, Panthera leo, native to Africa, India and formerly much of Europe.', '獅子', 'https://api.dictionaryapi.dev/media/pronunciations/en/lion-us.mp3', 1, '2026-06-01 14:48:14'),
(3667, 'lip', 1, '/lɪp/', 'Either of the two fleshy protrusions around the opening of the mouth.', '嘴唇、邊緣', 'https://api.dictionaryapi.dev/media/pronunciations/en/lip-us.mp3', 1, '2026-06-01 14:48:14'),
(3668, 'lipstick', 1, '/ˈlɪpˌstɪk/', 'Makeup for the lips.', '口紅、唇膏', 'https://api.dictionaryapi.dev/media/pronunciations/en/lipstick-us.mp3', 1, '2026-06-01 14:48:14'),
(3669, 'liquid', 1, '/ˈlɪkwɪd/', 'A substance that is flowing, and keeping no shape, such as water; a substance of which the molecules, while not tending to separate from one another like those of a gas, readily change their relative position, and which therefore retains no definite shape, except that determined by the containing receptacle; an inelastic fluid.', '液體', 'https://api.dictionaryapi.dev/media/pronunciations/en/liquid-us.mp3', 1, '2026-06-01 14:48:14'),
(3670, 'liquidation', 1, '/ˌlɪkwəˈdeɪʃən/', 'The act of exchange of an asset of lesser liquidity with a more liquid one, such as cash.', '清算、結算、公司解散', 'https://dictionaryapi.dev/liquidation', 1, '2026-06-01 14:48:14'),
(3671, 'liquor', 1, '/ˈlɪk.ə(ɹ)/', 'A liquid, a fluid.', '烈酒、含酒精飲料', 'https://api.dictionaryapi.dev/media/pronunciations/en/liquor-uk.mp3', 1, '2026-06-01 14:48:14'),
(3672, 'list', 1, '/lɪst/', 'A strip of fabric, especially from the edge of a piece of cloth.', '名單、目錄、表', 'https://api.dictionaryapi.dev/media/pronunciations/en/list-au.mp3', 1, '2026-06-01 14:48:14'),
(3673, 'list', 2, '/lɪst/', 'To create or recite a list.', '列出、列入表內', 'https://api.dictionaryapi.dev/media/pronunciations/en/list-au.mp3', 1, '2026-06-01 14:48:14'),
(3674, 'listen', 2, '/ˈlɪs.ən/', 'To pay attention to a sound or speech.', '聽、傾聽、聽從', 'https://api.dictionaryapi.dev/media/pronunciations/en/listen-au.mp3', 1, '2026-06-01 14:48:14'),
