(3852, 'maximum', 1, '/ˈmæksɪməm/', 'The highest limit', '最大量、最大限度、極大', 'https://api.dictionaryapi.dev/media/pronunciations/en/maximum-au.mp3', 1, '2026-06-01 14:48:14'),
(3853, 'May', 1, '/meɪ/', 'To be strong; to have power (over).', '五月', 'https://api.dictionaryapi.dev/media/pronunciations/en/may-us.mp3', 1, '2026-06-01 14:48:14'),
(3854, 'maybe', 4, '/ˈmeɪbi/', 'Modifies a verb, indicating a lack of certainty: it may be that...', '也許、可能', 'https://api.dictionaryapi.dev/media/pronunciations/en/maybe-uk.mp3', 1, '2026-06-01 14:48:14'),
(3855, 'mayor', 1, '/ˈmeɪ.ə/', 'The chief executive of the municipal government of a city, borough, &c., formerly usually appointed as a caretaker by European royal courts but now usually appointed or elected locally.', '市長、鎮長', 'https://api.dictionaryapi.dev/media/pronunciations/en/mayor-us.mp3', 1, '2026-06-01 14:48:14'),
(3856, 'meadow', 1, '/ˈmɛdəʊ/', 'A field or pasture; a piece of land covered or cultivated with grass, usually intended to be mown for hay.', '牧草地、草地', 'https://api.dictionaryapi.dev/media/pronunciations/en/meadow-us.mp3', 1, '2026-06-01 14:48:14'),
(3857, 'meal', 1, '/miːl/', 'Food that is prepared and eaten, usually at a specific time, and usually in a comparatively large quantity (as opposed to a snack).', '一餐、膳食', 'https://api.dictionaryapi.dev/media/pronunciations/en/meal-uk.mp3', 1, '2026-06-01 14:48:14'),
(3858, 'mean', 2, '/miːn/', 'To lament.', '意指、打算、意味著', 'https://api.dictionaryapi.dev/media/pronunciations/en/mean-us.mp3', 1, '2026-06-01 14:48:14'),
(3859, 'mean', 3, '/miːn/', 'To lament.', '卑鄙的、刻薄的、吝嗇的、平均的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mean-us.mp3', 1, '2026-06-01 14:48:14'),
(3860, 'meaning', 1, '/ˈmiːnɪŋ/', '(of words or symbols) The entity, perception, feeling or concept thereby represented or evoked.', '意思、意義、意圖', 'https://api.dictionaryapi.dev/media/pronunciations/en/meaning-us.mp3', 1, '2026-06-01 14:48:14'),
(3861, 'meaningful', 3, '/ˈminɪŋfʊl/', 'Having meaning, significant.', '有意義的、意味深長的', 'https://dictionaryapi.dev/meaningful', 1, '2026-06-01 14:48:14'),
(3862, 'meaningless', 3, '', 'Lacking meaning.', '無意義的、徒勞的', 'https://api.dictionaryapi.dev/media/pronunciations/en/meaningless-us.mp3', 1, '2026-06-01 14:48:14'),
(3863, 'means', 1, '/miːnz/', '(now chiefly in the plural) A method or course of action used to achieve some result.', '方法、手段、工具、財產', 'https://api.dictionaryapi.dev/media/pronunciations/en/means-us.mp3', 1, '2026-06-01 14:48:14'),
(3864, 'meanwhile', 4, '/ˈmiːnhwaɪl/', 'During the time that something is happening.', '同時、其間', 'https://dictionaryapi.dev/meanwhile', 1, '2026-06-01 14:48:14'),
(3865, 'measles', 1, '/ˈmiːzəlz/', 'Rubeola, an acute highly contagious disease, often of childhood, caused by Measles virus, of genus Morbillivirus, featuring a spreading red skin rash, fever, runny nose, cough and red eyes', '麻疹', 'https://api.dictionaryapi.dev/media/pronunciations/en/measles-us.mp3', 1, '2026-06-01 14:48:14'),
(3866, 'measure', 1, '/ˈmɛʒə/', 'A prescribed quantity or extent.', '尺寸、量度、措施、辦法', 'https://api.dictionaryapi.dev/media/pronunciations/en/measure-uk.mp3', 1, '2026-06-01 14:48:14'),
(3867, 'measure', 2, '/ˈmɛʒə/', 'To ascertain the quantity of a unit of material via calculated comparison with respect to a standard.', '測量、計量、估計', 'https://api.dictionaryapi.dev/media/pronunciations/en/measure-uk.mp3', 1, '2026-06-01 14:48:14'),
(3868, 'meat', 1, '/miːt/', 'The flesh (muscle tissue) of an animal used as food.', '肉、肉類', 'https://api.dictionaryapi.dev/media/pronunciations/en/meat-uk.mp3', 1, '2026-06-01 14:48:14'),
(3869, 'mechanical', 3, '/mɪˈkanɪk(ə)l/', 'Characteristic of someone who does manual labour for a living; coarse, vulgar.', '機械的、機械製的、呆板的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mechanical-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(3870, 'mechanics', 1, '', 'The branch of physics that deals with the action of forces on material objects with mass', '力學、機械學、技術細節', 'https://dictionaryapi.dev/mechanics', 1, '2026-06-01 14:48:14'),
(3871, 'medal', 1, '[ˈmeɾ.ɫ̩]', 'A stamped metal disc used as a personal ornament, a charm, or a religious object.', '獎章、勳章', 'https://api.dictionaryapi.dev/media/pronunciations/en/medal-uk.mp3', 1, '2026-06-01 14:48:14'),
(3872, 'media', 1, '/ˈmiːdɪə/', 'The middle layer of the wall of a blood vessel or lymph vessel which is composed of connective and muscular tissue.', '媒體、媒介物（medium的複數）', 'https://dictionaryapi.dev/media', 1, '2026-06-01 14:48:14'),
(3873, 'medical', 3, '/ˈmɛdɪkl̩/', 'Of or pertaining to the practice of medicine.', '醫學的、醫療的、內科的', 'https://api.dictionaryapi.dev/media/pronunciations/en/medical-us.mp3', 1, '2026-06-01 14:48:14'),
(3874, 'medication', 1, '/mɛdɪˈkeɪʃən/', 'A medicine, or all the medicines regularly taken by a patient.', '藥物治療、藥物', 'https://dictionaryapi.dev/medication', 1, '2026-06-01 14:48:14'),
(3875, 'medicine', 1, '/ˈmed(ɪ).sn̩/', 'A substance which specifically promotes healing when ingested or consumed in some way.', '藥、醫學、內科學', 'https://api.dictionaryapi.dev/media/pronunciations/en/medicine-uk.mp3', 1, '2026-06-01 14:48:14'),
(3876, 'medieval', 3, '/mɪd.ˈiː.vəl/', 'Of or relating to the Middle Ages, the period from approximately 500 to 1500 AD.', '中世紀的、古風的', 'https://dictionaryapi.dev/medieval', 1, '2026-06-01 14:48:14'),
(3877, 'meditation', 1, '/mɛdɪˈteɪʃən/', 'A devotional exercise of, or leading to contemplation.', '冥想、沉思', 'https://dictionaryapi.dev/meditation', 1, '2026-06-01 14:48:14'),
(3878, 'medium', 1, '/ˈmiːdɪəm/', '(plural media or mediums) The chemistry of the surrounding environment, e.g. solid, liquid, gas, vacuum, or a specific substance such as a solvent.', '媒介、方法、宣傳工具、中庸', 'https://api.dictionaryapi.dev/media/pronunciations/en/medium-us.mp3', 1, '2026-06-01 14:48:14'),
(3879, 'meek', 3, '/miːk/', 'Humble, non-boastful, modest, meager, or self-effacing.', '溫順的、謙卑的、懦弱的', 'https://api.dictionaryapi.dev/media/pronunciations/en/meek-uk.mp3', 1, '2026-06-01 14:48:14'),
(3880, 'meet', 2, '/miːt/', 'To make contact (with) while in proximity.', '遇見、會面、滿足、符合', 'https://api.dictionaryapi.dev/media/pronunciations/en/meet-uk.mp3', 1, '2026-06-01 14:48:14'),
(3881, 'meeting', 1, '/ˈmiːtɪŋ/', '(gerund) The act of persons or things that meet.', '會議、集會、匯合點', 'https://api.dictionaryapi.dev/media/pronunciations/en/meeting-us.mp3', 1, '2026-06-01 14:48:14'),
(3882, 'melancholy', 1, '/ˈmelənkəli/', 'Black bile, formerly thought to be one of the four \"cardinal humours\" of animal bodies.', '憂鬱、悲傷', 'https://api.dictionaryapi.dev/media/pronunciations/en/melancholy-us.mp3', 1, '2026-06-01 14:48:14'),
(3883, 'melancholy', 3, '/ˈmelənkəli/', 'Affected with great sadness or depression.', '憂鬱的、令人傷感的', 'https://api.dictionaryapi.dev/media/pronunciations/en/melancholy-us.mp3', 1, '2026-06-01 14:48:14'),
(3884, 'mellow', 3, '/ˈmɛləʊ/', 'Soft or tender by reason of ripeness; having a tender pulp.', '成熟潤熟的、柔和的、醇香的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mellow-us.mp3', 1, '2026-06-01 14:48:14'),
(3885, 'melody', 1, '/ˈmel.ə.di/', 'Tune; sequence of notes that makes up a musical phrase', '旋律、曲調', 'https://api.dictionaryapi.dev/media/pronunciations/en/melody-us.mp3', 1, '2026-06-01 14:48:14'),
(3886, 'melon', 1, '/ˈmɛlən/', 'Any of various plants of the family Cucurbitaceae grown for food, generally not including the cucumber.', '瓜、甜瓜', 'https://api.dictionaryapi.dev/media/pronunciations/en/melon-au.mp3', 1, '2026-06-01 14:48:14'),
(3887, 'melt', 2, '/mɛlt/', 'To change (or to be changed) from a solid state to a liquid state, usually by a gradual heat.', '融化、熔化、消散', 'https://api.dictionaryapi.dev/media/pronunciations/en/melt-us.mp3', 1, '2026-06-01 14:48:14'),
(3888, 'member', 1, '', 'One who officially belongs to a group.', '會員、成員', 'https://api.dictionaryapi.dev/media/pronunciations/en/member-1-au.mp3', 1, '2026-06-01 14:48:14'),
(3889, 'membership', 1, '', 'The state of being a member of a group or organization.', '會員資格、全體會員', 'https://api.dictionaryapi.dev/media/pronunciations/en/membership-us.mp3', 1, '2026-06-01 14:48:14'),
(3890, 'memo', 1, '/ˈmɛməʊ̯/', 'A short note; a memorandum.', '備忘錄、便條', 'https://dictionaryapi.dev/memo', 1, '2026-06-01 14:48:14'),
(3891, 'memorable', 3, '/ˈmɛm(ə)ɹəbl̩/', 'Worthy to be remembered; very important or remarkable.', '值得紀念的、難忘的', 'https://dictionaryapi.dev/memorable', 1, '2026-06-01 14:48:14'),
(3892, 'memorial', 1, '/məˈmoʊɹi.əl/', 'Memory; recollection.', '紀念碑、紀念物、紀念館', 'https://api.dictionaryapi.dev/media/pronunciations/en/memorial-uk.mp3', 1, '2026-06-01 14:48:14'),
(3893, 'memorial', 3, '/məˈmoʊɹi.əl/', 'Serving as a remembrance of someone or something; commemorative.', '紀念的、追悼的', 'https://api.dictionaryapi.dev/media/pronunciations/en/memorial-uk.mp3', 1, '2026-06-01 14:48:14'),
(3894, 'memorize', 2, '/ˈmɛm.əɹˌaɪ̯z/', 'To learn by heart, commit to memory.', '記住、背誦、熟記', 'https://api.dictionaryapi.dev/media/pronunciations/en/memorize-us.mp3', 1, '2026-06-01 14:48:14'),
(3895, 'men', 1, '/mɛn/', 'An adult male human.', '男人、人類（man的複數）', 'https://api.dictionaryapi.dev/media/pronunciations/en/men-us.mp3', 1, '2026-06-01 14:48:14'),
(3896, 'menace', 1, '/ˈmɛnɪs/', 'A perceived threat or danger.', '威脅、恐嚇、危險的事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/menace-uk.mp3', 1, '2026-06-01 14:48:14'),
(3897, 'mental', 3, '/ˈmɛntəl/', 'Of or relating to the mind or an intellectual process.', '精神的、心理的、智力的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mental-us.mp3', 1, '2026-06-01 14:48:14'),
(3898, 'mentality', 1, '/-ɪti/', 'A mindset; a way of thinking; a set of beliefs.', '心態、智力、思想狀況', 'https://api.dictionaryapi.dev/media/pronunciations/en/mentality-us.mp3', 1, '2026-06-01 14:48:14'),
(3899, 'mentally', 4, '/ˈmɛntəli/', 'In a mental manner; an idea thought out in one\'s mind, as opposed to an idea spoken orally.', '精神上、心理上、智力上', 'https://api.dictionaryapi.dev/media/pronunciations/en/mentally-us.mp3', 1, '2026-06-01 14:48:14'),
(3900, 'mention', 1, '/ˈmɛnʃən/', 'A speaking or notice of anything, usually in a brief or cursory manner. Used especially in the phrase make mention of.', '提及、說起', 'https://api.dictionaryapi.dev/media/pronunciations/en/mention-us.mp3', 1, '2026-06-01 14:48:14'),
(3901, 'mention', 2, '/ˈmɛnʃən/', 'To make a short reference to something.', '提及、說起、提名表揚', 'https://api.dictionaryapi.dev/media/pronunciations/en/mention-us.mp3', 1, '2026-06-01 14:48:14'),
(3902, 'mentor', 1, '/ˈmɛn.tɔː/', 'A wise and trusted counselor or teacher', '導師、良師益友', 'https://dictionaryapi.dev/mentor', 1, '2026-06-01 14:48:14'),
(3903, 'menu', 1, '/ˈmɛnju/', 'The details of the food to be served at a banquet; a bill of fare.', '菜單、選單', 'https://api.dictionaryapi.dev/media/pronunciations/en/menu-us.mp3', 1, '2026-06-01 14:48:14'),
(3904, 'merchant', 1, '/ˈmɜːtʃənt/', 'A person who traffics in commodities for profit.', '商人、零售商', 'https://api.dictionaryapi.dev/media/pronunciations/en/merchant-us.mp3', 1, '2026-06-01 14:48:14'),
(3905, 'mercy', 1, '/ˈmɜːsi/', 'Relenting; forbearance to cause or allow harm to another.', '慈悲、憐憫、仁慈', 'https://api.dictionaryapi.dev/media/pronunciations/en/mercy-us.mp3', 1, '2026-06-01 14:48:14'),
(3906, 'mere', 3, '', 'A body of standing water, such as a lake or a pond. More specifically, it can refer to a lake that is broad in relation to its depth. Also included in place names such as Windermere.', '僅僅的、只不過的', 'https://dictionaryapi.dev/mere', 1, '2026-06-01 14:48:14'),
(3907, 'merit', 1, '/ˈmɛɹət/', 'A claim to commendation or a reward.', '優點、價值、功績', 'https://api.dictionaryapi.dev/media/pronunciations/en/merit-us.mp3', 1, '2026-06-01 14:48:14'),
(3908, 'merry', 3, '/ˈmɛɹi/', 'Jolly and full of high spirits.', '快樂的、歡樂的', 'https://api.dictionaryapi.dev/media/pronunciations/en/merry-us.mp3', 1, '2026-06-01 14:48:14'),
(3909, 'mess', 1, '/mɛs/', 'A disagreeable mixture or confusion of things; hence, a situation resulting from blundering or from misunderstanding; disorder.', '混亂、髒亂、困境', 'https://api.dictionaryapi.dev/media/pronunciations/en/mess-us.mp3', 1, '2026-06-01 14:48:14'),
(3910, 'message', 1, '/ˈmɛsɪd͡ʒ/', 'A communication, or what is communicated; any concept or information conveyed.', '訊息、口信、啟示', 'https://api.dictionaryapi.dev/media/pronunciations/en/message-us.mp3', 1, '2026-06-01 14:48:14'),
(3911, 'messenger', 1, '/ˈmɛs.n̩.d͡ʒə/', 'One who brings messages.', '送信者、信差、使者', 'https://api.dictionaryapi.dev/media/pronunciations/en/messenger-us.mp3', 1, '2026-06-01 14:48:14'),
(3912, 'metal', 1, '/ˈmɛtəl/', '(heading) Chemical elements or alloys, and the mines where their ores come from.', '金屬', 'https://api.dictionaryapi.dev/media/pronunciations/en/metal-uk.mp3', 1, '2026-06-01 14:48:14'),
(3913, 'metaphor', 1, '/ˈmɛt.ə.fɔː(ɹ)/', 'The use of a word or phrase to refer to something that it is not, invoking a direct similarity between the word or phrase used and the thing described (but in the case of English without the words like or as, since use of those words would imply a simile); the word or phrase used in this way; an implied comparison.', '隱喻、暗喻', 'https://api.dictionaryapi.dev/media/pronunciations/en/metaphor-uk.mp3', 1, '2026-06-01 14:48:14'),
(3914, 'metaphysical', 3, '/ˌmɛtəˈfɪzɪkəl/', 'Of or pertaining to metaphysics.', '形上學的、抽象的、超自然氣質的', 'https://dictionaryapi.dev/metaphysical', 1, '2026-06-01 14:48:14'),
(3915, 'meter', 1, '/ˈmiːtə/', '(always meter) A device that measures things.', '公尺、計量器、儀表', 'https://api.dictionaryapi.dev/media/pronunciations/en/meter-us.mp3', 1, '2026-06-01 14:48:14'),
(3916, 'method', 1, '/ˈmɛθəd/', 'A process by which a task is completed; a way of doing something (followed by the adposition of, to or for before the purpose of the process):', '方法、條理、方式', 'https://api.dictionaryapi.dev/media/pronunciations/en/method-us.mp3', 1, '2026-06-01 14:48:14'),
(3917, 'microphone', 1, '/ˈmaɪ.kɹəˌfəʊn/', 'A device (transducer) used to convert sound waves into a varying electric current; normally fed into an amplifier and either recorded or broadcast.', '麥克風、話筒', 'https://dictionaryapi.dev/microphone', 1, '2026-06-01 14:48:14'),
(3918, 'microwave', 1, '/ˈmaɪkɹəʊˌweɪv/', 'An electromagnetic wave with wavelength between that of infrared light and radio waves.', '微波、微波爐', 'https://dictionaryapi.dev/microwave', 1, '2026-06-01 14:48:14'),
(3919, 'middle', 1, '/ˈmɪdəl/', 'A centre, midpoint.', '中間、中部', 'https://api.dictionaryapi.dev/media/pronunciations/en/middle-au.mp3', 1, '2026-06-01 14:48:14'),
(3920, 'middle', 3, '/ˈmɪdəl/', 'Located in the middle; in between.', '中間的、中級的', 'https://api.dictionaryapi.dev/media/pronunciations/en/middle-au.mp3', 1, '2026-06-01 14:48:14'),
(3921, 'midnight', 1, '/ˈmɪdnʌɪt/', 'The middle of the night: the sixth temporal hour, equidistant between sunset and sunrise.', '午夜、子夜', 'https://api.dictionaryapi.dev/media/pronunciations/en/midnight-us.mp3', 1, '2026-06-01 14:48:14'),
(3922, 'mighty', 3, '/ˈmaɪti/', 'Very strong; possessing might.', '強大的、有力的、巨大的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mighty-us.mp3', 1, '2026-06-01 14:48:14'),
(3923, 'migration', 1, '/maɪˈɡɹeɪʃ(ə)n/', 'An instance of moving to live in another place for a while.', '遷移、移居、遷徙', 'https://dictionaryapi.dev/migration', 1, '2026-06-01 14:48:14'),
(3924, 'mild', 3, '/ˈmaɪld/', 'Gentle and not easily angered.', '溫和的、輕微的、溫柔的', 'https://api.dictionaryapi.dev/media/pronunciations/en/mild-us.mp3', 1, '2026-06-01 14:48:14'),
(3925, 'mileage', 1, '/ˈmaɪlədʒ/', 'The total distance travelled in miles or in air miles.', '英里數、里程、油耗', 'https://dictionaryapi.dev/mileage', 1, '2026-06-01 14:48:14'),
(3926, 'militant', 3, '/ˈmɪlɪtənt/', 'Fighting or disposed to fight; belligerent, warlike.', '好戰的、激進的', 'https://dictionaryapi.dev/militant', 1, '2026-06-01 14:48:14'),
(3927, 'military', 1, '/ˈmɪl.ɪ.tɹi/', 'Armed forces.', '軍隊、軍方（恆用複數）', 'https://api.dictionaryapi.dev/media/pronunciations/en/military-us.mp3', 1, '2026-06-01 14:48:14'),
(3928, 'military', 3, '/ˈmɪl.ɪ.tɹi/', 'Characteristic of members of the armed forces.', '軍事的、軍隊的', 'https://api.dictionaryapi.dev/media/pronunciations/en/military-us.mp3', 1, '2026-06-01 14:48:14'),
(3929, 'milk', 1, '[mɛlk]', 'A white liquid produced by the mammary glands of female mammals to nourish their young. From certain animals, especially cows, it is also called dairy milk and is a common food for humans as a beverage or used to produce various dairy products such as butter, cheese, and yogurt.', '牛奶', 'https://api.dictionaryapi.dev/media/pronunciations/en/milk-uk.mp3', 1, '2026-06-01 14:48:14'),
(3930, 'milk', 2, '[mɛlk]', 'A white liquid produced by the mammary glands of female mammals to nourish their young. From certain animals, especially cows, it is also called dairy milk and is a common food for humans as a beverage or used to produce various dairy products such as butter, cheese, and yogurt.', '擠奶、榨取', 'https://api.dictionaryapi.dev/media/pronunciations/en/milk-uk.mp3', 1, '2026-06-01 14:48:14'),
(3931, 'mill', 1, '/mɪl/', 'A grinding apparatus for substances such as grains, seeds, etc.', '磨坊、製造廠、壓榨機', 'https://api.dictionaryapi.dev/media/pronunciations/en/mill-us.mp3', 1, '2026-06-01 14:48:14'),
(3932, 'mill', 2, '/mɪl/', 'To grind or otherwise process in a mill or other machine.', '碾碎、磨、攪拌', 'https://api.dictionaryapi.dev/media/pronunciations/en/mill-us.mp3', 1, '2026-06-01 14:48:14'),
(3933, 'milligram', 1, '/ˈmɪlɪɡɹæm/', 'An SI unit of mass, equivalent to one thousandth of a gram. Symbol: mg', '毫克', 'https://dictionaryapi.dev/milligram', 1, '2026-06-01 14:48:14'),
(3934, 'million', 1, '/ˈmɪljən/', '(long and short scales) The cardinal number 1,000,000: 106; a thousand thousand.', '百萬', 'https://api.dictionaryapi.dev/media/pronunciations/en/million-uk.mp3', 1, '2026-06-01 14:48:14'),
