(4187, 'novel', 1, '/ˈnɒvl̩/', 'Newly made, formed or evolved; having no precedent; of recent origin; new.', '小說', 'https://api.dictionaryapi.dev/media/pronunciations/en/novel-us.mp3', 1, '2026-06-01 14:48:14'),
(4188, 'novel', 3, '/ˈnɒvl̩/', 'Newly made, formed or evolved; having no precedent; of recent origin; new.', '新奇的、新穎的', 'https://api.dictionaryapi.dev/media/pronunciations/en/novel-us.mp3', 1, '2026-06-01 14:48:14'),
(4189, 'novelist', 1, '/ˈnɒvəlɪst/', 'An author of novels.', '小說家', 'https://dictionaryapi.dev/novelist', 1, '2026-06-01 14:48:14'),
(4190, 'novelty', 1, '/ˈnɒvəlti/', 'The state of being new or novel; newness.', '新奇、新穎、新奇事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/novelty-us.mp3', 1, '2026-06-01 14:48:14'),
