(4280, 'original', 3, '/əˈɹɪdʒnəl/', 'Relating to the origin or beginning; preceding all others', '最初的、原始的、獨創的', 'https://api.dictionaryapi.dev/media/pronunciations/en/original-us.mp3', 1, '2026-06-01 14:48:14'),
(4281, 'originality', 1, '/əˌɹɪdʒɪˈnælɪti/', 'The quality of being original or novel.', '獨創性、新穎、創意', 'https://dictionaryapi.dev/originality', 1, '2026-06-01 14:48:14'),
(4282, 'ornament', 1, '/ˈɔː(ɹ)nəmənt/', 'An element of decoration; that which embellishes or adorns.', '裝飾品、裝飾', 'https://api.dictionaryapi.dev/media/pronunciations/en/ornament-us-noun.mp3', 1, '2026-06-01 14:48:14'),
(4283, 'orphan', 1, '/ˈɔːfən/', 'A person, especially a minor, both or (rarely) one of whose parents have died.', '孤兒', 'https://api.dictionaryapi.dev/media/pronunciations/en/orphan-us.mp3', 1, '2026-06-01 14:48:14'),
(4284, 'orphanage', 1, '/ˈɔː(ɹ)fənɪd͡ʒ/', 'A residential institution for the care and protection of orphans.', '孤兒院', 'https://dictionaryapi.dev/orphanage', 1, '2026-06-01 14:48:14'),
(4285, 'orthodox', 3, '/ˈɔːθədɒks/', 'Conforming to the accepted, established, or traditional doctrines of a given faith, religion, or ideology.', '正統的、傳統的、普遍接受的', 'https://api.dictionaryapi.dev/media/pronunciations/en/orthodox-us.mp3', 1, '2026-06-01 14:48:14'),
(4286, 'other', 1, '/ˈɐðə/', 'An other, another (person, etc), more often rendered as another.', '其他人、別的東西', 'https://api.dictionaryapi.dev/media/pronunciations/en/other-uk.mp3', 1, '2026-06-01 14:48:14'),
(4287, 'other', 3, '/ˈɐðə/', 'See other (determiner) below', '其他的、另外的', 'https://api.dictionaryapi.dev/media/pronunciations/en/other-uk.mp3', 1, '2026-06-01 14:48:14'),
(4288, 'otherwise', 4, '/ˈʌð.əˌwaɪz/', '(manner) Differently, in another way.', '否則、在其他方面、要不然', 'https://api.dictionaryapi.dev/media/pronunciations/en/otherwise-us.mp3', 1, '2026-06-01 14:48:14'),
(4289, 'oust', 2, '/ʌʊst/', 'To expel; to remove.', '驅逐、罷免、革職', 'https://api.dictionaryapi.dev/media/pronunciations/en/oust-us.mp3', 1, '2026-06-01 14:48:14'),
(4290, 'out', 5, '/æɔt/', 'From from the inside to the outside of; out of.', '向外、在外（介系詞/副詞，此處原檔標記 5）', 'https://api.dictionaryapi.dev/media/pronunciations/en/out-au.mp3', 1, '2026-06-01 14:48:14'),
(4291, 'out-of-date', 3, '', 'Alternative form of out of date', '過時的、落伍的', 'https://dictionaryapi.dev/out-of-date', 1, '2026-06-01 14:48:14'),
(4292, 'outbreak', 2, '/ˈaʊtbɹeɪk/', 'To burst out.', '爆發、突然發生（原檔標記 2，常用作名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/outbreak-us.mp3', 1, '2026-06-01 14:48:14'),
(4293, 'outcome', 1, '/ˈaʊtkʌm/', 'That which is produced or occurs as a result of an event or process.', '結果、結局', 'https://dictionaryapi.dev/outcome', 1, '2026-06-01 14:48:14'),
(4294, 'outdoor', 3, '/ˌaʊtˈdɔː/', 'Situated in, designed to be used in, or carried on in the open air.', '戶外的、室外的', 'https://dictionaryapi.dev/outdoor', 1, '2026-06-01 14:48:14'),
(4295, 'outdoors', 4, '', 'Not inside a house or under covered structure; unprotected; in the open air.', '在戶外、在室外', 'https://dictionaryapi.dev/outdoors', 1, '2026-06-01 14:48:14'),
(4296, 'outfit', 1, '/ˈaʊtfɪt/', 'A set of clothing (with accessories).', '全套服裝、裝備、團隊', 'https://api.dictionaryapi.dev/media/pronunciations/en/outfit-uk.mp3', 1, '2026-06-01 14:48:14'),
(4297, 'outing', 1, '/ˈaʊtɪŋ/', 'A pleasure trip or excursion.', '郊遊、遠足', 'https://api.dictionaryapi.dev/media/pronunciations/en/outing-uk.mp3', 1, '2026-06-01 14:48:14'),
(4298, 'outlaw', 1, '', 'A fugitive from the law.', '不法之徒、歹徒、逃犯', 'https://api.dictionaryapi.dev/media/pronunciations/en/outlaw-au.mp3', 1, '2026-06-01 14:48:14'),
(4299, 'outlet', 1, '/ˈaʊtlɛt/', 'A vent or similar passage to allow the escape of something.', '出口、排水口、宣洩管道、暢貨中心', 'https://api.dictionaryapi.dev/media/pronunciations/en/outlet-us.mp3', 1, '2026-06-01 14:48:14'),
(4300, 'outline', 1, '/ˈaʊtlaɪn/', 'A line marking the boundary of an object figure.', '輪廓、大綱、概要', 'https://api.dictionaryapi.dev/media/pronunciations/en/outline-us.mp3', 1, '2026-06-01 14:48:14'),
