(4302, 'outnumber', 2, '', '(stative) to be more in number than somebody or something.', '在數量上超過、比...多', 'https://dictionaryapi.dev/outnumber', 1, '2026-06-01 14:48:14'),
(4303, 'outrage', 1, '/ˈæot.ɹæed͡ʒ/', 'An excessively violent or vicious attack; an atrocity.', '憤怒、暴行、侮辱', 'https://api.dictionaryapi.dev/media/pronunciations/en/outrage-us.mp3', 1, '2026-06-01 14:48:14'),
(4304, 'outrageous', 3, '/aʊtˈɹeɪdʒəs/', 'Violating morality or decency; provoking indignation or affront.', '令人容忍不了的、極其無禮的、駭人聽聞的', 'https://dictionaryapi.dev/outrageous', 1, '2026-06-01 14:48:14'),
(4305, 'outset', 1, '/ˈaʊtsɛt/', 'The beginning or initial stage of something.', '開端、開始', 'https://api.dictionaryapi.dev/media/pronunciations/en/outset-us.mp3', 1, '2026-06-01 14:48:14'),
