(4309, 'outside', 5, '', 'On the outside of, not inside (something, such as a building).', '在...外面（介系詞用法）', 'https://dictionaryapi.dev/outside', 1, '2026-06-01 14:48:14'),
(4310, 'outskirts', 1, '/ˈaʊtskɜːts/', 'The area surrounding a city or town; suburb.', '市郊、郊區', 'https://api.dictionaryapi.dev/media/pronunciations/en/outskirts-us.mp3', 1, '2026-06-01 14:48:14'),
(4311, 'outstanding', 3, '', 'Prominent or noticeable; standing out from others.', '優秀的、傑出的、未付清的', 'https://api.dictionaryapi.dev/media/pronunciations/en/outstanding-us.mp3', 1, '2026-06-01 14:48:14'),
