(4544, 'pigment', 1, '/ˈpɪɡ.mənt/', 'Any color in plant or animal cells', '色素、顏料', 'https://api.dictionaryapi.dev/media/pronunciations/en/pigment-uk.mp3', 1, '2026-06-01 14:48:14'),
(4545, 'pile', 1, '/paɪl/', 'A mass of things heaped together; a heap.', '一堆、大量、建築樁（名詞用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/pile-us.mp3', 1, '2026-06-01 14:48:14'),
(4546, 'pile', 2, '/paɪl/', '(often used with the preposition \"up\") To lay or throw into a pile or heap; to heap up; to collect into a mass; to accumulate', '堆積、累積', 'https://api.dictionaryapi.dev/media/pronunciations/en/pile-us.mp3', 1, '2026-06-01 14:48:14'),
(4547, 'pilgrim', 1, '/ˈpɪlɡɹɪm/', 'One who travels, especially on a journey to visit sites of religious significance.', '朝聖者、香客', 'https://api.dictionaryapi.dev/media/pronunciations/en/pilgrim-au.mp3', 1, '2026-06-01 14:48:14'),
