(4565, 'pipe', 2, '', 'To play (music) on a pipe instrument, such as a bagpipe or a flute.', '用管道輸送、吹笛', 'https://api.dictionaryapi.dev/media/pronunciations/en/pipe-au.mp3', 1, '2026-06-01 14:48:14'),
(4566, 'pipeline', 1, '/ˈpaɪpˌlaɪn/', 'A conduit made of pipes used to convey water, gas or petroleum etc.', '管道、管線、物資供應線', 'https://dictionaryapi.dev/pipeline', 1, '2026-06-01 14:48:14'),
(4567, 'pirate', 1, '/ˈpaɪ̯(ə)ɹət/', 'A criminal who plunders at sea; commonly attacking merchant vessels, though often pillaging port towns.', '海盜、盜版者', 'https://api.dictionaryapi.dev/media/pronunciations/en/pirate-us.mp3', 1, '2026-06-01 14:48:14'),
(4568, 'piston', 1, '/ˈpɪstən/', 'A solid disk or cylinder that fits inside a hollow cylinder, and moves under pressure (as in an engine) or displaces fluid (as in a pump)', '活塞', 'https://api.dictionaryapi.dev/media/pronunciations/en/piston-us.mp3', 1, '2026-06-01 14:48:14'),
(4569, 'pit', 1, '/ˈpɪt/', 'A hole in the ground.', '深坑、礦井、陷阱、果核', 'https://api.dictionaryapi.dev/media/pronunciations/en/pit.mp3', 1, '2026-06-01 14:48:14'),
(4570, 'pitch', 1, '/pɪtʃ/', 'A sticky, gummy substance secreted by trees; sap.', '音高、瀝青、投球、強度', 'https://api.dictionaryapi.dev/media/pronunciations/en/pitch-au.mp3', 1, '2026-06-01 14:48:14'),
(4571, 'pitcher', 1, '/ˈpɪtʃə/', 'One who pitches anything, as hay, quoits, a ball, etc.', '大水罐、投手', 'https://dictionaryapi.dev/pitcher', 1, '2026-06-01 14:48:14'),
