(4574, 'place', 1, '/pleɪs/', '(physical) An area; somewhere within an area.', '地方、地點、位置、職位', 'https://api.dictionaryapi.dev/media/pronunciations/en/place-uk.mp3', 1, '2026-06-01 14:48:14'),
(4575, 'place', 2, '/pleɪs/', '(physical) An area; somewhere within an area.', '放置、安置、任命、投寄', 'https://api.dictionaryapi.dev/media/pronunciations/en/place-uk.mp3', 1, '2026-06-01 14:48:14'),
(4576, 'plague', 1, '/pleɪɡ/', '(often used with the, sometimes capitalized: the Plague) The bubonic plague, the pestilent disease caused by the virulent bacterium Yersinia pestis.', '瘟疫、天災、麻煩事', 'https://api.dictionaryapi.dev/media/pronunciations/en/plague-us.mp3', 1, '2026-06-01 14:48:14'),
(4577, 'plague', 2, '/pleɪɡ/', 'To harass, pester or annoy someone persistently or incessantly.', '折磨、使苦惱、纏擾', 'https://api.dictionaryapi.dev/media/pronunciations/en/plague-us.mp3', 1, '2026-06-01 14:48:14'),
(4578, 'plain', 3, '/pleɪn/', 'Flat, level.', '樸素的、簡單的、清楚的、相貌平平的', 'https://api.dictionaryapi.dev/media/pronunciations/en/plain-us.mp3', 1, '2026-06-01 14:48:14'),
(4579, 'plainly', 4, '/ˈpleɪnli/', 'In a plain manner; simply; basically.', '清清楚楚地、坦白地、樸素地', 'https://api.dictionaryapi.dev/media/pronunciations/en/plainly-us.mp3', 1, '2026-06-01 14:48:14'),
(4580, 'plan', 1, '/plæn/', 'A drawing showing technical details of a building, machine, etc., with unwanted details omitted, and often using symbols rather than detailed drawing to represent doors, valves, etc.', '計劃、打算、平面圖', 'https://api.dictionaryapi.dev/media/pronunciations/en/plan-us.mp3', 1, '2026-06-01 14:48:14'),
(4581, 'plan', 2, '/plæn/', 'To design (a building, machine, etc.).', '計劃、打算、設計', 'https://api.dictionaryapi.dev/media/pronunciations/en/plan-us.mp3', 1, '2026-06-01 14:48:14'),
(4582, 'plane', 1, '/pleɪn/', 'A level or flat surface.', '飛機、平面', 'https://api.dictionaryapi.dev/media/pronunciations/en/plane-us.mp3', 1, '2026-06-01 14:48:14'),
(4583, 'planet', 1, '/ˈplænət/', 'Each of the seven major bodies which move relative to the fixed stars in the night sky—the Moon, Mercury, Venus, the Sun, Mars, Jupiter and Saturn.', '行星', 'https://api.dictionaryapi.dev/media/pronunciations/en/planet-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(4584, 'planetary', 3, '/ˈplæ.nə.ˌtɛr.i/', 'Of, or relating to planets, or the orbital motion of planets.', '行星的、在全球範圍的', 'https://api.dictionaryapi.dev/media/pronunciations/en/planetary-uk.mp3', 1, '2026-06-01 14:48:14'),
(4585, 'planning', 1, '/ˈplænɪŋ/', 'Action of the verb to plan.', '計畫、規劃', 'https://dictionaryapi.dev/planning', 1, '2026-06-01 14:48:14'),
(4586, 'plant', 1, '/plænt/', 'An organism that is not an animal, especially an organism capable of photosynthesis. Typically a small or herbaceous organism of this kind, rather than a tree.', '植物、工廠、車間', 'https://api.dictionaryapi.dev/media/pronunciations/en/plant-uk.mp3', 1, '2026-06-01 14:48:14'),
(4587, 'plant', 2, '/plænt/', 'To place (a seed or plant) in soil or other substrate in order that it may live and grow.', '種植、栽種、安置', 'https://api.dictionaryapi.dev/media/pronunciations/en/plant-uk.mp3', 1, '2026-06-01 14:48:14'),
(4588, 'plantation', 1, '/plænˈteɪʃən/', 'A large farm; estate or area of land designated for agricultural growth. Often includes housing for the owner and workers.', '大農場、種植園', 'https://api.dictionaryapi.dev/media/pronunciations/en/plantation-us.mp3', 1, '2026-06-01 14:48:14'),
(4589, 'plaster', 1, '/ˈplastə/', 'A paste applied to the skin for healing or cosmetic purposes.', '熟石膏、灰泥、灰泥牆', 'https://api.dictionaryapi.dev/media/pronunciations/en/plaster-us.mp3', 1, '2026-06-01 14:48:14'),
(4590, 'plastic', 1, '/ˈplæstɪk/', 'A synthetic, solid, hydrocarbon-based polymer, whether thermoplastic or thermosetting.', '塑膠、塑膠製品', 'https://api.dictionaryapi.dev/media/pronunciations/en/plastic-us.mp3', 1, '2026-06-01 14:48:14'),
(4591, 'plastic', 3, '/ˈplæstɪk/', 'Capable of being moulded; malleable, flexible, pliant.', '塑膠製的、可塑的、虛假的', 'https://api.dictionaryapi.dev/media/pronunciations/en/plastic-us.mp3', 1, '2026-06-01 14:48:14'),
(4592, 'plate', 1, '/pleɪt/', 'A slightly curved but almost flat dish from which food is served or eaten.', '盤子、金屬板、車牌', 'https://api.dictionaryapi.dev/media/pronunciations/en/plate-au.mp3', 1, '2026-06-01 14:48:14'),
(4593, 'platform', 1, '/ˈplætfɔːm/', 'A raised stage from which speeches are made and on which musical and other performances are made.', '平台、講台、月台、政綱', 'https://api.dictionaryapi.dev/media/pronunciations/en/platform-us.mp3', 1, '2026-06-01 14:48:14'),
(4594, 'Plato', 1, '', 'N/A', '柏拉圖', NULL, 1, '2026-06-01 14:48:14'),
