(4616, 'pneumonia', 1, '/nuˈmoʊniə/', 'An acute or chronic inflammation of the lungs caused by viruses, bacteria or other microorganisms, or sometimes by physical or chemical irritants.', '肺炎', 'https://dictionaryapi.dev/pneumonia', 1, '2026-06-01 14:48:14'),
(4617, 'pocket', 1, '', 'A bag stitched to an item of clothing, used for carrying small items.', '口袋、錢袋、小袋', 'https://api.dictionaryapi.dev/media/pronunciations/en/pocket-au.mp3', 1, '2026-06-01 14:48:14'),
(4618, 'poem', 1, '/ˈpoʊ̯ɪm/', 'A literary piece written in verse.', '詩、一首詩', 'https://api.dictionaryapi.dev/media/pronunciations/en/poem-uk.mp3', 1, '2026-06-01 14:48:14'),
