(5040, 'relationship', 1, '/ɹɪˈleɪʃ(ə)nʃɪp/', 'Connection or association; the condition of being related.', '關係、關聯、人際關係', 'https://api.dictionaryapi.dev/media/pronunciations/en/relationship-us.mp3', 1, '2026-06-01 14:48:14'),
(5041, 'relative', 1, '[ˈɹɛl.ə.tʰɪv]', 'Someone in the same family; someone connected by blood, marriage, or adoption.', '親戚、親屬', 'https://dictionaryapi.dev/relative', 1, '2026-06-01 14:48:14'),
(5042, 'relative', 3, '[ˈɹɛl.ə.tʰɪv]', 'Connected to or depending on something else; comparative.', '相對的、比較而言的、有關的', 'https://dictionaryapi.dev/relative', 1, '2026-06-01 14:48:14'),
(5043, 'relatively', 4, '[ˈɹɛl.ə.tʰɪv.li]', 'Proportionally, in relation to some larger scale thing.', '相對地、比較上地', 'https://dictionaryapi.dev/relatively', 1, '2026-06-01 14:48:14'),
(5044, 'relax', 2, '/ɹɪˈlæks/', 'To calm down.', '放鬆、休息、緩和', 'https://api.dictionaryapi.dev/media/pronunciations/en/relax-us.mp3', 1, '2026-06-01 14:48:14'),
(5045, 'release', 1, '/ɹɪˈliːs/', 'The event of setting (someone or something) free (e.g. hostages, slaves, prisoners, caged animals, hooked or stuck mechanisms).', '釋放、發行、發表、豁免', 'https://api.dictionaryapi.dev/media/pronunciations/en/release-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5046, 'release', 2, '/ɹɪˈliːs/', 'To let go (of); to cease to hold or contain.', '釋放、免除、發行、發布', 'https://api.dictionaryapi.dev/media/pronunciations/en/release-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5047, 'reliable', 3, '/ɹɪˈlaɪəbəl/', 'Suitable or fit to be relied on; worthy of dependence, reliance or trust; dependable, trustworthy', '可靠的、可信賴的', 'https://api.dictionaryapi.dev/media/pronunciations/en/reliable-us.mp3', 1, '2026-06-01 14:48:14'),
(5048, 'relief', 1, '/ɹɪˈliːf/', 'The removal of stress or discomfort.', '（痛苦的）減輕、寬心、救濟', 'https://api.dictionaryapi.dev/media/pronunciations/en/relief-us.mp3', 1, '2026-06-01 14:48:14'),
(5049, 'relieve', 2, '/ɹɪˈliːv/', 'To ease (a person, person\'s thoughts etc.) from mental distress; to stop (someone) feeling anxious or worried, to alleviate the distress of.', '減輕、緩解、解除、接替', 'https://api.dictionaryapi.dev/media/pronunciations/en/relieve-us.mp3', 1, '2026-06-01 14:48:14'),
(5050, 'religion', 1, '/ɹɪˈlɪdʒən/', 'Belief in a spiritual or metaphysical reality (often including at least one deity), accompanied by practices or rituals pertaining to the belief.', '宗教、信仰', 'https://api.dictionaryapi.dev/media/pronunciations/en/religion-uk.mp3', 1, '2026-06-01 14:48:14'),
(5051, 'religious', 3, '/ɹɪ.ˈlɪ.d͡ʒəs/', 'Concerning religion.', '宗教的、虔誠的', 'https://api.dictionaryapi.dev/media/pronunciations/en/religious-us.mp3', 1, '2026-06-01 14:48:14'),
(5052, 'relinquish', 2, '[ɹɪˈlɪŋkwɪʃ]', 'To give up, abandon or retire from something. To trade away.', '放棄、讓與、鬆開', 'https://dictionaryapi.dev/relinquish', 1, '2026-06-01 14:48:14'),
(5053, 'relish', 1, '/ˈɹɛ.lɪʃ/', 'A pleasant taste', '滋味、風味、愛好、調味品', 'https://api.dictionaryapi.dev/media/pronunciations/en/relish-us.mp3', 1, '2026-06-01 14:48:14'),
(5054, 'relish', 2, '/ˈɹɛ.lɪʃ/', 'To taste or eat with pleasure, to like the flavor of', '喜愛、享受、品嚐', 'https://api.dictionaryapi.dev/media/pronunciations/en/relish-us.mp3', 1, '2026-06-01 14:48:14'),
(5055, 'reluctant', 3, '/ɹɪˈlʌktənt/', 'Opposing; offering resistance (to).', '不情願的、勉強的', 'https://api.dictionaryapi.dev/media/pronunciations/en/reluctant-us.mp3', 1, '2026-06-01 14:48:14'),
(5056, 'reluctantly', 4, '/ɹɪˈlʌktəntli/', 'In a reluctant or hesitant manner.', '不情願地、勉強地', 'https://dictionaryapi.dev/reluctantly', 1, '2026-06-01 14:48:14'),
(5057, 'rely', 2, '/ɹɪˈlaɪ/', '(with on or upon, formerly also with in) to trust; to have confidence in; to depend.', '依賴、依靠、信賴', 'https://api.dictionaryapi.dev/media/pronunciations/en/rely-us.mp3', 1, '2026-06-01 14:48:14'),
(5058, 'remain', 2, '/ɹɪˈmeɪn/', 'To stay behind while others withdraw; to be left after others have been removed or destroyed; to be left after a number or quantity has been subtracted or cut off; to be left as not included or comprised.', '保持、留下、剩餘、依然是', 'https://api.dictionaryapi.dev/media/pronunciations/en/remain-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(5059, 'remains', 1, '/ɹɪˈmeɪnz/', '(chiefly in the plural) That which is left; relic; remainder.', '剩餘物、遺跡、遺體', 'https://api.dictionaryapi.dev/media/pronunciations/en/remains-us.mp3', 1, '2026-06-01 14:48:14'),
(5060, 'remark', 1, '/ɹɪˈmɑːk/', 'An act of pointing out or noticing; notice or observation.', '談論、評論、注意', 'https://api.dictionaryapi.dev/media/pronunciations/en/remark-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5061, 'remark', 2, '/ɹɪˈmɑːk/', 'To make a remark or remarks; to comment.', '談論、評論、注意到', 'https://api.dictionaryapi.dev/media/pronunciations/en/remark-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5062, 'remarkable', 3, '/ɹɪˈmɑːkəbl̩/', 'Worthy of being remarked or noted; notable', '顯著的、非凡的、值得注意的', 'https://api.dictionaryapi.dev/media/pronunciations/en/remarkable-us.mp3', 1, '2026-06-01 14:48:14'),
(5063, 'remedy', 1, '/ˈɹɛmədi/', 'Something that corrects or counteracts.', '治療法、補救辦法、賠償', 'https://api.dictionaryapi.dev/media/pronunciations/en/remedy-us.mp3', 1, '2026-06-01 14:48:14'),
(5064, 'remember', 2, '/ɹɪˈmɛmbə/', 'To recall from one\'s memory; to have an image in one\'s memory.', '記得、想起、記住', 'https://api.dictionaryapi.dev/media/pronunciations/en/remember-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(5065, 'remind', 2, '/ɹəˈmaɪnd/', 'To cause one to experience a memory (of someone or something); to bring to the notice or consideration (of a person).', '提醒、使想起', '', 1, '2026-06-01 14:48:14'),
(5066, 'reminiscence', 1, '', 'An act of remembering long-past experiences, often fondly.', '回憶、緬懷、往事', 'https://dictionaryapi.dev/reminiscence', 1, '2026-06-01 14:48:14'),
(5067, 'reminiscent', 3, '/ˌɹɛməˈnɪsnt/', 'Of, or relating to reminiscence', '使人回想起的、懷舊的', 'https://api.dictionaryapi.dev/media/pronunciations/en/reminiscent-uk.mp3', 1, '2026-06-01 14:48:14'),
(5068, 'remote', 3, '[ɹəˈməʊt]', 'At a distance; disconnected.', '遙遠的、偏僻的、微小的、疏遠的', 'https://api.dictionaryapi.dev/media/pronunciations/en/remote-us.mp3', 1, '2026-06-01 14:48:14'),
(5069, 'remove', 2, '/ɹɪˈmuːv/', 'To move something from one place to another, especially to take away.', '移開、移除、去掉、免職', 'https://api.dictionaryapi.dev/media/pronunciations/en/remove-au.mp3', 1, '2026-06-01 14:48:14'),
(5070, 'renaissance', 1, '/ˈɹɛnəˌsɑns/', 'A rebirth or revival.', '文藝復興、復興', 'https://api.dictionaryapi.dev/media/pronunciations/en/renaissance-us.mp3', 1, '2026-06-01 14:48:14'),
(5071, 'renew', 2, '/ɹɪˈnjuː/', 'To make (something) new again; to restore to freshness or original condition.', '更新、續期、重新開始、修復', 'https://api.dictionaryapi.dev/media/pronunciations/en/renew-us.mp3', 1, '2026-06-01 14:48:14'),
(5072, 'renowned', 3, '/ɹɪˈnaʊnd/', 'Famous, celebrated, or well-known.', '著名的、有聲望的', 'https://dictionaryapi.dev/renowned', 1, '2026-06-01 14:48:14'),
(5073, 'rent', 1, '/ɹɛnt/', 'A payment made by a tenant at intervals in order to occupy a property.', '租金、租金收入', 'https://api.dictionaryapi.dev/media/pronunciations/en/rent-uk.mp3', 1, '2026-06-01 14:48:14'),
(5074, 'rent', 2, '/ɹɛnt/', 'To occupy premises in exchange for rent.', '租用、出租', 'https://api.dictionaryapi.dev/media/pronunciations/en/rent-uk.mp3', 1, '2026-06-01 14:48:14'),
(5075, 'repair', 1, '/ɹɪˈpɛə/', 'The act of repairing something.', '修理、修補、賠償', 'https://api.dictionaryapi.dev/media/pronunciations/en/repair-us.mp3', 1, '2026-06-01 14:48:14'),
(5076, 'repair', 2, '/ɹɪˈpɛə/', 'To restore to good working order, fix, or improve damaged condition; to mend; to remedy.', '修理、修補、糾正', 'https://api.dictionaryapi.dev/media/pronunciations/en/repair-us.mp3', 1, '2026-06-01 14:48:14'),
(5077, 'repay', 2, '/ɹiˈpeɪ/', 'To pay back.', '償還、報答、回報', 'https://api.dictionaryapi.dev/media/pronunciations/en/repay-us.mp3', 1, '2026-06-01 14:48:14'),
(5078, 'repeat', 2, '', 'To do or say again (and again).', '重複、重做、複述', 'https://api.dictionaryapi.dev/media/pronunciations/en/repeat-uk.mp3', 1, '2026-06-01 14:48:14'),
(5079, 'repel', 2, '/ɹɪˈpɛl/', 'To turn (someone) away from a privilege, right, job, etc.', '擊退、排斥、使厭惡', 'https://api.dictionaryapi.dev/media/pronunciations/en/repel-au.mp3', 1, '2026-06-01 14:48:14'),
(5080, 'repent', 2, '/ɹɪˈpɛnt/', 'To feel pain, sorrow, or regret for what one has done or omitted to do; the cause for repenting may be indicated with \"of\".', '後悔、懊悔、懺悔', 'https://api.dictionaryapi.dev/media/pronunciations/en/repent-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5081, 'repetition', 1, '/ɹɛpəˈtɪʃən/', 'The act or an instance of repeating or being repeated.', '重複、反覆', 'https://api.dictionaryapi.dev/media/pronunciations/en/repetition-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5082, 'replaceable', 3, '', 'Capable of being replaced.', '可替換的、可代替的', 'https://dictionaryapi.dev/replaceable', 1, '2026-06-01 14:48:14'),
(5083, 'replacement', 1, '/ɹɪˈpleɪsmənt/', 'A person or thing that takes the place of another; a substitute.', '更換、代替、替代的人或物', 'https://api.dictionaryapi.dev/media/pronunciations/en/replacement-us.mp3', 1, '2026-06-01 14:48:14'),
(5084, 'replacement', 2, '/ɹɪˈpleɪsmənt/', 'A person or thing that takes the place of another; a substitute.', '替換、代替（動詞誤植或特殊用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/replacement-us.mp3', 1, '2026-06-01 14:48:14'),
(5085, 'reply', 1, '/ɹɪˈplaɪ/', 'A written or spoken response; part of a conversation.', '回答、答覆', 'https://api.dictionaryapi.dev/media/pronunciations/en/reply-us.mp3', 1, '2026-06-01 14:48:14'),
(5086, 'reply', 2, '/ɹɪˈplaɪ/', 'To give a written or spoken response, especially to a question, request, accusation or criticism; to answer.', '回答、答覆', 'https://api.dictionaryapi.dev/media/pronunciations/en/reply-us.mp3', 1, '2026-06-01 14:48:14'),
(5087, 'report', 1, '/ɹəˈpoːt/', 'A piece of information describing, or an account of certain events given or presented to someone, with the most common adpositions being by (referring to creator of the report) and on (referring to the subject).', '報告、報導、成績單', 'https://api.dictionaryapi.dev/media/pronunciations/en/report-us.mp3', 1, '2026-06-01 14:48:14'),
(5088, 'report', 2, '/ɹəˈpoːt/', 'To relate details of (an event or incident); to recount, describe (something).', '報告、報導、舉報', 'https://api.dictionaryapi.dev/media/pronunciations/en/report-us.mp3', 1, '2026-06-01 14:48:14'),
(5089, 'reporter', 1, '/ɹɪˈpɔːtə/', 'Someone or something that reports.', '記者、通訊員', 'https://api.dictionaryapi.dev/media/pronunciations/en/reporter-us.mp3', 1, '2026-06-01 14:48:14'),
(5090, 'represent', 2, '/ɹɛp.ɹɪ.ˈzɛnt/', 'To present again or anew; to present by means of something standing in the place of; to exhibit the counterpart or image of; to typify.', '代表、代理、象徵、表示', 'https://api.dictionaryapi.dev/media/pronunciations/en/represent-us.mp3', 1, '2026-06-01 14:48:14'),
(5091, 'representation', 1, '/ˌɹɛp.ɹə.zɛn.ˈteɪ.ʃən/', 'That which represents something else.', '代表、表現、描述、陳述', 'https://api.dictionaryapi.dev/media/pronunciations/en/representation-us.mp3', 1, '2026-06-01 14:48:14'),
(5092, 'representative', 1, '/ˌɹɛpɹɪˈzɛnt(ət)ɪv/', 'A delegate.', '代表、代理人', 'https://api.dictionaryapi.dev/media/pronunciations/en/representative-us.mp3', 1, '2026-06-01 14:48:14'),
(5093, 'representative', 3, '/ˌɹɛpɹɪˈzɛnt(ət)ɪv/', 'Typical; having the same properties or interest as a larger group.', '典型的、有代表性的', 'https://api.dictionaryapi.dev/media/pronunciations/en/representative-us.mp3', 1, '2026-06-01 14:48:14'),
(5094, 'repress', 2, '', 'To press again.', '壓制、壓抑、鎮壓', 'https://dictionaryapi.dev/repress', 1, '2026-06-01 14:48:14'),
(5095, 'republic', 1, '[ɹɪˈpʌblɪk]', 'A state where sovereignty rests with the people or their representatives, rather than with a monarch or emperor; a country with no monarchy.', '共和國、共和政體', 'https://api.dictionaryapi.dev/media/pronunciations/en/republic-us.mp3', 1, '2026-06-01 14:48:14'),
(5096, 'republican', 1, '/ɹɪˈpʌblɪkən/', 'Someone who favors a republic as a form of government.', '共和主義者、共和黨員', 'https://api.dictionaryapi.dev/media/pronunciations/en/republican-uk.mp3', 1, '2026-06-01 14:48:14'),
(5097, 'republican', 3, '/ɹɪˈpʌblɪkən/', 'Advocating or supporting a republic as a form of government, advocating or supporting republicanism.', '共和政體的、共和黨的', 'https://api.dictionaryapi.dev/media/pronunciations/en/republican-uk.mp3', 1, '2026-06-01 14:48:14'),
(5098, 'reputation', 1, '/ˌɹɛpjʊˈteɪʃən/', 'What somebody is known for.', '名譽、名聲、聲望', 'https://api.dictionaryapi.dev/media/pronunciations/en/reputation-us.mp3', 1, '2026-06-01 14:48:14'),
(5099, 'request', 1, '/ɹɪˈkwɛst/', 'Act of requesting (with the adposition at in the presence of possessives, and on in their absence).', '要求、請求、需要', 'https://api.dictionaryapi.dev/media/pronunciations/en/request-us.mp3', 1, '2026-06-01 14:48:14'),
(5100, 'request', 2, '/ɹɪˈkwɛst/', 'To ask for (something).', '要求、請求', 'https://api.dictionaryapi.dev/media/pronunciations/en/request-us.mp3', 1, '2026-06-01 14:48:14'),
(5101, 'require', 1, '/ɹɪˈkwaɪə/', 'To ask (someone) for something; to request.', '需要、要求（名詞誤植或特殊用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/require-us.mp3', 1, '2026-06-01 14:48:14'),
(5102, 'require', 2, '/ɹɪˈkwaɪə/', 'To ask (someone) for something; to request.', '需要、要求、命令', 'https://api.dictionaryapi.dev/media/pronunciations/en/require-us.mp3', 1, '2026-06-01 14:48:14'),
(5103, 'rescue', 1, '/ˈɹɛs.kjuː/', 'An act or episode of rescuing, saving.', '營救、解救、救援', 'https://api.dictionaryapi.dev/media/pronunciations/en/rescue-us.mp3', 1, '2026-06-01 14:48:14'),
(5104, 'rescue', 2, '/ˈɹɛs.kjuː/', 'To save from any violence, danger or evil.', '營救、解救、救援', 'https://api.dictionaryapi.dev/media/pronunciations/en/rescue-us.mp3', 1, '2026-06-01 14:48:14'),
(5105, 'research', 1, '/ɹɪˈsɜːtʃ/', 'Diligent inquiry or examination to seek or revise facts, principles, theories, applications, etc.; laborious or continued search after truth.', '研究、調查', 'https://api.dictionaryapi.dev/media/pronunciations/en/research-us.mp3', 1, '2026-06-01 14:48:14'),
(5106, 'research', 2, '/ɹɪˈsɜːtʃ/', 'To search or examine with continued care; to seek diligently.', '研究、調查', 'https://api.dictionaryapi.dev/media/pronunciations/en/research-us.mp3', 1, '2026-06-01 14:48:14'),
(5107, 'researcher', 1, '', 'One who researches.', '研究人員、調查者', 'https://dictionaryapi.dev/researcher', 1, '2026-06-01 14:48:14'),
(5108, 'resemblance', 1, '/ɹəˈzɛmbləns/', 'The quality or state of resembling', '相似、像', 'https://dictionaryapi.dev/resemblance', 1, '2026-06-01 14:48:14'),
(5109, 'resemble', 2, '/ɹɪˈzɛmb(ə)l/', 'To be like or similar to (something); to represent as similar.', '像、與...相似', 'https://api.dictionaryapi.dev/media/pronunciations/en/resemble-uk.mp3', 1, '2026-06-01 14:48:14'),
(5110, 'resent', 2, '/ɹiˈzɛnt/', 'To feel resentment over; to consider as an affront.', '憤恨、怨恨', 'https://api.dictionaryapi.dev/media/pronunciations/en/resent-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5111, 'reservation', 1, '/ˌɹɛzəˈveɪʃən/', 'The act of reserving, withholding or keeping back.', '預訂、預約、保留、保護區', 'https://dictionaryapi.dev/reservation', 1, '2026-06-01 14:48:14'),
(5112, 'reserve', 2, '/ɹɪˈzɜːv/', 'To keep back; to retain.', '保留、儲備、預訂', 'https://api.dictionaryapi.dev/media/pronunciations/en/reserve-us.mp3', 1, '2026-06-01 14:48:14'),
(5113, 'reservoir', 1, '/ˈɹɛz.ə.vwɑː(ɹ)/', 'A place where anything is kept in store', '水庫、蓄水池、儲藏', 'https://api.dictionaryapi.dev/media/pronunciations/en/reservoir-us.mp3', 1, '2026-06-01 14:48:14'),
(5114, 'reside', 2, '/ɹɪˈzaɪd/', 'To dwell permanently or for a considerable time; to have a settled abode for a time; to remain for a long time.', '居住、定居、存在於', 'https://api.dictionaryapi.dev/media/pronunciations/en/reside-us.mp3', 1, '2026-06-01 14:48:14'),
(5115, 'resign', 2, '/ɹɪˈzaɪn/', 'To give up; to relinquish ownership of.', '辭職、放棄、聽任', 'https://api.dictionaryapi.dev/media/pronunciations/en/resign-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(5116, 'resignation', 1, '/ɹɛzɪɡˈneɪʃən/', 'The act of resigning.', '辭職、辭呈、聽天由命', 'https://api.dictionaryapi.dev/media/pronunciations/en/resignation-us.mp3', 1, '2026-06-01 14:48:14'),
(5117, 'resist', 2, '/ɹəˈzɪst/', 'To attempt to counter the actions or effects of.', '抵抗、反抗、忍住、抗拒', 'https://api.dictionaryapi.dev/media/pronunciations/en/resist-us.mp3', 1, '2026-06-01 14:48:14'),
(5118, 'resistance', 1, '/ɹɪˈzɪstəns/', 'The act of resisting, or the capacity to resist.', '抵抗、反抗、抵抗力、阻力', 'https://api.dictionaryapi.dev/media/pronunciations/en/resistance-us.mp3', 1, '2026-06-01 14:48:14'),
(5119, 'resolution', 1, '/ˌɹɛzəˈluːʃ(ə)n/', 'A strong will, determination.', '決心、決定、決議、解析度', 'https://api.dictionaryapi.dev/media/pronunciations/en/resolution-us.mp3', 1, '2026-06-01 14:48:14'),
(5120, 'resolve', 2, '/ɹiːˈzɒlv/', 'To find a solution to (a problem).', '解決、決心、決議、分解', 'https://api.dictionaryapi.dev/media/pronunciations/en/resolve-1-us.mp3', 1, '2026-06-01 14:48:14'),
