(5290, 'satisfaction', 1, '/sætɪsˈfækʃən/', 'A fulfilment of a need or desire.', '滿意、滿足、令人滿意的事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/satisfaction-us.mp3', 1, '2026-06-01 14:48:14'),
(5291, 'satisfactory', 3, '/sætɪsˈfækt(ə)ɹi/', 'Done to satisfaction; adequate or sufficient.', '令人滿意的、符合要求的', 'https://api.dictionaryapi.dev/media/pronunciations/en/satisfactory-us.mp3', 1, '2026-06-01 14:48:14'),
(5292, 'satisfy', 2, '/ˈsætɪsfaɪ/', 'To do enough for; to meet the needs of; to fulfill the wishes or requirements of.', '使滿意、滿足、使信服', 'https://api.dictionaryapi.dev/media/pronunciations/en/satisfy-us.mp3', 1, '2026-06-01 14:48:14'),
(5293, 'Saturday', 1, '', 'N/A', '星期六', NULL, 1, '2026-06-01 14:48:14'),
(5294, 'sauce', 1, '', 'A liquid (often thickened) condiment or accompaniment to food.', '醬汁、調味汁', 'https://api.dictionaryapi.dev/media/pronunciations/en/sauce-au.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(5295, 'sausage', 1, '/ˈsɑsɪd͡ʒ/', 'A food made of ground meat (or meat substitute) and seasoning, packed in a section of the animal\'s intestine, or in a similarly cylindrical shaped synthetic casing; a length of this food.', '香腸', 'https://api.dictionaryapi.dev/media/pronunciations/en/sausage-us.mp3', 1, '2026-06-01 14:48:14'),
(5296, 'savage', 3, '/ˈsævɪdʒ/', 'Wild; not cultivated.', '野蠻的、殘酷的、未開化的', 'https://api.dictionaryapi.dev/media/pronunciations/en/savage-us.mp3', 1, '2026-06-01 14:48:14'),
(5297, 'save', 2, '/seɪv/', 'To prevent harm or difficulty.', '拯救、儲蓄、節省、保留', 'https://api.dictionaryapi.dev/media/pronunciations/en/save-us.mp3', 1, '2026-06-01 14:48:14'),
(5298, 'saving', 1, '/ˈseɪvɪŋ/', 'A reduction in cost or expenditure.', '儲蓄、存款、節約', 'https://api.dictionaryapi.dev/media/pronunciations/en/saving-us.mp3', 1, '2026-06-01 14:48:14'),
(5299, 'saw', 1, '/sɔː/', 'A tool with a toothed blade used for cutting hard substances, in particular wood or metal', '鋸子', 'https://api.dictionaryapi.dev/media/pronunciations/en/saw-us.mp3', 1, '2026-06-01 14:48:14'),
(5300, 'say', 2, '/seɪ/', 'To pronounce.', '說、講、說明、假設', 'https://api.dictionaryapi.dev/media/pronunciations/en/say-us.mp3', 1, '2026-06-01 14:48:14'),
(5301, 'scale', 1, '/skeɪl/', 'A ladder; a series of steps; a means of ascending.', '刻度、天平、規模、魚鱗', 'https://api.dictionaryapi.dev/media/pronunciations/en/scale-au.mp3', 1, '2026-06-01 14:48:14'),
(5302, 'scan', 2, '/skæn/', 'To examine sequentially, carefully, or critically; to scrutinize; to behold closely.', '細看、掃描、瀏覽、審視', 'https://api.dictionaryapi.dev/media/pronunciations/en/scan-us.mp3', 1, '2026-06-01 14:48:14'),
(5303, 'scandal', 1, '/ˈskændəl/', 'An incident or event that disgraces or damages the reputation of the persons or organization involved.', '醜聞、醜事、流言蜚語', 'https://dictionaryapi.dev/scandal', 1, '2026-06-01 14:48:14'),
(5304, 'scare', 2, '/skɛə/', 'A minor fright.', '驚嚇、使害怕', 'https://api.dictionaryapi.dev/media/pronunciations/en/scare-us.mp3', 1, '2026-06-01 14:48:14'),
(5305, 'scared', 3, '/skɛəd/', 'Feeling fear; afraid, frightened.', '害怕的、恐懼的', 'https://api.dictionaryapi.dev/media/pronunciations/en/scared-uk.mp3', 1, '2026-06-01 14:48:14'),
(5306, 'scarf', 1, '', 'A long, often knitted, garment worn around the neck.', '圍巾、領巾', 'https://api.dictionaryapi.dev/media/pronunciations/en/scarf-au.mp3', 1, '2026-06-01 14:48:14'),
(5307, 'scarlet', 3, '/ˈskɐːlət/', 'Of a bright red colour.', '猩紅色的、鮮紅色的', 'https://api.dictionaryapi.dev/media/pronunciations/en/scarlet-uk.mp3', 1, '2026-06-01 14:48:14'),
(5308, 'scary', 3, '/ˈskɛəɹi/', 'Causing or able to cause fright.', '可怕的、嚇人的', 'https://api.dictionaryapi.dev/media/pronunciations/en/scary-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5309, 'scatter', 2, '/ˈskætə/', 'To (cause to) separate and go in different directions; to disperse.', '使分散、驅散、撒、散播', 'https://api.dictionaryapi.dev/media/pronunciations/en/scatter-us.mp3', 1, '2026-06-01 14:48:14'),
(5310, 'scene', 1, '/siːn/', 'The location of an event that attracts attention.', '場景、舞台、現場、景色', 'https://api.dictionaryapi.dev/media/pronunciations/en/scene-us.mp3', 1, '2026-06-01 14:48:14'),
(5311, 'scenery', 1, '/ˈsiːnəɹi/', 'View, natural features, landscape.', '風景、景色、舞台佈景', 'https://api.dictionaryapi.dev/media/pronunciations/en/scenery-us.mp3', 1, '2026-06-01 14:48:14'),
(5312, 'schedule', 1, '', 'A slip of paper; a short note.', '時間表、日程表、計畫表', 'https://api.dictionaryapi.dev/media/pronunciations/en/schedule-au.mp3', 1, '2026-06-01 14:48:14'),
(5313, 'schedule', 2, '', 'To create a time-schedule.', '安排、將...列入計畫表', 'https://api.dictionaryapi.dev/media/pronunciations/en/schedule-au.mp3', 1, '2026-06-01 14:48:14'),
(5314, 'scholar', 1, '/ˈskɒlə/', 'A student; one who studies at school or college, typically having a scholarship.', '學者、獎學金獲得者', 'https://api.dictionaryapi.dev/media/pronunciations/en/scholar-uk.mp3', 1, '2026-06-01 14:48:14'),
(5315, 'scholastic', 3, '/skəˈlæstɪk/', 'Of or relating to school; academic', '學校的、學業的、學術的', 'https://dictionaryapi.dev/scholastic', 1, '2026-06-01 14:48:14'),
(5316, 'school', 1, '/skuːl/', '(collective) A group of fish or a group of marine mammals such as porpoises, dolphins, or whales.', '學校、學院、學派', 'https://api.dictionaryapi.dev/media/pronunciations/en/school-uk.mp3', 1, '2026-06-01 14:48:14'),
(5317, 'science', 1, '/ˈsaɪəns/', 'A particular discipline or branch of learning, especially one dealing with measurable or systematic principles rather than intuition or natural ability.', '科學、科學知識、學科', 'https://api.dictionaryapi.dev/media/pronunciations/en/science-1-ca.mp3', 1, '2026-06-01 14:48:14'),
(5318, 'scientific', 3, '/ˌsaɪənˈtɪfɪk/', 'Of, or having to do with science.', '科學的、符合科學規律的', 'https://api.dictionaryapi.dev/media/pronunciations/en/scientific-ca.mp3', 1, '2026-06-01 14:48:14'),
(5319, 'scientist', 1, '/ˈsaɪ.ən.tɪst/', 'One whose activities make use of the scientific method to answer questions regarding the measurable universe. A scientist may be involved in original research, or make use of the results of the research of others.', '科學家', 'https://dictionaryapi.dev/scientist', 1, '2026-06-01 14:48:14'),
(5320, 'scissor', 1, '/ˈsɪzə/', 'One blade on a pair of scissors.', '剪刀', 'https://dictionaryapi.dev/scissor', 1, '2026-06-01 14:48:14'),
(5321, 'scold', 2, '/skəʊld/', 'To burn with hot liquid.', '責罵、訓斥', 'https://api.dictionaryapi.dev/media/pronunciations/en/scold-us.mp3', 1, '2026-06-01 14:48:14'),
(5322, 'score', 1, '/skɔː/', 'The total number of goals, points, runs, etc. earned by a participant in a game.', '得分、分數、二十', 'https://api.dictionaryapi.dev/media/pronunciations/en/score-us.mp3', 1, '2026-06-01 14:48:14'),
(5323, 'score', 2, '/skɔː/', 'To cut a notch or a groove in a surface.', '得分、記分、評分', 'https://api.dictionaryapi.dev/media/pronunciations/en/score-us.mp3', 1, '2026-06-01 14:48:14'),
(5324, 'scorn', 1, '/skɔːn/', 'Contempt or disdain.', '輕蔑、鄙視、嘲弄', 'https://api.dictionaryapi.dev/media/pronunciations/en/scorn-us.mp3', 1, '2026-06-01 14:48:14'),
(5325, 'scorn', 2, '/skɔːn/', 'To feel or display contempt or disdain for something or somebody; to despise.', '輕蔑、鄙視、拒絕', 'https://api.dictionaryapi.dev/media/pronunciations/en/scorn-us.mp3', 1, '2026-06-01 14:48:14'),
(5326, 'scout', 1, '', 'A person sent out to gain and bring in tidings; especially, one employed in war to gain information about the enemy and ground.', '偵察員、童子軍', 'https://api.dictionaryapi.dev/media/pronunciations/en/scout-au.mp3', 1, '2026-06-01 14:48:14'),
(5327, 'scrap', 1, '/skɹæp/', 'A (small) piece; a fragment; a detached, incomplete portion.', '碎片、小塊、廢料、殘屑', 'https://api.dictionaryapi.dev/media/pronunciations/en/scrap-us.mp3', 1, '2026-06-01 14:48:14'),
(5328, 'scrape', 2, '/skɹeɪp/', 'To draw (an object, especially a sharp or angular one), along (something) while exerting pressure.', '擦傷、刮除、勉強透過', 'https://api.dictionaryapi.dev/media/pronunciations/en/scrape-us.mp3', 1, '2026-06-01 14:48:14'),
(5329, 'scratch', 2, '/skɹætʃ/', 'To rub a surface with a sharp object, especially by a living creature to remove itching with nails, claws, etc.', '抓、搔、抓傷、擦出（聲音）', 'https://api.dictionaryapi.dev/media/pronunciations/en/scratch-us.mp3', 1, '2026-06-01 14:48:14'),
(5330, 'scream', 1, '/skɹiːm/', 'A loud, emphatic, exclamation of extreme emotion, especially horror, fear, excitement, or anger; it may comprise a word or a sustained, high-pitched vowel sound.', '尖叫聲、大笑聲', 'https://api.dictionaryapi.dev/media/pronunciations/en/scream-us.mp3', 1, '2026-06-01 14:48:14'),
(5331, 'scream', 2, '/skɹiːm/', 'To cry out with a shrill voice; to utter a sudden, sharp outcry, or shrill, loud cry, as in fright or extreme pain; to shriek; to screech.', '尖叫、大叫', 'https://api.dictionaryapi.dev/media/pronunciations/en/scream-us.mp3', 1, '2026-06-01 14:48:14'),
(5332, 'screen', 1, '/skɹiːn/', 'A physical divider intended to block an area from view, or provide shelter from something dangerous.', '螢幕、銀幕、屏風、紗窗', 'https://api.dictionaryapi.dev/media/pronunciations/en/screen-au.mp3', 1, '2026-06-01 14:48:14'),
(5333, 'script', 1, '/skɹɪpt/', 'A writing; a written document.', '劇本、腳本、手稿', 'https://api.dictionaryapi.dev/media/pronunciations/en/script-us.mp3', 1, '2026-06-01 14:48:14'),
(5334, 'scrutiny', 1, '/ˈskɹuː.tɪ.ni/', 'Intense study of someone or something.', '詳細審查、細看、監視', 'https://api.dictionaryapi.dev/media/pronunciations/en/scrutiny-uk.mp3', 1, '2026-06-01 14:48:14'),
(5335, 'sculpture', 1, '/ˈskʌlptj(ʊ)ə/', 'A three dimensional work of art created by shaping malleable objects and letting them harden or by chipping away pieces from a rock (sculpting).', '雕刻品、雕塑', 'https://api.dictionaryapi.dev/media/pronunciations/en/sculpture-us.mp3', 1, '2026-06-01 14:48:14'),
(5336, 'sea', 1, '/siː/', 'A large body of salt water.', '海、海洋', 'https://dictionaryapi.dev/sea', 1, '2026-06-01 14:48:14'),
(5337, 'seal', 1, '/siːl/', 'A pinniped (Pinnipedia), particularly an earless seal (true seal) or eared seal.', '海豹、印章、封條', 'https://api.dictionaryapi.dev/media/pronunciations/en/seal-us.mp3', 1, '2026-06-01 14:48:14'),
(5338, 'seal', 2, '/siːl/', 'To hunt seals.', '密封、蓋章、確認', 'https://api.dictionaryapi.dev/media/pronunciations/en/seal-us.mp3', 1, '2026-06-01 14:48:14'),
(5339, 'seam', 1, '/siːm/', 'A folded-back and stitched piece of fabric; especially, the stitching that joins two or more pieces of fabric.', '接縫、縫合處、煤層', 'https://api.dictionaryapi.dev/media/pronunciations/en/seam-au.mp3', 1, '2026-06-01 14:48:14'),
(5340, 'search', 1, '/sɜːt͡ʃ/', 'An attempt to find something.', '搜尋、尋找、調查', 'https://api.dictionaryapi.dev/media/pronunciations/en/search-us.mp3', 1, '2026-06-01 14:48:14'),
(5341, 'search', 2, '/sɜːt͡ʃ/', 'To look in (a place) for something.', '搜尋、尋找、搜查', 'https://api.dictionaryapi.dev/media/pronunciations/en/search-us.mp3', 1, '2026-06-01 14:48:14'),
(5342, 'season', 1, '', 'Each of the four divisions of a year: spring, summer, autumn (fall) and winter', '季節、時期、旺季', 'https://api.dictionaryapi.dev/media/pronunciations/en/season-au.mp3', 1, '2026-06-01 14:48:14'),
(5343, 'seat', 1, '/siːt/', 'Something to be sat upon.', '座位、席位、所在地', 'https://api.dictionaryapi.dev/media/pronunciations/en/seat-us.mp3', 1, '2026-06-01 14:48:14'),
(5344, 'seat', 2, '/siːt/', 'To put an object into a place where it will rest; to fix; to set firm.', '使就座、容納', 'https://api.dictionaryapi.dev/media/pronunciations/en/seat-us.mp3', 1, '2026-06-01 14:48:14'),
(5345, 'Second', 1, '/ˈsɛkɪnd/', 'Something that is number two in a series.', '秒、片刻、第二名、助手', 'https://api.dictionaryapi.dev/media/pronunciations/en/second-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5346, 'Second', 2, '/ˈsɛkɪnd/', 'To agree as a second person to (a proposal), usually to reach a necessary quorum of two. (See under #Etymology 3 for translations.)', '贊成、支持、附議', 'https://api.dictionaryapi.dev/media/pronunciations/en/second-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5347, 'Second', 3, '/ˈsɛkɪnd/', 'Number-two; following after the first one with nothing between them. The ordinal number corresponding to the cardinal number two.', '第二的、次要的、另一個的', 'https://api.dictionaryapi.dev/media/pronunciations/en/second-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5348, 'secondary', 3, '/ˈsɛkənd(ə)ɹɪ/', 'Next in order to the first or primary; of second place in origin, rank, etc.', '次要的、中等的、輔助的', 'https://api.dictionaryapi.dev/media/pronunciations/en/secondary-us.mp3', 1, '2026-06-01 14:48:14'),
(5349, 'secret', 1, '/ˈsiːkɹət/', 'A piece of knowledge that is hidden and intended to be kept hidden.', '秘密、奧秘', 'https://api.dictionaryapi.dev/media/pronunciations/en/secret-us.mp3', 1, '2026-06-01 14:48:14'),
(5350, 'secret', 3, '/ˈsiːkɹət/', 'Being or kept hidden.', '秘密的、機密的、隱密的', 'https://api.dictionaryapi.dev/media/pronunciations/en/secret-us.mp3', 1, '2026-06-01 14:48:14'),
(5351, 'secretary', 1, '/ˈsɛk.ɹə.tɹi/', 'Someone entrusted with a secret; a confidant.', '秘書、書記、大臣', 'https://api.dictionaryapi.dev/media/pronunciations/en/secretary-us.mp3', 1, '2026-06-01 14:48:14'),
(5352, 'section', 1, '/ˈsɛkʃən/', 'A cutting; a part cut out from the rest of something.', '切片、部分、部門、階層', 'https://api.dictionaryapi.dev/media/pronunciations/en/section-us.mp3', 1, '2026-06-01 14:48:14'),
(5353, 'secular', 3, '/ˈsɛkjʊlə/', 'Not specifically religious; lay or civil, as opposed to clerical.', '世俗的、非宗教的', 'https://api.dictionaryapi.dev/media/pronunciations/en/secular-us.mp3', 1, '2026-06-01 14:48:14'),
(5354, 'secure', 3, '/səˈkjɔː(ɹ)/', 'Free from attack or danger; protected.', '安全的、穩固的、有把握的', 'https://api.dictionaryapi.dev/media/pronunciations/en/secure-us.mp3', 1, '2026-06-01 14:48:14'),
(5355, 'security', 1, '/sɪˈkjɔːɹəti/', 'The condition of not being threatened, especially physically, psychologically, emotionally, or financially.', '安全、保安、保障、證券', 'https://api.dictionaryapi.dev/media/pronunciations/en/security-us.mp3', 1, '2026-06-01 14:48:14'),
(5356, 'seduce', 2, '/sɪˈdjuːs/', 'To beguile or lure (someone) away from duty, accepted principles, or proper conduct; to lead astray.', '引誘、誘惑、勾引', 'https://api.dictionaryapi.dev/media/pronunciations/en/seduce-uk.mp3', 1, '2026-06-01 14:48:14'),
(5357, 'seek', 2, '/siːk/', 'To try to find; to look for; to search for.', '尋找、尋求、請求', 'https://api.dictionaryapi.dev/media/pronunciations/en/seek-us.mp3', 1, '2026-06-01 14:48:14'),
(5358, 'seem', 2, '/siːm/', 'To appear; to look outwardly; to be perceived as.', '似乎、好像、顯得', 'https://api.dictionaryapi.dev/media/pronunciations/en/seem-us.mp3', 1, '2026-06-01 14:48:14'),
(5359, 'seemingly', 4, '/ˈsiːmɪŋli/', 'As it appears; apparently.', '表面上、看來', 'https://api.dictionaryapi.dev/media/pronunciations/en/seemingly-us.mp3', 1, '2026-06-01 14:48:14'),
(5360, 'segregate', 2, '', 'To separate, especially by social policies that directly or indirectly keep races or ethnic groups apart.', '隔離、分開、使分離', 'https://dictionaryapi.dev/segregate', 1, '2026-06-01 14:48:14'),
(5361, 'seize', 2, '/siːz/', 'To deliberately take hold of; to grab or capture.', '抓住、奪取、沒收、利用', 'https://api.dictionaryapi.dev/media/pronunciations/en/seize-us.mp3', 1, '2026-06-01 14:48:14'),
(5362, 'seldom', 4, '/ˈsɛldəm/', 'Infrequently, rarely.', '很少、不常', 'https://api.dictionaryapi.dev/media/pronunciations/en/seldom-us.mp3', 1, '2026-06-01 14:48:14'),
(5363, 'select', 2, '/sɪˈlɛkt/', 'To choose one or more elements of a set, especially a set of options.', '選擇、挑選、選拔', 'https://api.dictionaryapi.dev/media/pronunciations/en/select-uk.mp3', 1, '2026-06-01 14:48:14'),
(5364, 'selection', 1, '/səˈlɛkʃən/', 'A process by which heritable traits conferring survival and reproductive advantage to individuals, or related individuals, tend to be passed on to succeeding generations and become more frequent in a population, whereas other less favourable traits tend to become eliminated; the differential survival and reproduction of phenotypes.', '選擇、挑選、精選品', 'https://api.dictionaryapi.dev/media/pronunciations/en/selection-us.mp3', 1, '2026-06-01 14:48:14'),
(5365, 'selfish', 3, '/ˈsɛlfɪʃ/', 'Holding one\'s own self-interest as the standard for decision making.', '自私的', 'https://api.dictionaryapi.dev/media/pronunciations/en/selfish-us.mp3', 1, '2026-06-01 14:48:14'),
(5366, 'sell', 2, '/sɛl/', '(ditransitive) To transfer goods or provide services in exchange for money.', '賣、出售、推銷', 'https://api.dictionaryapi.dev/media/pronunciations/en/sell-us.mp3', 1, '2026-06-01 14:48:14'),
(5367, 'semester', 1, '/sɪˈmɛstə/', 'Half of a school year or academic year such as fall or spring semester.', '學期', 'https://dictionaryapi.dev/semester', 1, '2026-06-01 14:48:14'),
(5368, 'seminar', 1, '', 'A class held for advanced studies in which students meet regularly to discuss original research, under the guidance of a professor.', '研討會、專題討論會', 'https://dictionaryapi.dev/seminar', 1, '2026-06-01 14:48:14'),
(5369, 'send', 2, '/sɛnd/', 'To make something (such as an object or message) go from one place to another.', '發送、寄、派遣、把...打發走', 'https://api.dictionaryapi.dev/media/pronunciations/en/send-uk.mp3', 1, '2026-06-01 14:48:14'),
(5370, 'sensation', 1, '/sɛnˈseɪʃən/', 'A physical feeling or perception from something that comes into contact with the body; something sensed.', '感覺、知覺、轟動、轟動一時的事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/sensation-us.mp3', 1, '2026-06-01 14:48:14'),
(5371, 'sense', 1, '/sɛn(t)s/', 'Any of the manners by which living beings perceive the physical world: for humans sight, smell, hearing, touch, taste.', '感官、感覺、意識、理智', 'https://api.dictionaryapi.dev/media/pronunciations/en/sense-uk.mp3', 1, '2026-06-01 14:48:14'),
(5372, 'sense', 2, '/sɛn(t)s/', 'To use biological senses: to either see, hear, smell, taste, or feel.', '感覺到、意識到', 'https://api.dictionaryapi.dev/media/pronunciations/en/sense-uk.mp3', 1, '2026-06-01 14:48:14'),
