(6239, 'traveler', 1, '/ˈtɹæv.l̩.ɚ/', 'A member of a particular nomadic ethnic minority in Ireland, the Pavee.', '旅客、旅行者', 'https://api.dictionaryapi.dev/media/pronunciations/en/traveler-us.mp3', 1, '2026-06-01 14:48:14'),
(6240, 'traverse', 2, '/tɹəˈvɜːs/', 'To travel across, often under difficult conditions.', '橫越、穿過', 'https://api.dictionaryapi.dev/media/pronunciations/en/traverse-uk.mp3', 1, '2026-06-01 14:48:14'),
(6241, 'tray', 1, '/tɹeɪ/', 'A small, typically rectangular or round, flat, and rigid object upon which things are carried.', '托盤、盤子', 'https://api.dictionaryapi.dev/media/pronunciations/en/tray-us.mp3', 1, '2026-06-01 14:48:14'),
(6242, 'treasure', 1, '/ˈtɹɛʒə/', 'A collection of valuable things; accumulated wealth; a stock of money, jewels, etc.', '寶藏、財寶', 'https://api.dictionaryapi.dev/media/pronunciations/en/treasure-us.mp3', 1, '2026-06-01 14:48:14'),
(6243, 'treasure', 2, '/ˈtɹɛʒə/', '(of a person or thing) To consider to be precious; to value highly.', '珍視、珍藏', 'https://api.dictionaryapi.dev/media/pronunciations/en/treasure-us.mp3', 1, '2026-06-01 14:48:14'),
(6244, 'treat', 1, '/tɹiːt/', 'An entertainment, outing, food, drink, or other indulgence provided by someone for the enjoyment of others.', '款待、請客、樂事', 'https://api.dictionaryapi.dev/media/pronunciations/en/treat-us.mp3', 1, '2026-06-01 14:48:14'),
(6245, 'treat', 2, '/tɹiːt/', 'To negotiate, discuss terms, bargain (for or with).', '對待、治療、款待、看待', 'https://api.dictionaryapi.dev/media/pronunciations/en/treat-us.mp3', 1, '2026-06-01 14:48:14'),
(6246, 'tree', 1, '/tɹiː/', 'Fast growing function based on Kruskal\'s tree theorem.', '樹、樹木', 'https://api.dictionaryapi.dev/media/pronunciations/en/tree-uk.mp3', 1, '2026-06-01 14:48:14'),
(6247, 'tremble', 1, '/ˈtɹɛmbl̩/', 'A shake, quiver, or vibration.', '顫抖、發抖', 'https://dictionaryapi.dev/tremble', 1, '2026-06-01 14:48:14'),
(6248, 'tremble', 2, '/ˈtɹɛmbl̩/', 'To shake, quiver, or vibrate.', '顫抖、發抖、搖晃', 'https://dictionaryapi.dev/tremble', 1, '2026-06-01 14:48:14'),
(6249, 'tremendous', 3, '/tɹəˈmɛndəs/', 'Awe-inspiring; terrific.', '巨大的、極大的、極好的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tremendous-us.mp3', 1, '2026-06-01 14:48:14'),
