(6522, 'warn', 2, '/wɔːn/', 'To make (someone) aware of (something impending); especially:', '警告、告誡、提醒', 'https://dictionaryapi.dev/warn', 1, '2026-06-01 14:48:14'),
(6523, 'warning', 1, '/ˈwɔːnɪŋ/', 'The action of the verb warn; an instance of warning someone.', '警告、預兆、警報', 'https://api.dictionaryapi.dev/media/pronunciations/en/warning-us.mp3', 1, '2026-06-01 14:48:14'),
